/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170313-3","meetingId":"h29-c-budget","date":"2017年3月13日","dateIso":"2017-03-13","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件整理しています。","topics":[{"id":"topic-01","title":"平成２９年度品川区一般会計予算","agenda":"平成２９年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２８９ページ、カラス・外来種対策事業の中のカラス対策と外来種のことについてお伺いいたします。初めに、カラス、それと外来種についてお伺いいたします。","respondent":"三ツ橋環境課長","answer":"対策です、カラスの巣の撤去、また外来種などの箱穴設置などに向けて対応しております。今までは、直接環境課が受け付けておりましたけれども、それを一手に業務委託をして窓口受付をしております。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３月から６月の時期までなのかということをお知らせいただきたいのと、ハクビシンなのですけれども、電線を伝って歩行しているということがあります。箱穴の設置件数が２０件、保護件数が３件ということなのですけれども、今現在わかっている数字があれば教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"やはり３月、４月、５月あたりまでがかなり区としての相談件数は多くなっております。箱穴設置数が１１件、平成２７年度も捕獲件数は３件となっておりますので、大体昨年並みとなっております。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、しながわ百景についてお伺いいたします。本年新しくなったということで、この取組みというか、この作成の内容をどういうふうに事業としてやっていくのかお知らせほしいと求めました。","respondent":"鈴木文化観光課長","answer":"予算を８００万円ほど計上させていただきまして、それを見ながら各スポットを回っていただけるような、歩きながら使える地図を想定しております。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"主要なスポットが約１０カ所あるということで、しながわ百景以外に一部の文化財、その辺のこともお聞かせほしいと求めました。たしか４０周年のときに、それも含めて新しくそういったプレートもこれから設置をするのかどうか、お聞かせほしいと求めました。","respondent":"中島企画部副参事、中元広報広聴課長","answer":"ＡＲ技術（拡張現実）というＩＣＴ技術を活用いたしましてＰＲをしてまいりますが、その主要なスポット１０カ所程度で撮影スポットを考えております。今回、歴史や懐かしさを感じる品川ならではの風景を選びまして… しながわ百景で新しく選びましたプレートの件ですけれども、そちらも現地の方、施設管理者の方と調整をさせていただいて、できる限りプレートをつける形で検討しています。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１２カ所増えたと思うのですけれども、その１２カ所は全部プレートを設置を検討していくのかどうか、そこだけお知らせほしいと求めました。","respondent":"中元広報広聴課長","answer":"１２カ所につきましては、こちらとしては検討しています。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問・要望","question":"２９１ページ、３０５ページ、都市型観光プラン推進事業について伺っていきたいと思います。２月８日更新で、これはかねてより要望しておりましたけれども、一般財団法人日本ＡＥＤ財団のリンクが張られました。","respondent":"川島健康課長","answer":"そういった普及啓発につながるのではないかということで、早速、リンクを張らせていただいたところです。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな区民相談も含めて要望があって、要望はさせていただいていたということで、その中に「心止村湯けむり事件簿」というのが入っております。そうした心構えができるような意味からも、やはり常に携行できるものは必要かと思うのですが、アプリの活用とあわせて考え方を説明を求めました。","respondent":"川島健康課長","answer":"それからスマホや携帯といった新しいものの活用については、引き続き、防災課と連携しまして検討していきたいと考えています。その辺のご紹介も我々の役目だと考えていますので、今後、検討してまいりたいと考えています。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"これは国会の場でも公明党の委員からも厚生労働大臣に対して求めてはいるのですが、改めて根拠とかも含めて提案できればと考えています。品川区はもう既に産後ケア事業を行っていらっしゃるわけですから、もう既に予算の中に反映されているのであれば教えてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"予算の計上は今はまだ行われておりません。考え方につきましては、１４回分の公費助成を行っておりますので、他区の動向および今後出される国の事業の詳細の内容について注視してまいります。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"次に移りますが、これまでも質問等させていただいて、都へ働きかけるなどということで体制をしっかりつくってほしいということで求めてまいりました。早期療育のために、区としても積極的にその体制の充実を東京都に求めるべきかと思いますが、現在の働きかけの状況等を含めて説明を求めました。","respondent":"太田品川保健センター所長","answer":"現在、衛生主幹部長会および衛生主幹課長会で医療機関での実施状況等について調査を行っているところであります。その結果が出たところで、そちらの状況を見て品川区としての方針を決めていきたいと考えています。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"質疑の中でも伺っておりますが、素早くそういう体制がとられるように、今後も強力に推進してほしいと求めました。補正のときにもちょっと伺ったのですが、改めて、平成２８年度の日帰りのケア、それからホテルの利用状況を説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"６月から開始したわけですが、６月から２月までで、約８０名の方が利用されました。大変満足ですということで、貴重な体験ができたということで、非常に満足度の高いサービスになっております。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"ホテルを使って、宿泊型についても教えてください。失礼しました。","respondent":"太田品川保健センター所長","answer":"１１月から予約を開始し、１２月から宿泊を行いまして、２月末で１６件の利用が行われている状況であります。母子同室で、不規則な生活へのイメージが持てたとか、今後の子育てに自信が持てた等の利用者にとっては大変満足度の高い結果が得られております。","id":"exchange-011"},{"speaker":"つる委員","kind":"確認","question":"確認でした。数字を改めて伺ったのですが、前回も確認しましたが、このあたりについての考え方を説明を求めました。","respondent":"榎本荏原保健センター所長、太田品川保健センター所長","answer":"三カ月頃の経産婦については、来年度は、第二子以降の出産の経産婦も対象を加えていく予定です。対象を考えていたのですが、里帰りをしてご利用される方も４３％ぐらいございましたので、４カ月未満ということで拡大をしていく予定です。 宿泊型に関しては、やはり産後うつになられた方の８割が初産婦であったということから、初産婦の方を対象にと考えています。上のお子さんは預かれないということですので、そういうことからも初産婦の方を対象にしたいと考えています。","id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"２回ほど提案も含めてさせていただいたものでありますが、それに加えて、発展途上国の支援にもつながるという取組みを紹介させていただきました。そうしたことを取り組んでいく中で、もったいないプロジェクトの拡充を検討されてはどうかと思いますが、まずこのあたりの考え方を説明を求めました。","respondent":"三ツ橋環境課長","answer":"例えば、３０１０運動ですとか、また、食品ロス削減につきましては、そのほかの「食べきりげんまんプロジェクト」などを東京都もやっております。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"その辺もしっかりと詳細に検討していただきながら、積極的にドギーバッグの検討をしてほしいと求めました。さまざまな観点からも非常にいい取組みかと思いますので、ぜひそうした環境においても先進区である品川区が積極的に検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"３０９ページ、取り上げてきた住宅リフォーム助成の店舗版の実現と、商店街イベント告知チラシ補助制度改善を伺いたいと思います。区はこれまで融資制度を利用と説明しておりますが、より積極的に補助制度導入へとレベルアップを求めますが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"私ども区といたしましては、商店街に対しましての助成、支援につきましては、さまざま対応しています。年間３００件ほど多く利用する中で、多く活用され、ニーズに応えさせていただいているというような状況です。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"こうした業態が活気にあふれていなければ、品川区の継続的な発展はなし得ないと、中小企業と商店街を積極的に位置づけていると思います。なぜ中小企業や商店に対しては、いわゆる融資制度で十分だと考えるのか、その理由を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"ゾーンとしての商店街のにぎわいを確保するため、区としては、これまで産業の分野において支援をしてきたところです。ゾーンとしての支援、中小企業であれば、そうしたさまざまな条件に基づいて補助制度を構築しているというような考えです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうして中小企業や商店街に対しては無利子融資での税金投入はありますけれども、再開発とは何がどう違うのか、この点も伺いたいと思います。ぜひ中小企業や商店街の内装や外装に補助制度を導入することを改めて強く求めますけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"産業支援と再開発で一概に比較してというようなことは少し難しいご質問かとは思いますが、さまざま、いろいろな分野で区としての支援メニューを構築しているというような考え方です。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"地元の仕事づくりにもつながるという地域経済への貢献にもつながると思いますけれども、この点も伺いたいと思います。まずこの事実を伺いたいのと、東京都に改善を求めているということですけれども、あわせて伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"根っこの部分は、繰り返しになりますが、行政として自治法の規定に基づいて、補助、助成をする、それぞれの分野で対応しているというようなことです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"商店街や中小企業はとても地域経済に貢献していると思います。とりわけ経済の多くは個人消費ですから、そこをしっかりと見ていただいて、実施を改めて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"平成３０年以降には、これは利用者からお伺いした話なのですが、ＪＲ西大井駅の公衆トイレを利用する方のお話です。そういったものをしっかりやるべきであって、それは連携をとっているわけですから、どういう動きになっているかということをやるべきではないかと。","respondent":"溝口公園課長、鈴木文化観光課長、中元広報広聴課長","answer":"続きまして、西大井駅前の公衆便所につきましては、設置からもう３０年以上経過して古くなっているという認識があります。ただ… 設置箇所数と今後の予定ですが、実はこの事業は東京都の補助金を利用する事業でございまして、平成２９年度は２カ所を予定しております。… こちらは主に区有施設内にデジタルサイネージを設置いたしまして、イベント、更新を可能とするシステム基盤の構築を検討しているものです。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これは５件の見積もりになっているのですけれども、可能性はあるわけですから、緑化を進めていくよう努力をしてほしいと求めました。しっかり連携をとっているわけですから、本当に連携がとれているという部分ではないかと考えていますので、その辺をどうお考えか説明を求めました。","respondent":"鈴木文化観光課長","answer":"当然、品川区の観光のＰＲも兼ねて、サンリオのほうで情報発信をしていただくようにお願いをしたいと思います。既にサンリオのほうでも取り組んでいただいていまして、サンリオの「いちご新聞」などで紹介をしていただいております。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、総合点で３位ということにはならない可能性があります。ですから、１回立ちどまって考えていただきたいのですけれども、品川区のお考えはいかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"したがいまして、委員ご指摘のように、さまざまな要因が考えられますので、それは政府として考えていることだと思います。しかしながら、品川区として影響がある場合には、国に申し伝えてまいります。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、しっかりとこうした品川区は都市型観光プランとして舟運事業、水辺活用を非常に重視している。したがって、ぜひとも国土交通省にお伝えしていただきたいのですけれども、品川区のお考えはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"しかし、今、区に対する影響があるというところで、これは国に対して対応を求めているところです。ただ、やはり品川区として影響があるというところにつきましては、必要な対応について国に強く求めてまいるというふうに考えているところです。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"国土交通省は、品川区は都市型観光プランとして、舟運事業や水辺活用事業を重視しているということはご存じなのか尋ねました。","respondent":"中村都市計画課長","answer":"今回、国からこのルート案が示された時点で、品川区としてさまざまな考えを伝えております。委員がおっしゃいました国への要望、これは引き続き強く求めていきたいというふうに考えております。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"いわゆる成羽新線、これが実現されれば５９分で成田空港と羽田空港を結ぶことができますので、成羽新線を実現させる。ほかの代替案をしっかりと考えるべきだと考えていますし、そういったことを伝えるべきだと考えておりますけれども、お考えはいかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"すみません、新ルートに関連して、舟運の観光についてのお話をいただいていますので、ちょっと補足をします。その船に乗って低空を飛ぶ、全て飛行機の新ルートが観光に、舟運に悪い影響が出るというものではないというところをご認識いただければと思います。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"アンケートもしっかりとっていただきたいのですけれども、ぜひ区民の皆様の声をとっていってほしいと求めましたけれども、その辺はいかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"飛行機を見たい方は水辺で特に羽田方面というように、それぞれ訪れる方のお好みとか希望に合わせたコースを用意して、多くの方に楽しんでいただければというふうに考えております。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"こちらの事情は考慮せず、１５時から１９時に一方的に通ってしまう可能性が大きいものですから、とにかく飛ばないに越したことはないのですから。成羽新線と大崎－成田のバス路線についてのお考えはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"他都市との連携、こういったものそれぞれについて重要だと考えております。これは国に対してしっかりと要望してまいりますけれども、公共交通の拡充、こういったものも並行して進めていくべきだと考えております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも国土交通省に１回立ちどまって考えていただきたいということで、しっかりと品川区の状況をお示ししていただきたいと考えております。新ルート案で考えられることは、今の段階で反対の表明を品川区として行っていくべきだと考えておりますけれども、その点はいかがか尋ねました。","respondent":"中村都市計画課長","answer":"その他メリット、デメリット、こういったものもさまざまな角度から検討する必要があると考えております。今現在はまだ区としましては、国に対して必要な情報を求めているというところで、これを継続して行うことが重要だと考えております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"意見","question":"向こうの対応次第では反対の表明をすべきだと考えておりますので、ぜひともその点、よろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"横山委員","kind":"確認","question":"１点目は、乳がん検診についてお伺いいたします。先日、たけうち委員より、乳がん検診に関する質問がありましたが、まず初めに、乳がん検診率の推移について、最近の傾向を確認させてください。","respondent":"川島健康課長","answer":"平成２５年度と平成２６年度が１９.３％、平成２７年度が大幅に伸びまして２５.２％ということで、そういった受診環境などの整備に努めてまいりたいと考えております。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"そこで、授乳期と断乳後６カ月未満の方の乳がん検診について、現在の区の状況を教えてください。３７歳、次の検診の前に受診をしていただきたいと考えているのですけれども、区のご所見を説明を求めました。","respondent":"川島健康課長","answer":"委員お尋ねの授乳期、断乳後６カ月未満の方の乳がん検診の対応ですが、乳腺外科のご受診をということを今はお勧めしています。ただ、その翌年にまた検診を受けられる期間が来てしまいますので、そのときは間隔をなるべく１年以上あけるようにといったご案内をしています。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"保健師、ネウボラ相談員への情報提供や、しながわパパママ応援アプリへの掲載も含めて周知の徹底を要望させてほしいと求めました。その先にある区民の健康につながっていくと考えておりますので、この辺、ご答弁をお願いいたします。","respondent":"川島健康課長","answer":"今のご質問にあったようなご案内の徹底というところですが、どのようにしていけばいいのか、今後引き続き努力してまいりたいと考えています。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目は、不妊治療助成についてお伺いいたします。学校教師、保健師を対象とした講演会の事例をご紹介いただきながら、男性不妊症の意識改革と文化をつくっていくことの必要性を伺いました。","respondent":"川島健康課長","answer":"それから、どうしたら男性不妊に関する啓発のあり方がよいのかというようなところも含めて周知に努めてまいりたいと考えています。平成２７年度が１７０組、平成２８年度が１０７組という、こちらも１月末現在までです。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"なかなかプライドというのですか、学べるような、そういった機会を増やしていただけたらというところで要望をします。我が会派の沢田委員より、世界各国のＩＴベンチャー企業の共同によるホスピタリティハウスを五反田・大崎地域に誘致してはいかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長、山崎商業・ものづくり課長","answer":"ホスピタリティハウスにつきましては、国、地域のみならず、企業にとっても情報発信やＰＲの絶好の機会だということは、リオの視察で確認しています。適地調査費用も入っているところですので、委員のご指摘の趣旨も踏まえつつ… これから取り組む予定の商店街ならびに産業関連の国際化推進事業などにつきまして、さまざま展開している産業関連資源との連携について、これから研究してまいります。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"今、品川区はいろいろ動いてくださっていると思うのですけれども、そういった視点であらゆる可能性をぜひ探っていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"３０３ページ、もう１つが、しながわみやげについて伺いたいと思います。大震災等の際に、公衆便所が果たす役割と耐震化の状況について説明を求めました。","respondent":"溝口公園課長","answer":"トイレの災害時の対応ですが、または地下にピットを設けて災害時に対応している、そういったものをやっているものです。設置したものが古くて、なかなか災害時の対応まで行っておりませんが、災害時のマンホールトイレまたは地下にピットを設けて災害時対応できる。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"全体の中で１つのトイレにおいて１基は洋式化をすると、３１％だということでしたけれども、特に東京都としての目標は求めていない。品川区は今後どのようにお考えになっているのか、安全性についてはまた伺いますので、そこについて説明を求めました。","respondent":"溝口公園課長","answer":"特別清掃、特別な薬品を使って清掃するなど、そういったことを対応しながらやってきているものです。公衆便所を利用しやすい、また利用していただけるような環境については、今後も引き続き努めていきたいと考えているものです。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひそこを進めていってほしいと求めましたし、あと、安全の面です。やはりどうしても女性の場合、品川区の現状についてお伺いしたいのと、そこについてどのようにお考えなのか説明を求めました。","respondent":"溝口公園課長","answer":"トイレの利用頻度、そういったものを勘案しながら、安全なトイレになるように努めていきたいと考えているものです。引き続き、品川区のトイレが利用しやすい効果的なＰＲ方法については検討していきたいと考えているものです。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"項目がないので、がん検診に関連して伺います。今後、品川区としてもアピアランスの支援ということも考えていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"川島健康課長","answer":"がん患者が社会生活を送る上での有効な支援策の１つというふうに考えてあります。どういった形で区の施策に取り入れていけるのか、今後しっかり検討させていただきたいと思います。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"提案","question":"３０５ページ、議員になって１カ月後、６月の行財政改革特別委員会で初めてこれを求めてから１６回ほど質問をさせていただきました。もちろん優秀な品川区の皆さんですから、ぜひそういう職員の方の配置をお願いしたいと思うのですが、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"その情報もあわせながら、区として正式なフィルムコミッションの担当の部署を設置しまして、しっかりと調査やＰＲを進めていきたいと考えております。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ、これは要望になりますが、区民の方にボランティアでエキストラに参加をしていただくということをやっております。そこに区民の方が参加できるということが重要だと思いますので、ぜひこういったことも検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"最初に、３０５ページの第５款１項産業経済費から、就業支援費の中の就業支援事業を伺いたいと思います。継続して伺っておりますが、昨年もお尋ねしているのですが、その点だけ説明を求めました。","respondent":"立木産業活性化担当課長","answer":"子育て中の女性の就労相談の件ですけれども、今現在も引き続き検討している最中です。来られない方に対しての相談ということで、出張相談も来年度検討させていただきたいというところで、今さまざまな角度から検討している最中です。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"どのような趣旨での増額か伺いたいと思います。どういう調査なのか尋ねました。","respondent":"三ツ橋環境課長","answer":"こちらは６００ｍメッシュを切って、それぞれ約５０カ所の地点を騒音調査していく予定です。吉田委員のご指摘の屋上の部分に設置という部分ですけれども、例えば、区役所の屋上などを考えております。","id":"exchange-043"},{"speaker":"吉田委員","kind":"確認","question":"それを１点確認させてください。少なくとも高層ビルの調査は必要なのではないかと思いますが、その辺はどのようにお考えか説明を求めました。","respondent":"三ツ橋環境課長","answer":"国がどのように考えていくのか、そちらは注視していきながら、区としてどのような部分がいいのかは対応してまいります。確かに委員おっしゃるように、そちらの部分に関しては、いろいろ情報を仕入れながら国からの情報を伺いながら対応してまいりたいと考えています。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"今まで私たち、院内集会で確認したところでも、まだ決定ではない。その辺、もう一度確認させてください。","respondent":"三ツ橋環境課長","answer":"騒音や安全面などに向けて、区として対応していかなければならない問題だと考えております。丁寧な説明、また区民に対する説明会なども実施を要望してまいりますので、区民の皆様の不安払拭に向けて対応してまいります。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"決定ではないということを確認させていただきました。次に、２９７ページ、３項清掃費、１目清掃総務費の東京二十三区清掃一部事務組合分担金について伺います。","respondent":"小林品川区清掃事務所長","answer":"それで割り返しまして分担して支出しているというのが基本的な構造です。毎月大体１億円、来年はそれが総経費で年間１億円ほど増加している、各区の分担金が増加しています。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"搬入しているごみの量が、この分担金に関係してくるということであれば、例えば、区民がごみの減量をするとか、もったいないプロジェクトとかもありますから、そういうことで減っていけば、これは減らすことができると考えてよろしいのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"ただ、基本的に大きく変わることができませんので、短期的にすぐに各区のごみ量の増減で変わってくるというものではございません。全体の量を各区で按分しておりますので、経年変化の中では、例えば隣の区よりも品川区の分担金が減るというような影響はあろうかと思います。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"これ、ＪＩＣＡから受託した事業の視察ということであれば、その予算もＪＩＣＡから出ているのでしょうか。それとも各区の分担金から出るのか、それを説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"国際協力事業として取り組む場合に、その経費につきましては、清掃事業として費用を持ち出しているというものではありません。職員の人件費等については別ですので、各区の中から持っている人材でご協力をして、国際協力の視点から事業にかかわっているところです。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"ＪＩＣＡからの受託事業本体はわかります。この視察に関しての、それも受託の中に含まれての視察なのか、それとも独自の分担金で行くものなのか、それを伺いたいのです。","respondent":"小林品川区清掃事務所長","answer":"マレーシアとの協力で、現地に職員が行ったりしておりますけれども、それについては国際協力の経費です。今回、かかわりがあるのかないのかと言われれば、分担金の対象になっているというふうに理解しております。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"その事業内容をここで質問しても、分担金を出す以上、区としても区民に対して説明責任があるというふうに考えます。この視察の趣旨と意義を把握していらっしゃるのかということを伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"一義的に一部事務組合として取り組むものについてご説明する立場にはないので、十分な情報を持ち合わせてはおりません。そういう責任が一組として、今回、最終的な成果の検証の一環として計画されたというふうに聞き及んでおります。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"この方向が進むかどうかだけ確認させてください。これはつけるべきところはみんな終わったということで、新たにそういう施設があれば、またということで考えてよろしいのか尋ねました。","respondent":"三ツ橋環境課長","answer":"三計画改訂の進捗状況ですけれども、今年度につきましては、各課へのアンケート、また区民の皆様へのアンケートを集約しておりまして、方向性といたしましては、今後、三計画を整合性をとりながら改訂してまいります。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"保健師の配置状況を教えてください。保健所、保健センターの総数、また、その他の課のところの事業に配置されている人数を、わかる範囲でいいです、それぞれ説明を求めました。","respondent":"太田品川保健センター所長","answer":"うち１名が短時間再任用ということになります。国保医療年金課に１名、保健予防課に４名、保健センターには２９名配属となっております。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１人の担当が約１万人弱だったのですけれども、その後５年間で２万５,０００人の人口増となっていますけれども、変化はないのでしょうか。高齢者、子ども、障害者の事業への保健師の配置が求められていると思いますが、この辺の認識はいかがか尋ねました。","respondent":"太田品川保健センター所長","answer":"健康なまちづくりを進めるために、危機管理対策など、いろいろな分野で保健師の活動が期待されているところだと認識しております。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当にいろいろな分野で健康を守っていくという立場で保健師の役割が求められてきています。保健所、保健センター、増員が求められますけれども、現場職員の意見を取り入れて、こういった面、改善が必要であると思いますが、いかがか尋ねました。","respondent":"太田品川保健センター所長","answer":"保健師の業務につきましては、どんな仕事もそうですが、緊急性の高い仕事に優先順位を高くして行っております。いろいろな虐待等、養育困難に陥った家庭への支援等におきましても、保健師１人でやるというのではなく、関係各課と協力して行っているところです。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"どういった方向で新しい施策を立てていくことが区民の健康増進につながるのかといった、そういった大きなところでプランをつくっていると思うのですけれども、そういった中身になっていると思われているのか尋ねました。","respondent":"川島健康課長","answer":"ただいまご紹介いただきました健康プランを健康課のほうでつくっているということです。保健師のご協力をいただいて仕事を進めているようなことですので、保健センター、全て連携した上で話を取り入れてつくっていっております。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私、さっき確認しましたが、平成２５年のときから増えていないではないですか。保健センターのところの増員を求めましたけれども、増員を求めていますので、明確に、答えるよう求めました。","respondent":"米田人事課長","answer":"この間、人数的にはあまり変わっていないかもしれませんけれども、非常勤職員の活用等を含めて、事業には対応しているというふうに考えてあります。来年度の４月１日に向けて、委員のご要請と人数に乖離はあるかもしれませんが、一定の確保を図っているところです。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして、昨年、文教委員会で名古屋市に視察に伺いました。ぜひ予算を組んで、予防啓発パンフレット、そしてハンドブックをこの品川区でもつくってほしいと求めましたが、いかがか尋ねました。","respondent":"舟木保健予防課長","answer":"それにつきましては、来年度も継続します。それについては、連携しながら検討していければと思っているところです。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"経験の長い方が退職していく中での今後の業務維持とか発展のために早期に採用し育成、育成のところが必要ではないかということを訴えました。パンフレット、ハンドブックのところは、ぜひ教育委員会、子どもの頃からのところも、ぜひ力を入れて、前向きに連携強化してほしいと求めました。","respondent":"太田品川保健センター所長","answer":"保健師の育成については、心がけてまいります。","id":"exchange-058"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２７５ページの感染症対策費、２７７ページの健康診査、２８１ページの出産・子育て応援事業について質問します。平成２６年１０月に定期接種となった水痘ワクチンの接種率の推移と、もう一度、補正に引き続いてご説明をお願いします。","respondent":"舟木保健予防課長","answer":"任意接種を実施してはいたのですが、１回助成という形でやっておりましたので、平成２５年で３,０００人弱の方が助成を受けておりました。平成２８年は、今の接種状況から想定しますと、年度末までに大体９９％前後までいくのではないかと思っているところです。","id":"exchange-059"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今現在１００％近くなっている、１００％だというご説明があったのですが、個人防衛の点以外にも非常に重要な役割があると思われます。その点についてご説明をお願いします。","respondent":"舟木保健予防課長","answer":"非常に感染力が強いということで、院内感染とかでも非常に問題となっているような状況です。そういう意味では、そういうふうに重症化リスクの高い方を水痘から守る、そういうような効果もあるのではないかと考えています。","id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"水痘ワクチンの接種率の向上のさらなる向上と維持、区としてもしっかりと取り組むように要望いたしまして、次の質問に移ります。梅毒の流行の状況と、現在の流行はいつからどのようにして始まったのか、まずご説明をお願いしたいと思います。","respondent":"舟木保健予防課長","answer":"報告数が継続して増加するような状況となりまして、２０１６年（平成２８年）は、４,５１８例と急増しているような状況です。多い世代としましては、男性では２０代から４０代、女性では２０代というふうな形で、男女とも増加しているような状況です。","id":"exchange-061"},{"speaker":"鈴木（博）委員","kind":"質問","question":"全数報告対象５類疾患に属しているために、今現在の４,０００例が、患者数がいるのではないかと言われています。そもそも梅毒はどういう病気なのか、あるいは非常に問題になる先天梅毒について、簡単にご説明をお願いします。","respondent":"舟木保健予防課長","answer":"では、梅毒についての説明です。出生した場合も、さまざまな全身の症状を、奇形をはじめとして出るというふうに言われております。","id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"質問","question":"特に若い女性が今問題になっているのですが、母子感染を起こして子どもは流産（死産）、あるいは先天異常を伴った先天梅毒として生まれてきます。この大流行が始まっている梅毒に対して、どのような取組みをされているのか、ご説明をお願いします。","respondent":"舟木保健予防課長","answer":"月１回は、荏原保健センターで性感染症の検査を実施しておりますので、そちらは継続して実施しているような状況です。ＨＩＶの即日検査を年２回やっておりますので、梅毒についても、そういうときにあわせてこちらの啓発もやっていけたらと思っているところです。","id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"質問","question":"」というようなポスターの作成など、かなり必死さが伺われるような啓発活動を行っています。デング熱、チクングニア熱など、蚊媒介感染症に対する品川区の予防対策に関して、昨年に引き続いてお尋ねいたします。","respondent":"井浦生活衛生課長","answer":"平成２９年度は１万４,０００カ所さらに拡大しまして、私道の雨水マスも対象として、５月から１０月にかけて区内全域を４巡回する予定です。財源としまして、都の補助金２７０万円を予定しています。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"次に、成人眼科検診についてお伺いします。４０歳以上の眼科検診の実施を高齢者の健康寿命の延伸のために、再度ぜひ要望したいと思いますが、区のご見解はいかがか尋ねました。","respondent":"川島健康課長","answer":"委員ご指摘のとおり、この検診の重要性につきましては、十分認識しています。実施方法、それから関係機関との調整も含めて、少し具体的な研究をする時間をいただきたいと考えています。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後に、しながわネウボラネットワークに関して、医療との関連についてお伺いします。非常に大切だと思いますが、医療機関との連携に関しては、今どのように取り組まれているのか尋ねました。","respondent":"太田品川保健センター所長","answer":"両医師会につきましては、妊婦面接や産後ケア事業について、毎年、チラシ、ポスターを配布してご案内しております。年２回、保健センター保健師と妊産婦支援のネットワーク会議を、ハイリスク妊婦への支援を中心に行っております。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"意見","question":"私は医師会なのですけれども、一度もお誘いを受けたことがないのですが、なるべく医師会とか、いろいろな職種で顔の見える化を図るように、いろいろご配慮をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"松永委員","kind":"質問・要望","question":"質問に入ります前に、要望ですけれども、先日の防災フェアに行った際、中小企業センターの１階ロビーでは、伝統工芸実演会が行われておりました。３０５ページの若者・助成就業支援事業についてですが、この若者と女性に対して、こうした職人とのマッチングは行われているのか、あわせて伺います。","respondent":"山崎商業・ものづくり課長","answer":"就職をするような支援と違いまして、取り組んでいるものに対してものすごく愛着があったり、気持ちがあったりというような分野です。そうした取組みにも、区としましても一定理解をさせていただいて、支援をさせていただいているような状況です。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問・要望","question":"どういう形で支援をしているのか、ぜひお伺いしたいですが、我が会派の石田しんご委員から質疑があったと思います。なかなか難しいとは思いますが、ぜひ品川区でもそうした事業をご検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"それぞれの伝統工芸の方々が取り組まれていることそのものの販路の拡大ですとか、伝統的産業の振興についてご支援をさせていただいているところです。","id":"exchange-069"},{"speaker":"松永委員","kind":"質問・要望","question":"要望です。その理由について伺いたいということと、節水対策として自動で水が出る手洗い場にしていただきたいと思うのですが、ぜひご意見を説明を求めました。","respondent":"溝口公園課長","answer":"そういったところの考え方ですが、公園灯と足並みをそろえるような形で、既にＬＥＤ化に取り組んできているところです。環境にやさしい面でも、そういったものを配慮して公衆便所の維持管理に努めていきたいと考えているものです。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"私からは、２７７ページの胃がん内視鏡検診導入準備経費と、３０３ページ、中小企業センター等運営費の２つをお伺いしたいと思います。お伺いします。","respondent":"山崎商業・ものづくり課長","answer":"それぞれ講習室ですとか、パソコンを使ったプロジェクターでのイベントなどについては、そうした備品の貸出も行っているようなところです。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問","question":"予算をとりながら適切にということで、本年度、備品の予算でいきますと、貸出用備品等購入の項目になるのでしょうか、４５万円というようなところですが、この辺でどれぐらいの整備がされるのかお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"液晶プロジェクターが２台ありましたけれども、ちょうど私どもの２階の事務室の隣が大講習室で、１００人規模の事業を行う大きな部屋があります。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"では、次に、２７７ページ、胃がん内視鏡検診導入準備経費ですけれども、まず、この胃がん内視鏡の検診につきましての準備を始めるということで、自治体で胃がん内視鏡検診を実施するようになったことにつきましての背景、目的、初めにお伺いしたいと思います。","respondent":"川島健康課長","answer":"平成２８年２月に国の指針が一部改正されまして、自治体が実施するべき対策型検診としまして、胃の内視鏡検査が新規に追加されたという状況です。区では、この胃内視鏡検査について、できれば平成３０年度に導入できればということで、今回、導入経費を計上させていただいたです。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"国からの指針が理由ということかと思いますけれども、まずバリウムがこれまで主に実施をされてきたわけですが、この内視鏡検診の医学的なところで言うところのメリット、バリウムと比べてどういうものがあるのかというところをお伺いしたいと思います。","respondent":"川島健康課長","answer":"胃の内視鏡の導入の一番のメリットといいますか、長所になりますけれども、こちらは発見率が高くなるということで、胃がんがより見つかるであろうという、そういう期待があります。","id":"exchange-074"},{"speaker":"塚本委員","kind":"意見","question":"平成３０年度の実施に向けて、まず対象者はどういう人たちが対象となるのかというところと、費用負担の考え方です。費用負担についてはどのように考えているのか、まずこの２点を説明を求めました。","respondent":"川島健康課長","answer":"単純計算しますと４万２,０００人ということで、それで計算しますと１,３００人、１０％で見積もりますと４,２００人が受診対象になるです。これはこれからさまざまな検討を加えていく必要があるとは思うのですが、今現在、医療のほうで３割負担で受けますと。","id":"exchange-075"},{"speaker":"塚本委員","kind":"意見","question":"３割負担でいくというところで５,０００円から１万幾らというところがありましたが、これは保険適用で３割ということですけれども、これが１つの自己負担の考え方として捉えていいのかというところで説明を求めました。","respondent":"川島健康課長","answer":"今の併用についての考え、バリウムと内視鏡ですけれども、できれば内視鏡のほうに順次移行していきたいというような考え方が大きな考えです。それから、費用負担、それを見て適正な本人負担を幾らにするかということをこれから検討させていただければと考えています。","id":"exchange-076"},{"speaker":"塚本委員","kind":"意見","question":"１０％というところで言うと、４,２００人ぐらいの対象ということでしたけれども、最後に説明を求めました。","respondent":"川島健康課長","answer":"今、委員からご指摘いただきました体制が一番大きな問題というところで、現在、胃がんリスク検診をやっているのですけれども、そちらで精密検査ということで回される場合が約６０件程度ということでして、今後、関係機関とさまざま調整してまいりたいと考えています。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"ノロウィルス関係なのでしょうか、残念ながらやめているところもあれば、しっかりきっちりと指導に沿って開催をしたというところがあります。Ｗｉ－Ｆｉの活用を提唱いたしましたが、その後、動きはありますか尋ねました。","respondent":"井浦生活衛生課長、太田品川保健センター所長","answer":"新聞報道等も繰り返し出された関係で、町会長ですとか、あるいは学校施設から問い合わせがございました。啓発に努めまして、学校施設におきましても、もちつきによる食中毒等の発生は一切ございませんでした。１歳６カ月の問診で言葉が少ないとか、はっきり診断というところまではいきませんが、医療機関への紹介ということは行います。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"横も縦もそうですが、しっかりスクラムを組んで対処していくようなものを少しまとめられるといいのかと思うのですが、そのお考えをお聞きします。こういうことができますということを話し合う場であったり、勉強会とかというものをぜひつくってほしいと求めましたが、いかがか尋ねました。","respondent":"井浦生活衛生課長、太田品川保健センター所長、山崎商業・ものづくり課長","answer":"もちつきにつきましては、引き続きまして、季節のよき伝統行事ですので、大切にする方向で安全確保のための啓発に努めてまいります。 その点で我々の支援から漏れてしまうということはないとは思いますが、障害者福祉課を中心に、学校および就労にも向けて行っているところです。 ご商売の販路拡大なども含めて魅力ある観光資源の１つだということで対応しておりますので、商連も含めてやってまいりたいというふうに考えているものです。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"なかなかそこに行こうとしないという部分があるので、ここは大切なのだということは啓発をかなりしていただきたいと。せっかくの成長の機会を失ってしまうことになりますので、そこはタイミングをはかって、縦横のつながりをしっかりつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"渡部委員","kind":"確認","question":"３０６ページです、このたび新しく始まります事業承継支援について伺っていきますが、いわゆる対象業種拡大という言葉がたくさん出てきます。確認なのですが、このカタリストに限らず、さまざまな部門でそういう考えでよろしかったか尋ねました。","respondent":"立木産業活性化担当課長","answer":"４つの事業を考えておりまして、知的財産権取得支援、全業種で使えるような形に拡大するものです。","id":"exchange-081"},{"speaker":"渡部委員","kind":"質問・要望","question":"事務事業概要のほうも確認しますと、そして法務・知的財産権というふうに続いていると思いますが、１社で何回も活用があると思うのです。１６５回とか、活用に至るまでの経緯を僕が知らなかったので教えていただきたいのと、どのようなケースがあるのか説明を求めました。","respondent":"立木産業活性化担当課長","answer":"窓口での相談等から、もしくはパンフレット等でご覧になられた方は直接という形になるのですけれども、カタリストマネージャーがおります。商工相談員ですけれども、適切なスキルを持ったカタリストを派遣するというような形をとらせていただいております。","id":"exchange-082"},{"speaker":"渡部委員","kind":"質問","question":"２番目に相談内容の多いものが、融資についてとなっていたものですから、そういう意味なのか。例えば、そういうものに対してこういうことが起こっているのか、その辺の関係を説明を求めました。","respondent":"立木産業活性化担当課長","answer":"今、項目として８件２８回というふうに入ってあります融資・補助金活用の部分なのですけれども、主に活用いただいているのは補助金が多くあります。","id":"exchange-083"},{"speaker":"渡部委員","kind":"質問・要望","question":"事業承継支援のほうを伺ってまいります。１００年でしたか、いわゆる事業承継というものをどういうふうに捉えて、今回こういう支援が起こったのかというところを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"品川区の約２万社のうち、８６％に当たる企業が２０名以下の小規模事業所という特性があります。この事業承継支援事業については、区としては、今後取り組んでいくべき事業だということで開始をさせていただいているものです。","id":"exchange-084"},{"speaker":"渡部委員","kind":"質問・要望","question":"これから先、何とかこの制度を使って生き延びてほしいという言い方は変ですけれども、そのために有用な施策になると非常に期待はしています。これはそのようなときにも活用できる運転資金なのか、その２点を説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"事業承継支援事業が２年目に入りますので、経営の部分、会計業務などのスキルアップのためにやってまいりたいというふうには思っております。そういう意味では、そうしたところにも、お金の面でも事業承継の支援を広げさせていただいたという考えです。","id":"exchange-085"},{"speaker":"渡部委員","kind":"質問・要望","question":"それから、少しだけ時間があるので、この中小企業の景況という、１つだけ簡単に答えを教えていただければ結構です。これが何かあれば説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"やはり経済の動向に影響を受けるのは、小規模事業者だからこそ影響が大きいのかという側面があります。それゆえ、そうした数字の傾向が出ているのかなというふうには受けとめているところです。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２８９ページの環境三計画改訂等経費に関連して、地球温暖化対策について伺います。ひいてはＣＯ２削減について、何がどう変わるのか具体的に伺うとともに、なぜ改訂するのか経緯も伺います。","respondent":"三ツ橋環境課長","answer":"パリ協定ですけれども、２０１３年度比、２０３０年までに２６％のマイナスということを大きく国は掲げております。他区との状況を考えながら、また東京都の状況を考えながら、どのようにしていけばいいのか考えていくものです。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、この改訂の経緯については、パリ協定を受けて改訂していくということでよろしいのか尋ねました。","respondent":"三ツ橋環境課長","answer":"国がそれに基づいてＣＯ２の排出量などを考えております。区といたしましては、国の動向、また東京都の動向も踏まえながら考えているものです。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"公共施設についてはＣＯ２排出量削減目標があるのですけれども、つまりは業務、産業部門への削減目標はなぜないのか伺います。目標を定める必要があると思いますけれども、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"事業者は基本的に事業者独自が目標を掲げ、そしてＣＯ２削減については事業者みずからが対応していかなければならない問題です。区といたしましても、全体の地域推進計画の中でマイナス２５％と考えておりますので、事業者に対してはいろいろな経営支援セミナーなどを通じて。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"指導しているということですけれども、やはり品川区内でＣＯ２排出量を削減していくためには、事業所についても取組みを行っていく必要があると思いますけれども、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"委員ご指摘の事業者に対してですけれども、基本的には事業者がみずから取り組むべきものと考えております。例えば、助成として支援していくこと、また、環境経営セミナーなどを通じて事業者を支援していくものと考えております。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"報告義務があると思うのですけれども、その産業業務部門の中でどれだけの割合なのか把握すべきだと思いますけれども、いかがでしょうか。届出対象事業者は、どういった広さなのか、従業員が何人ぐらいのところなのかというところもあわせて伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"事業者に対しては支援をしていく、また、助成設置事業を支援していくというものです。届出の１,５００キロリットルについてのイメージですけれども、一事業者としては、品川区役所のイメージを持っていただければと考えています。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"もう少しイメージをわかりやすく伺いたいと思います。あるいは中小の事業者、改めて把握してほしいと求めましたが、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"例えば、また一方では１,５００キロリットル以下のものに対して、全面的に区といたしましては支援をしていかなければならないと考えています。区全体として地球温暖化防止に向けて取り組まなければいけないものと考えていますので、以下の把握はまた違う観点だと考えています。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"目標の１,３２４キロトンに達するには、現在の排出量から４割削減しなければなりません。この施策の抜本的見直しが必要だと思いますけれども、具体的にどうやっていくのか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"その１つとして、例えば先ほど申し上げましたように、事業者向けには経営支援セミナーを効果的に実施すること。特に、しながわＥＣＯフェスティバルは、区内約３万人を動員できる大きな取組みですので、そちらにつきましても対応してまいります。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"このＣＯ２排出量の中で、そういった排出量が上がらないような電源ベースにしていくことも求めていってほしいと求めましたが、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"今すぐにはお答えするのが難しいところですけれども、大きな目標値、マイナス２６％という大きな目標を掲げております。そちらに向かいまして、区といたしましても、持続可能な社会を保ちつつ、環境対策に取り組んでまいります。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"この点から言えば、再開発推進路線を見直す必要があるのではないでしょうか。伺います。","respondent":"稲田都市開発課長","answer":"都市再生ビジョンを作成して、その中で平成１７年７月に環境配慮ガイドラインをつくり、マニュアルも作成しております。そういう中におきまして、この地区ごとの環境に対する配慮等をチェックしていっているです。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問","question":"そのチェックしているところで、実際にどうなのでしょうか、増えているのか、減っているのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"都市再開発諸制度の中で、カーボンマイナスの推進として評価基準を設けて、それ以上というところでやってきているところです。その中で変更があれば、事業途中でも変更しながら、そういうものが完了していくというところでチェックをしています。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"高層化を進めていけば、やはり延床面積が増えてしまうので、いくら効率よくしても、ＣＯ２排出量は増えてしまうと思うのです。ですので、やはりそういったところも考えながら、地球規模の問題ですので、排出を抑制していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"木村委員","kind":"意見","question":"２７７ページの一番上の２０歳以上の健診が行われていますけれども、私たちの頃には、本当に考えられないようなことでありました。そこで、行政側のお考えが多少変わってきたのだと思いますけれども、２０歳まで繰り上がった理由は何だったのか説明を求めました。","respondent":"川島健康課長","answer":"高血圧、こちらは４０代から急激に増えてまいりますが、自覚症状がなかなか出てこないことが多い。生活習慣が大きく変化する時期が２０歳ということですので、このタイミングで健康診査を実施していくという、そういう考え方です。","id":"exchange-098"},{"speaker":"木村委員","kind":"質問・要望","question":"確かにそうですね、そしてたばこを吸う年代ですから、健診がそういう若い方たちにももっともっと興味を持ってもらえるようにお願いしたいと思います。２,６００人とありますけれども、２０代はどのぐらいの人数の方々がそういう健診を受けるのか、わかれば教えてほしいと求めました。","respondent":"川島健康課長","answer":"女性のほうが受診の数が圧倒的に多いということ、それから、男性のほうがやはり健康に関する関心が低いのではないかというふうに推測しています。これはまだ１年通して結果は出ておりませんが、２０代の方の受診数でいきますと、今のところ、６０３件という実績が出てあります。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問","question":"６０３件が多いのか少ないのかということになると、ちょっとあれなのですけれども、次にまいります。特に２０歳からの若者が、健康に対してどのように考えているとお思いか尋ねました。","respondent":"川島健康課長","answer":"自分の体をチェックして、それから具合が悪ければお医者さんにかかるといったことを早め早めにやりましょうという、そういったニュアンスになります。","id":"exchange-100"},{"speaker":"木村委員","kind":"意見","question":"２７９ページの中ほどにありますけれども、８,３６４万円余からですけれども、４,０５４万円を充てています。その後、持ち去りはどのようになっているのか、また、行政としてどのような処置をとったのか、あれば説明を求めました。","respondent":"溝口公園課長","answer":"これにつきましては、毎日清掃する際に、点検または補充をしているものです。持ち去り等がないように維持管理をしていますので、今のところ、新たに持ち去りがあったという形での報告は受けていないということで聞いております。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"安全性に関しては、どのようなところに気配りをしているのでしょうか。説明を求めました。","respondent":"溝口公園課長","answer":"ですから、また清掃等をしっかりやっていく、そういったことによってトイレのイメージを向上していきたいというふうに考えているものです。そういったもので対応、また、そういった取組みをしていきたいと考えているものです。","id":"exchange-102"},{"speaker":"木村委員","kind":"意見","question":"そして、修理代。この修理代に３３２万円余ですけれども、また先ほどとよく似ていますけれども、お答えくださいとの意見を述べました。","respondent":"溝口公園課長","answer":"重たくなって動かなくなったり、そういったものに対しての修繕という形で、毎年３００万円ほど予算要求をして修繕を行っているものです。すぐ補修をしたり、改修したり、使いやすい形でのトイレを心がけて維持管理を行っているものです。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"３０３ページの下から４行目なのですけれども、ずばりお聞きいたしますが、それともなくなってもいいかなとお考えか尋ねました。","respondent":"川島健康課長","answer":"まちの銭湯は、大事にしていかなければならない、なくなっては困るというふうに考えてあります。","id":"exchange-104"},{"speaker":"渡辺委員","kind":"質問","question":"３０５ページ、しながわ観光大使関連事業、３１１ページ、商店街ステップ・アップ支援事業全体のところで伺います。どんなねらいで、どんな効果、助成をやっていくのか説明を求めました。","respondent":"鈴木文化観光課長、山崎商業・ものづくり課長","answer":"観光大使関連事業ですが、１つは、観光大使でありますシナモンの着ぐるみとか、それから関連グッズの配布等を含めて、品川のイメージとシナモンのイメージをセットで広く知っていただいてＰＲするという事業の目的になります。商店街ステップ・アップ支援事業の中の商店街後継者育成支援事業に関しましては、やはり次代を担う方々が不足しているというようなことがあります。","id":"exchange-105"},{"speaker":"渡辺委員","kind":"質問・要望","question":"実はそれを軸に、次の展開というところで、基本的に人という点で伺いたいと思います。という意味で、観光大使の今後のシナモロールをリーダーとして考えたときに、こんな可能性があるのかどうか説明を求めました。","respondent":"鈴木文化観光課長、山崎商業・ものづくり課長","answer":"区のほうで予定をして検討している仕組みがございまして、シナモロールのこと、観光のことを発信していただこうというようなものを検討しております。商店街の皆さん… やはり画一的な講座という意味では、いろいろご商売の形態がありますので、参加の部分で効率的でなかったりというような現状があります。","id":"exchange-106"},{"speaker":"渡辺委員","kind":"質問","question":"夜だろうと、やはりこういう方々もすごくリストアップしたらおもしろいのかなと思うので、いかがでしょうか。そこまでまず伺います。","respondent":"鈴木文化観光課長","answer":"それを活用するときの大学との連携、それから地域の同窓会等の会の発信力、それから在勤の方ということですね。今後検討する中で、お声かけをして、しっかりと連携できるように取り組みたいと考えております。","id":"exchange-107"},{"speaker":"渡辺委員","kind":"質問","question":"時間の中で、観光という中で、まちかど観光案内所を１点伺います。力を入れるべきものという点から、その点、最後にお知らせください。","respondent":"鈴木文化観光課長","answer":"平成２９年度末までの予定を含めまして４９カ所、事業者・店舗等の方にご協力をいただいて、区の観光に関するＰＲなどを協力いただいているものです。どこで観光案内所に入っても、訪れた方が観光を楽しめるように、さらに体制を強化したいということで進めているところです。","id":"exchange-108"},{"speaker":"こんの委員","kind":"質問","question":"インフルエンザ様疾患による臨時休業措置状況の報告があったと伺っているのですが、学年閉鎖、どのように捉えていらっしゃいますでしょうか。効果が果たして本当に出ているのか、大事なことではあるのですけれども、そこら辺はどう捉えていらっしゃいますか尋ねました。","respondent":"舟木保健予防課長","answer":"流行の開始の時期等に結構左右されるのではないかと考えています。それについては引き続き予防啓発をしていきたいと考えています。","id":"exchange-109"},{"speaker":"こんの委員","kind":"質問・要望","question":"私は、昨年の予算特別委員会でもこの点を取り上げ、この予防接種の必要性をいま一度確認をさせてほしいと求めました。接種率を区として把握をし、また、どのように接種をしている状況を捉えていらっしゃいますか尋ねました。","respondent":"舟木保健予防課長","answer":"それ以外の年齢、小児を含む方についての接種者数等については把握はしておりません。していない方で罹患率に差があるかということについても、これは定期の方を含めてもこちらのほうでは把握はしていないような状況です。","id":"exchange-110"},{"speaker":"こんの委員","kind":"質問・要望","question":"いわゆる１５歳までのお子さん、やはりそれでもこうして学級閉鎖、学年閉鎖が毎年起きている。そこら辺のところは、いま一度お考えほしいと求めましたし、このままでいいというふうに考えていらっしゃるのか、その点、もう一度お願いします。","respondent":"舟木保健予防課長","answer":"定期接種化を検討されているものについては、おたふくかぜのワクチンとかについては、既に実施をしているところです。ただいま国の定期接種化の検討対象のワクチンの中には入ってはおりませんので、国の検討の状況等を見ながら研究させていただければと考えています。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"意見","question":"先に、産業経済費全般についてお尋ねいたします。こうした観点から、産業振興関連予算、そして観光関連予算、それぞれ特徴や今後の施策の方向性、中心になる重要なポイントについてお尋ねいたしますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"商店街の支援の関係ですが、商店街の方が国際化推進対応事業ということで、発信の強化に努めてまいりたいというふうに考えているものです。","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"明日の土木費の関連になりますけれども、特に立会川周辺はまちづくりビジョンを策定すると伺っています。それから、にぎわいづくりなど商店街活性化の観点で、どのようにこちらの所管でかかわっていくのかということをお尋ねいたします。","respondent":"山崎商業・ものづくり課長","answer":"委員ご指摘のオリンピックの会場に近いというようなことも、今後の地域特性の１つです。商店街の抱える課題、こういったものを所管として、しっかりエリアの魅力を高めるようなことに努めてまいりたいというふうに考えてあります。","id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"地域の方々のご意見を伺ったりという形でいろいろ活動されています。平成２８年度第４回定例会でも質問をいたしましたが、この助成金４,７２３万円余は、財団運営費の補助金であると考えます。","respondent":"立木産業活性化担当課長","answer":"それから、品川ビジネスクラブの会員数ですが、今年度４月の段階で１４８の会員数となります。大体約７割程度が区内の会員の方ということで聞いてあります。","id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問","question":"事業費も今お話を伺った４００万円超でしょうか、地元の経営者の方々にいろいろとお伺いしますと、そのような事業が多いと。そのあたりについては、区はどのように認識されているか尋ねました。","respondent":"立木産業活性化担当課長","answer":"ＳＨＩＰの指定管理に関しましては、区のほうでもいろいろ事業企画を立ててあります。区との連携の中で、来年度、より緊密な形で連携をとっていく予定です。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問","question":"それから医療費の増大を抑制していくということを長期的な目標として掲げていくべきと思うのですが、いかがでしょうかということが１点。障害者歯科健診も同じように高齢になっていくわけでありますから、そこの高齢化対応についてはいかがでしょうかという質問をまずします。","respondent":"川島健康課長","answer":"歯科健診の検討を何年かされているということもありますので、今回は若いほうの方の年齢を引き下げるという判断をさせていただいたものです。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"これでいくわけですから、これからの１つの提案として、例えば「わ！そういう言葉を募集すると言ったらいいのですか、そういうようなことを企画してみてはいかがでしょうかという提案なのですが、いかがか尋ねました。","respondent":"中島企画部副参事、鈴木文化観光課長","answer":"しながわ」の後に魅力を続けてほしいという思いで展開をしています。今後、具体的な展開についても考えてまいりたいと考えています。 しながわ」と、それから観光の連携ですが、現在、サンリオと相談をしまして、先ほど質問にも出ました観光大使のシナモロールと「わ！ご指摘のように、連携しながら、しっかりと品川の魅力を発信していきたいというふうに考えております。","id":"exchange-117"},{"speaker":"伊藤委員","kind":"提案","question":"それに対して品川区はどうなのだという思いがあるので、ぜひ次のステップとして企画をしてみてはいかがでしょうか。提案ですが、答弁をお願いいたしますとの意見を述べました。","respondent":"中島企画部副参事","answer":"在勤の方ですので、今後展開する上では、区内の方と品川区の魅力を続ける形の企画等は検討していきたいと考えております。今年度、区制７０周年のプロモーション動画も考えておりますので、インパクトのある内容についても検討してまいりたいと考えています。","id":"exchange-118"},{"speaker":"伊藤委員","kind":"提案","question":"だから、坂井市の三国では、竹下景子さんという著名な方をプロデュースしてやっているわけではないですか。だから、品川区でも、やるのだったら、それぐらいのことをやったらどうですかという提案なのですとの意見を述べました。","respondent":"中島企画部副参事","answer":"なかなか打ち出し方というのは、今でもいろいろ考えております。品川区の魅力だと考えていますので、品川区の魅力を全国に発信できるように、今後も積極的に努めてまいりたいと思います。","id":"exchange-119"},{"speaker":"伊藤委員","kind":"意見","question":"例えば、Ｃｈａｒさんでしたか、あの方は品川区の出身であります。その人がいいかどうかは別の問題として、このことについては、ぜひもう１回正確な答弁をお願いいたしますとの意見を述べました。","respondent":"中島企画部副参事","answer":"前向きな答弁をしてまいりたいと思いますが、現段階では、映像をこれからつくってまいります。今、委員ご提案ございましたところも含めまして、品川区の顔が見える形の動画も検討してまいりたいと考えています。","id":"exchange-120"},{"speaker":"伊藤委員","kind":"提案","question":"例えでその名前を出しただけですから、ＰＲの動画をつくってくださいというお願いでありますので、よろしくお願いしておきます。先ほどの提案もあったように、誕生日もありました、３月６日なのだそうですとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"今後の連携については、せっかくなっていただいたものですから、効果的な活用をできればというふうに考えております。ご指摘のように、ぜひ皆さんに品川の魅力を知っていただくためにも、しっかりとＰＲをしていきたいと考えております。","id":"exchange-121"},{"speaker":"あべ委員","kind":"質問・要望","question":"区役所で受理する場合も、すぐに面談をすることができるのかどうかもお伺いしたいと思います。どう対処するのか、都に求めるのかどうかということも含めて、いかがお考えか尋ねました。","respondent":"太田品川保健センター所長、井浦生活衛生課長、山崎商業・ものづくり課長","answer":"妊娠届出の提出場所ですが、区役所の健康課が５割、保健センターが３割、地域センターが２割、ざっくりとそれぐらいの割合になっております。… 大井ふ頭中央海浜公園の猫の件です。きれいに管理している公園もありますので、このあたりの経験も踏まえまして… 答弁漏れです。","id":"exchange-122"},{"speaker":"あべ委員","kind":"提案","question":"今も立って待っているのでしょうか。子どもが泣いたりぐずったりしても、ずっと列のまま並んでいたりする風景は、今もそのとおりなのか尋ねました。","respondent":"太田品川保健センター所長、山崎商業・ものづくり課長","answer":"もう少しわかりやすく保健センターを一番上に出す等については、今後検討してまいりたいと思います。区役所の健康課は保健師がいる職場ではありませんので… 個人事業主の飲食店などの状況なども、必要に応じて把握をさせていただきながら、この事業にフィードバックをするようなことを考えております。","id":"exchange-123"},{"speaker":"あべ委員","kind":"質問・要望","question":"要望だけ。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"南委員","kind":"確認","question":"２８９ページの航空機騒音調査に関連してお尋ねしたいと思います。航空機騒音調査、これは初めての予算計上ではないかと思うのですけれども、航空機の騒音に特化した測定なのかどうか、そこを確認したいと思います。","respondent":"三ツ橋環境課長","answer":"航空機騒音調査のご質問です。こちらは予算としては、昨年度も予算計上しておりまして、予算は今年度が初めてではございません。","id":"exchange-125"},{"speaker":"南委員","kind":"質問・要望","question":"世界各地の空港で、大勢の人が住んでいる市街地上空を低空で通過して着陸する、こういう状況の空港はあるのでしょうか。あるとしたら、どこか教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"低空という部分が何フィートを低空と言うのか非常に難しいところですが、資料によりますと、例えばニューヨークでありますとか、ロンドンのヒースロー空港、そのあたりが資料の中では出されているものだと考えています。","id":"exchange-126"},{"speaker":"南委員","kind":"質問・要望","question":"品川の上空を低空する２００ｍから３００ｍ、そういう関係で質問しているので、そういう状況で答えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"国からの資料によりますと、ほかの例えばロンドンのヒースロー空港の周り、またニューヨークのラ・ガーディア空港の周りの部分につきましては、１,０００フィート程度、また１,５００フィート程度という資料はあります。","id":"exchange-127"},{"speaker":"南委員","kind":"質問・要望","question":"そうしましたら、安全対策はどのようにとっているのでしょうか。落下物対策として徹底した整備点検を国に対して強く求めるというふうな、どういうふうに求めているのか、それについてまず伺いたいと思います。","respondent":"中村都市計画課長","answer":"例えば説明会が品川区内で行われるですとか、あるいは、こういったもので国と話をする機会があります。そういった機会を捉えて、国のほうへは対応を求めているところです。","id":"exchange-128"},{"speaker":"南委員","kind":"質問・要望","question":"私たち、今一番心配しているところが、落下物、墜落、騒音、ですから、それについてきちんとお知らせをほしいと求めました。本当にそういうことで落下物１つとってみても、心配を払拭させることができるのか、その点について区はどう考えているのか尋ねました。","respondent":"中村都市計画課長","answer":"安全基準の内容につきましては、航空機の整備ですとか、あるいはパイロットの教育、そういったものについて基準を設けて実施しています。そういったものから推測するのではないかと、これはあくまで推測ですが、そのように考えております。","id":"exchange-129"},{"speaker":"南委員","kind":"質問","question":"なくすようにするにはどうしたらいいのかということを伺っておきたいと思います。品川区との関係はどういうふうになっているのか、品川区ではどなたが参加をしておられるのか、それについて伺います。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"脱落部品などがないか、こういったものを国としては徹底して検査をしていく、また駐機中の航空機に対しても抜き打ちで検査をするというようなことが示されております。 これについては、現在のところ、開催という形にはなってございません。作業部会、ワーキンググループということで課長級の会議があるというような形になってあります。","id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"住民の皆さんが寄せてくださったご意見、要望、こういうものについてどこの場面に反映しているのですか。伺います。","respondent":"中村都市計画課長","answer":"区民の皆様の意見につきましては、これはこういった東京都が主催する会議ではなくて、区として直接国へ伝えているものです。","id":"exchange-131"},{"speaker":"南委員","kind":"質問","question":"この連絡会を開催しろという要請は、品川区としてしてきたことがあったのでしょうか、なかったのでしょうか。ないとしたら、なぜしなかったのか、そこを伺います。","respondent":"中村都市計画課長","answer":"国に対する要望あるいは要請につきましては、都として国に対して意見を上げる際の情報共有の場だというふうに認識をしております。","id":"exchange-132"},{"speaker":"南委員","kind":"確認","question":"３月１日の都議会、国に反映させていく、そういう手立てをとることがまず大事ではないかと思っているのです。区はどんなふうに認識しているのか、必要ないと思っているのか、改めてそこを確認したいと思います。","respondent":"中村都市計画課長","answer":"国に対して意見を上げる場合に、東京都として上げていただく場合もあります。区民の皆様の声を直接国に届けるということも大事だと考えておりますので、さまざまなルートを使って国に対して伝えていっているところです。","id":"exchange-133"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで質問ですが、来年度、平成２９年度予算の予算額について、平成２８年度より多い理由をお聞かせほしいと求めました。予算が組まれた平成２９年度の見込みは、どのように捉えられているかお聞かせほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"平成２９年度については、２回分、そうした事務費がかかっている関係で予算が増えているというようなことです。６億６,０００万円に掛け合わせますと、１億８,０００万円ほどが今年度の消費喚起額だということで、押さえているものです。","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"当時、総額９億６,０００万円の大規模な共通商品券だったわけですが、ここら辺はどのような分析をされているかお聞かせほしいと求めました。２回アンケートをとられて、創意工夫をされているのか、ここら辺についてもお聞かせほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"あるいは、やはり商店街なり個店の魅力、あるいは取り扱っている商品の魅力を基本的にはアップしてＰＲしていくということで考えているものです。","id":"exchange-135"},{"speaker":"若林委員","kind":"確認","question":"時間がなくなりましたので、その後のコメントはまた後ほどということで、そ族昆虫については、１点だけ。私道で１万４,０００カ所、この１万４,０００カ所の選定方法はどうするのか、これを確認させてください。","respondent":"井浦生活衛生課長","answer":"私道につきましては、道路現況調査によりまして、道路延長約１０万ｍということで把握してございまして、何ｍごとに雨水マスという国の基準がありますので、そこから１万４,０００カ所という数字を算定したものです。","id":"exchange-136"},{"speaker":"若林委員","kind":"質問","question":"最後に、所有者によっては、うちは結構ですとかということもあるので、そこら辺のきめ細かなオーナーとの対応はいかがか尋ねました。","respondent":"井浦生活衛生課長","answer":"きめ細かく適切に対応してまいります。","id":"exchange-137"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、２９７ページ、東品川の粗大ごみ中継所に関連してお願いしたいと思います。我々もどうなったのかというのを、そこは今どういう形になっているのかということを、まず初めに教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"２３区全体でこういった施設については、要望をお出ししたりとか、そういったところで交渉を続けているところではあります。一部報道にもありましたけれども、貸し付けという形でできるということが出てきたというのが現状です。","id":"exchange-138"},{"speaker":"石田（秀）委員","kind":"意見","question":"ここのところはどういうふうにしていくかというのは非常に微妙だけれども、今、そういう誘致をしようとしているところの１つの種地として候補にする。あそこは運河もあるし、そういう話を私はその中の候補の１つにするべきだと思っているのですが、そこら辺のお考えを説明を求めました。","respondent":"柏原企画調整課長","answer":"ただ、都との交渉の中では、２０年の縛りの中で、清掃の業務に支障を来さないようにというのがかなり強い条件ということであります。我々品川区でも、そういったいろいろな広い捉え方ということも考えながら、有効活用をさらに研究していきたいというふうには思ってあります。","id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つの候補として、東京都でオリンピックをやろうとしているわけですから、これはお願いしておきます。せっかく品川区内にあるわけだから、それを有効活用させてもらうということはできないのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"品川清掃作業所については、今、お話がありましたように、施設的には余裕があると思っています。まずもってトータルで清掃事業を円滑に進めるために活用したいということで、申し入れ、お願いを継続してまいりたいと考えています。","id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから、公衆便所は確認だけさせていただきたいと思っています。その体制整備は、そこら辺の体制整備は必ずできているものだと思っているのだけれども、そこら辺のところを教えてほしいと求めました。","respondent":"溝口公園課長","answer":"マンホールトイレ等あるものについては、地域の方たちが囲いをつくっていただいたり、トイレを設置していただいて使うような形になっているものです。壊していただいて、そのままためていただく、そういった形での利用を想定しているものです。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"意見","question":"すみません、私の理解が悪かったのかもしれないのですが、それは私のイメージだと、１回やめたはずなのです。そうではなく、行政側で必ずさっと外しに行きますという体制にすると思っていたのだけれども、違ったらごめんなさいとの意見を述べました。","respondent":"溝口公園課長","answer":"今、災害時のトイレの利用です。基本的には地域の方たちにトイレを利用していただくような形で今考えているものです。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"各町会長とかに再度確認をしていただいて、鉄の棒になるのかどうか、しっかり配っていくということを再度やってほしいと求めました。私のわかっている範囲では、その意識は今はもうなくなっているかなという感じがあるので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"私は、３０５ページ、都市型観光プラン推進事業についてお聞きしたいと思います。創出につながっていると考えられているというような報告がありますが、観光を推進する品川区はどのような考えをお持ちなのか尋ねました。","respondent":"鈴木文化観光課長","answer":"品川区の観光ですが、昨年、平成２７年度末に策定をしました都市型観光プランに基づいて、区の魅力発信、それから区の観光資源を多くの方に楽しんでいただきながら、住んでいる品川区民の区への愛着もあわせて感じていただくというところが目的です。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"それでも観光を前面に出すのですか。説明を求めました。","respondent":"鈴木文化観光課長","answer":"品川区で考えています観光につきましては、いわゆる一般的な大きな観光施設や大自然のような、観光地型の観光とはちょっと違うものを考えております。日頃楽しめる、それから区外から訪れた方も楽しんでいただけるというのが品川区の都市型観光だと考えております。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"きれいな景観があるのだな、いろいろな我々が見たことのないものを品川区で見られるのだな、そういうふうに思うのが観光ではないですか。別の呼び方にしたほうがまだいいのではないか尋ねました。","respondent":"鈴木文化観光課長","answer":"委員のご指摘のような観光は従来からある観光として認識をしております。ただ、そういうものに楽しみを感じていただけるということで、そういう身近な資源を活用した観光であるというふうにご理解いただければと思います。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"でも、全然それ、世界に発信する、日本全国に発信する、本当にそんなものが、そのぐらいのものでなぜできるのですか。皆さん、一般の人はそう思うのではないか尋ねました。","respondent":"鈴木文化観光課長","answer":"それぞれ楽しむということで、その楽しむ方のいろいろな選択肢の中の幾つかに品川の観光資源がマッチをしたときに、品川に訪れて楽しんでいただける。よいまちだというふうに考えていただけると考えております。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問・要望","question":"あえてシティプロモーション、それから観光推進事業をしなくても、人がこの品川区を求めて引っ越してくるのです。見てくださいというのは、どうなのかなと思うのですが、もう一度ご見解を説明を求めました。","respondent":"鈴木文化観光課長","answer":"品川区のブランド力を高める、また住んでいる方の愛着も高めるということで重要なことです。テーマとして、観光のためにやるのではなくて、品川区のよさを知る手法の１つとして観光があるというふうに考えていただければと思います。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"だって、十分知っているから皆さん来るのではないですか。これだけのことをやって、ここで観光、では、見に来ました、ああ、これがまちなのだ、品川区なのだ、そのギャップは相当出てしまうのではないか尋ねました。","respondent":"鈴木文化観光課長","answer":"観光のイメージもさまざま捉える方によって違うかと思いますけれども、区で今考えております観光の周知も、１つは、区民の方への周知です。そのことで多少なり経済効果なり地域のにぎわいなりの創出ということで、効果があるというふうに考えております。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"よそから仕入れているのですから、サービスしている、売っている分しか収入は上がらないのです。ですから、今、文化観光課長は言っていましたけれども、私はこういういろいろな面を見たときに、やはり何がいいのだ。","respondent":"鈴木文化観光課長","answer":"委員ご指摘のように、品川の魅力、また、よいものを知っていただくという思いは同じです。ただ、私の場合は、その伝える手法のテーマが観光ということで区から任されておりますので、観光一本でしっかりとやりたいと考えております。","id":"exchange-150"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、これは企画調整課も、また財政課もしっかりその辺を見て、これから品川区のためにやってほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほど、観光地のようなものが品川区にはない、文化観光課長との質問と答弁の行き違いがあったのかなというふうにも。品川区が求める観光というのはどういうことなのか、改めて観光について、文化観光課長の思いを教えてほしいと求めました。","respondent":"安藤文化スポーツ振興部長","answer":"では、私のほうからお答えします。そういうことで、人々でにぎわい交流の喜びであふれる品川区を求めていく、それが品川区の都市型観光プランです。","id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、２７７ページの成人歯科健診と、３０５ページのシルバー人材センター支援事業について伺いたいと思います。この５歳刻みになった根拠を伺いたいのと、あと、この通知対象です。","respondent":"川島健康課長","answer":"１つ、５歳刻みの考え方ということですが、歯科を定期的に受診するようなきっかけになるような形をねらっているのが１つあります。区の健診の持ち出しの費用になりますけれども、大体７,０００円、クリーニングが２,０００円ぐらいで、事務手数料が２１６円です。","id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"確認","question":"なのに、なぜ歯は５歳刻みなのか、その違いを伺いたいと思います。そこも確認させてください。","respondent":"川島健康課長","answer":"受診券につきましては、２０歳から７０歳まで５歳刻みで、区民の方で全ての対象年齢の方にお送りするような形になります。レントゲンは、健診の内容には入ってございません。","id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこを改めて求めたいのです。そこはいかがか尋ねました。","respondent":"川島健康課長","answer":"下のほうに年齢を下げたということで、そもそも、今お話がございました職域のほうで歯科健診があるところもまだ少ないというようなところになります。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１件の健診の区の負担も、合わせると大体９,０００円ちょっとなのですか。シルバー人材センターの支援事業ですけれども、平成２８年の会員数と受託事業件数、それから事業収入を説明を求めました。","respondent":"立木産業活性化担当課長","answer":"シルバー人材センターの平成２８年度１月末の会員数ですが、２,４５８人、受託事業件数が１万５,０６５件、それに伴う事業収入が１０億５,７００万円となっています。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問","question":"会員数も徐々に減ってきてしまっているとは思うのですけれども、こうした高齢者の方がまた働くというところの背景について伺いたいのです。そして、今シルバー人材で働く方々の実情などは把握されているのか尋ねました。","respondent":"立木産業活性化担当課長","answer":"ボランティアに関して、ちょっと配分金をいただいているというような考え方のほうが近いのかなです。第４次の中期計画の中では、そういったところを区とも連携をとりながら、いろいろ事業開発にも進めていくというようなことと考えております。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問","question":"私が話を伺った方は、子どもも不安定雇用で低賃金、自立ができていない。こういったことに区はどうお考えか尋ねました。","respondent":"立木産業活性化担当課長","answer":"安い労働力として高齢者の会員を見ているということではなく、やはりそれなりの生きがい、それから経験を生かした社会参加というところでご参加いただいているものと考えています。","id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ区として、最低賃金になるように支援してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"改めて確認と要望をさせていただきたいのですが、仕組みについて教えていただくのと、その概要についてお知らせください。それから、プレス発表の１２ページです、これがまず予算書でどこに当てはまるのかということを説明を求めました。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"７７８件、８４３件となっており、平成２８年度も前年度以上になりそうな見込みでおります。それから妻の年齢が３４歳以下などというふうに新聞にはあったのですが、まだ詳細を検討中であるというようなお答えをいただいております。 予算書です、３１１ページの下から５行目にあります商店街国際化推進事業、１,１７０万円のうち、プレス発表させていただいた商店街おもてなし店ＰＲ事業につきましては、９７０万円というようなことです。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"提案","question":"平成２０年のときに要望した際には、私もそういうことを気にするような体になりましたものですから、改めてご提案しますけれども。５,４００万円ぐらいの予算ですが、本会議でも要望させていただきましたけれども、ご所見を伺いたいと思いますとの意見を述べました。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"区での実施につきましては、それから、どんな手法が品川区にふさわしいのかといった点について検討してまいりたいと考えております。この事業につきましては、例えば食品衛生協会といった関係団体のお考えをお聞きするほか… 例えば外国の方々がよく言われる多言語化の対応をされていたり、こういったものを、しっかり取組みを発掘しようではないかということが２つ目です。","id":"exchange-161"},{"speaker":"たけうち委員","kind":"質問","question":"そういったところもあるみたいですので、そういったことも視野に入れながら、ぜひ前向きにお願いしたいと思います。観光の視点もかなりあると思うのですけれども、文化観光課とはこれから連携していくのだと思うのですけれども、そこだけ説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"もともと２年前の組織改正で商業・ものづくり課になりました以前は、商業・観光課という課でございました。従来どおりきっちり連携して、魅力ある品川のエリアということで、強力に発信なり取組みをしてまいりたいというふうに考えているところです。","id":"exchange-162"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、品川区の中で今、環境アセスメントの対象になっているのはどのぐらいの数があるのかということを教えてください。ですから、区の当局としてはどのように考えているか、そこら辺を説明を求めました。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長","answer":"今現在のところ、４カ所から出ております。目黒清掃工場であったり、川崎天然ガス、また、委員ご指摘の今の４号線の部分、そして京急立体化となっております。 資源回収におきましては、区内約１万カ所の資源回収ステーションで、集積所回収の流れの延長上で回収をしております。保管場所、集積所の整備とあわせまして、それに応じた車両の配置も含めて検討してまいりたいと考えております。","id":"exchange-163"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、うまく収集し、また事故のないように気をつけていただくように、よろしくお願いしたいと思います。あそこがホッケー場ができると、やはり樹木が大分影響を受けるのではないかと、その辺では区のほうに話は来ているのか尋ねました。","respondent":"三ツ橋環境課長","answer":"自主的なのですけれども、委員ご指摘のように、東京都のオリンピック・パラリンピック準備組織委員会から出されているものです。こちらはＩＯＣの要請により、対応といたしましては、この両方の会場がアセスメントの対象となっております。","id":"exchange-164"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"緑という意味で、品川区のみどり率が現在どのぐらいになっているのかというのと、今後の目標的にはどうなっているのか教えてください。区なのか、警察に話をしてもという、その辺の区と警察の協力体制みたいな関係を説明を求めました。","respondent":"三ツ橋環境課長、溝口公園課長、小林品川区清掃事務所長","answer":"緑地に関しても、委員ご心配の部分につきましては、意見照会の部分で伝えてまいります。そちらでいきますと、現在、品川区内のみどり率といたしましては、２１.４％になっているものです。策定後１０年、平成３３年までに目標を定めておりまし… したがいまして、その趣旨をご説明してまいったところですが、なかなか理解が得られず、ごみが放置されている実態がありました。","id":"exchange-165"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"みどり率ですけれども、これからもその目標へ向かってしっかりやっていってほしいと求めました。警察とタイアップしてきれいにできたということなので、これからもこういう案件が万が一あったら、ぜひ対応を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/307926?Template=document&Id=1062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":124140,"voices":395}},{"id":"h29-20170314-3","meetingId":"h29-c-budget","date":"2017年3月14日","dateIso":"2017-03-14","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を161件整理しています。","topics":[{"id":"topic-01","title":"起立少数であります。ご着席願います。 よって、本動議は否決いたしました。 それでは、改めまして、第５号議案、平成２９年度品川区一般会計予算","agenda":"起立少数であります。ご着席願います。 よって、本動議は否決いたしました。 それでは、改めまして、第５号議案、平成２９年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３５３ページ、３５７ページ、空き家改修についてお伺いをさせてほしいと求めました。この街路樹等維持管理費、剪定等ありますけれども、それと、かむろ坂の桜植替え工事費について、内容をお知らせほしいと求めました。","respondent":"多並道路課長","answer":"ここの平成２９年度に計上しています費用といたしましては、管理するための費用ということで、計上しています。その１段上のかむろ坂の桜につきましては、適正な時期に植え替えていきたいということで、計上させていただいた内容です。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"桜の見ごろのときの桜が、すごく見栄えがよくなくなってしまって、そういう基準というのがどうなっているのか教えてほしいと求めました。トラックもあるでしょうし、枝をはらわなければいけないということもあると思うのですけれども、その辺のところをお聞きしたいと思います。","respondent":"多並道路課長","answer":"桜の寿命等ですけれども、一般的に高木の寿命、全体的には８０年ぐらいと言われております。ひとつの楽しみでもありますので、その点、よく注意して剪定はしていきたいと思っているところです。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３５５ページ、改修工事助成、および３５３ページ、住宅耐震化支援費についてお伺いいたします。予算書を見ますと、おそらくこれは耐震化支援費に入ると思うのですけれども、それを確認させてほしいと求めました。","respondent":"鈴木建築課長","answer":"予算書の３５３ページのほうには、件数は書いてございませんが、その３０万円をプラスした金額が記載されているというものです。東京都が平成２５年に調査をかけた中で、倒壊危険度が高いエリア、そこで重点的にやっていきたいというものです。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それぞれありがとうございました。施工に入ったときに、派遣アドバイザーの方も実地現場調査に来るのかどうか、お知らせほしいと求めました。","respondent":"鈴木建築課長","answer":"１回１時間から２時間程度、２ｍ以上を超える擁壁になりますので、必ず確認申請が必要になります。ほかの一級建築士が受けるのかによって違いますけれども、基本的には現場のほうは、しっかり資格を持った方が工事管理をなさるという話です。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３５７ページ、空き家対策についてお伺いをさせてほしいと求めました。防草シート購入１０件ということなのですけれども、そういうことなのかどうなのか、お聞きしたいと思います。","respondent":"今井住宅課長","answer":"活用モデルという形で、こちらのほうは２件、目標ということで考えております。保全通知を差し上げている方の中から１０件程度はご希望があるというふうに考えておりまして、１０件達成する見込みというふうに考えております。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"区のほうで依頼を受けて、区のほうで、この当該空き家のところに防草のシートを敷くという認識でよろしいのか尋ねました。","respondent":"今井住宅課長","answer":"今般の防草シートの購入支援につきましては、防草シートの代金の２分の１程度になります限度額５,０００円で助成をするという形で考えております。シート代のみです。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"意見","question":"ぜひ、そういった地域の、近隣の方からの依頼がありましたら、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"３２３ページ、３４３ページ、公園整備事業費について伺っていきたいと思います。駅周辺等ですが、区内のバイク、それから二輪の保有台数について、今日はわかりますか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"バイクの保有台数ですけれども、こちら、税務課のほうにちょっと確認いたしまして、原付につきましては１万４,７７６台、自動二輪につきましては８,１２２台が登録されているということで、確認いたしました。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"確認させていただきました。ちょっと不勉強で教えていただきたいのですが、何らかの形で品川区まで入ってくるものかどうか、説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"これは確認します。原付しか止められない所と、自動二輪も止められる所の、その内訳がわかれば説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"バイクの駐車場所のスペースについては先ほどのとおりなのですけれども、一応、施設の大きさによって、大きいバイク用の所もありますし、原付用のちょっと狭いスペースという所もありますので、ちょっと細かいところの数字、内訳までは把握していないところです。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"３９台余裕があるのですが、２９台の放置バイクがあったということで、それを全部入れたとしても１０台の余裕があるのですよね。放置バイクもしっかりと、せっかく整備している所に止めてもらえるような工夫をされたほうがいいかと思うのですが、これについて説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"ホームページ等でも、そういったものがネット上でも見られるようになっておりますので、引き続きいろいろな場所があるということを周知していきたいと考えております。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"街路樹約４,０００本に対して、今現在、何本になったか教えてください。パーセンテージも説明を求めました。","respondent":"多並道路課長","answer":"区内の街路樹については、現在３,９９９本、委員のご指摘のとおり、約４,０００本です。そのうち、桜が１,３１８本で、割合としましては、約３３％が桜で、ほかの区よりは非常に多い街路樹の割合だと、我々、認識しています。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"不健全木が１９本あって、それから工法、昨年の決算でも要望させていただいた根上がり対策ですね。これを説明を求めました。","respondent":"多並道路課長","answer":"空洞が５０％以上あるものが１９本あったということで、５０％以上倒木の危険性があるということで、その１９本を対象にしているものです。平成２９年度の予算で計上させていただいて、その１９本の、それがこの計上させていただいた費用です。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"１９本ですから、全部ではないので、多分、植え替えた所は、どうしても少し空が見える。桜の木が植えられていくように、これも引き続き、要望も含めて、提案も含めて、言い続けていきたいなと思いますとの意見を述べました。","respondent":"溝口公園課長","answer":"正確には４カ所ですね、４カ所のトイレ改修について、予算を計上させていただいているものです。ほかにも旧東海道沿いのトイレ、また大井町の駅前のトイレ等ありますので、そういったものを改修していきたいというふうに考えているものです。","id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"平成２７年度の決算のときに、提案をさせていただいていたので、非常に喜んでおります。ましてや、武蔵小山、大きい駅ですからとの意見を述べました。","respondent":"溝口公園課長","answer":"人的、予算的にも、計画的に進めていくという箇所でいくと、やはり５、６カ所。４カ所から６カ所ぐらい、やはりこのぐらいが、ちょうど計画的に進められる限界なのかなというふうに感じているものです。","id":"exchange-015"},{"speaker":"つる委員","kind":"提案","question":"提案もしていきたいと思いますし、いろいろなところから引っ張ってきて、促進されるようにしたいと思います。おもてなしトイレは、品川区どこから入ってもおもてなしトイレがある、そういう整備をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"３５７ページ、マンション管理支援、また、３４７ページ、大崎駅周辺地区再開発事業、大崎西口駅前地区について伺います。それと、マンション建替え時の課題は何だと区は考えていらっしゃるのかも伺いたいと思います。","respondent":"今井住宅課長","answer":"ただ、今１件、建替えを行いたいというふうな具体的なご相談があります。まずは意識、またはその建替えに向かう集約ですとか、住民の合意が一番の課題になるかと思います。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、この直面しているマンションというのは、区内にどれぐらいあるのか、区は把握してらっしゃるのか伺いたいと思います。実態調査が必要だと思うのですけれども、この実施も求めますけれども、いかがか尋ねました。","respondent":"今井住宅課長","answer":"旧耐震・耐震の部分で、旧耐震の割合が大体２５％程度、マンション全体の２５％程度のような報告が出てくる見込みです。実際にマンション管理セミナーということで実施いたしましたけれども、十分、長寿命化もできるというふうにも聞いております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいと思います。この先行モデル事業の成果とは何だったのか、伺います。","respondent":"今井住宅課長、稲田都市開発課長","answer":"先ほどの割合ですけれども、現在調査を行っておりますのは、東京都と連携して、分譲マンションのほうです。５０年後以降の建替えに際して、どういうふうに考えていくかというのを、合意形成を十分に図っていくことが大切だと考えていま… 平成２７年度、平成２８年度と、その辺を検討してまいりました。容積率、それから都市づくりの中での補助金制度、また税制制度等の関係等を提案したです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"超高層マンションのほうが困難があるのではないかということについて、もう一度、区の認識を伺いたいと思います。それと、計画はどのような計画なのか、わかれば説明を求めました。","respondent":"今井住宅課長、稲田都市開発課長","answer":"いかに普段の管理規約、もしくは通常の日常管理の中で、大規模修繕などの計画を練っていくかにかかっていると思います。こちらは戸数の問題ではなくて、超高層・高層というふうな考え方で区別するものではないというふうに考えておりま… この地区で、借家人等はちょっと今のところ把握できないのですが、建物数から言えば、このエリアの中で１３棟あるところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"提案","question":"この方の土地は、耐震化したばかりのビルですから、この終末期の問題も既にクリアしているわけなのですけれども、納得いかないと。この場所で事業を続けたいという希望は当然のことだと思いますけれども、品川区はそういうふうに思わないのでしょうか、伺いたいと思いますとの意見を述べました。","respondent":"稲田都市開発課長","answer":"この大崎駅の西口地区、この地区に関しましても、平成２４年から地元の方と意見交換会等しておりまして、今後また合意形成等に向けて進めていくと思われます。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"３２５ページの補助１６３号線整備について伺います。どのように、もしかしたら、区役所前でありますから、区役所に影響が出てくるのか、そのことについて伺いたいと思います。","respondent":"多並道路課長","answer":"その後に、下の街路の整備を行うのが１年間、平成３２年度ということで、現在、平成３２年度に完了させる予定で、工事を進めているものです。一緒に検討しながら、今後の補助１６３号線整備のあり方についてということを、検討していこうという経費が入っているものです。","id":"exchange-022"},{"speaker":"松永委員","kind":"提案","question":"ちょっと提案なのですけれども、タクシーの乗降者スペースをぜひつくっていただきたいと思うのですけれども、そのことについて伺います。ぜひそうしたサインを、矢印の方向というのをつけていただきたいと思うのですけれども、そのことについても合わせて伺いたいと思いますとの意見を述べました。","respondent":"多並道路課長","answer":"１つ今回の事業の中であるのが、どうやって入れるかどうかというのを、工夫しないといけないかなと考えているところです。ちょうど我々の補助１６３号線でやっている工事から続いて、その掲示をできないかとか、協議をしていきたいと思っているところです。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"新しい壁画を、また同じ学校の生徒さんに描いていただきたいとは思うのですけれども、そのことについてどのように考えていらっしゃるのでしょうか。それとも、また残していくのか、その辺、お伺いしたいと思います。","respondent":"多並道路課長","answer":"補助１６３号線は新たな事業区間ということで、事業を、どのような整備を進めるかという協議を進めていくところです。やはり地域の方のご意見をお伺いして、よりよい形でということで、進めていきたいと思っているところです。","id":"exchange-024"},{"speaker":"松永委員","kind":"提案","question":"提案ですけれども、この場所はこのように変わりますというような立て看板をつけながら、少しずつ対策をとってみてはいかがでしょうか。もちろんトラック以外にもいろいろな車が止まっておりますので、その辺の対策について伺いたいと思いますとの意見を述べました。","respondent":"多並道路課長","answer":"大田区とも続くので大田区、警視庁とも協議しているところですけれども、自転車レーンを整備する予定となっています。今後も協議しながら、詳細については詰めていきたいと思っているところです。","id":"exchange-025"},{"speaker":"松永委員","kind":"提案","question":"そこで、３１９ページのシェアサイクル事業について伺います。平成２９年度予算書では、公園等整備費に５００万円となっておりますが、場所はある程度決まっているのか尋ねました。","respondent":"多並道路課長、安井土木管理課長","answer":"平成２９年度につきましては、あとは桜新道の塗り替えと、やっていきたいと考えています。は地元ともよく協議しながら、今後進めていくということで、引き続き協議を進めているところです。まず間違いなく、区の重要な観光スポットですので、こちらのほうはつくるということで予定はしておりますけれども。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"次に、３４１ページのしながわ水族館運営費について、関連して３４３ページのしながわ区民公園改修工事について伺います。そのことについて伺います。","respondent":"溝口公園課長","answer":"委員お話しの所は、レストラン横の階段になっている部分だと思います。勝島の海に触れ合える、そういったゾーンの設定をして、階段状になっているものです。","id":"exchange-027"},{"speaker":"松永委員","kind":"提案","question":"勝島の海ということで、ぜひその海を活用してみてはいかがかということで、ちょっと提案させてほしいと求めました。昔あの場所でボートをやられていたということをお伺いしたのですけれども、なぜボートを取りやめてしまったのか、その辺も伺いたいと思いますとの意見を述べました。","respondent":"溝口公園課長","answer":"そういうコンセプトのもとにつくってきて、皆さんに親しまれてきている公園だというふうに認識しています。本来であれば活用という形でいろいろ考えていきたいところではありますが、そういったところで一旦は中止という形でさせていただいたのが現状です。","id":"exchange-028"},{"speaker":"松永委員","kind":"意見","question":"全国水族館ランキング、じゃらんnetというところでちょっと調べさせていただいたのですが、しながわ水族館は３２位と健闘しております。ぜひ水族館以外にも、そうしたアトラクションを１つ増やしてみてはいかがかと思うのですが、最後に改めて区の意見を説明を求めました。","respondent":"溝口公園課長","answer":"平成２９年度予算の中でも、勝島のレストランをどう活用していくのか、そういったところの検討費用も計上させていただいているところです。詳細設計に入っていく予定になっておりますので、公園になるように、検討していきたいというふうに考えているものです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"３３７ページ、３４２ページ、公園新設改良費についてお伺いをいたします。航路とか、ポイント、拠点、そして来訪者人数など、そういったことをお知らせください。","respondent":"和田河川下水道課長","answer":"舟運社会実験継続中でございまして、今後検討していくわけですが、定期航路にとまっていただく。それから、東品川二丁目防災桟橋をハブの桟橋として、区内の舟運の活性化が図れればというような構想を考えているところです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"どのくらいの来訪者人数というのは、まだ予想はできないか尋ねました。","respondent":"和田河川下水道課長","answer":"２８日間の運行の中で、２１７便、概算で１,３００人ほど乗っていただいたという計算があります。どのような乗降客数ですかね、そのようなものが考えられるかということを、検討していきたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした事業にしていっていただきたいと考えておりますけれども、同時に、また船から見える景観づくりというのは非常に重要になってくると思います。この２つの事業があると思われるのですけれども、この２つの事業は一体どういうものなのかをお知らせください。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"そしてこれから、基準の策定の１つの基礎の調査にしようというところで、今回計上しているものです。 水辺の賑わい構想検討委託ですけれども、今、現在ある水辺からの景観をどうやって守っていくかという視点で検討するものです。この辺を生かして、どのように賑わいを創出していくかという視点で検討するのが、賑わい構想の検討委託です。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ、前向きなそうした検討を重ねていって、人が多く来る賑わいづくりというのを、ぜひともやっていただきたいと考えております。これを１つのきっかけとして、天王洲エリアのかつての輝きを取り戻すべく、区のお考えはどのようになっているか尋ねました。","respondent":"和田河川下水道課長","answer":"対岸には、我々の品川天王洲桟橋もあります。今後は、東品川二丁目防災桟橋も含めまして、天王洲全体で水辺の活性化ということでご利用いただければというふうに考えてあります。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"次は、公園についてお伺いいたしますけれども、しながわ中央公園拡張部に、前回、建設委員会で視察に参りました。今後ともそうした方向でやっていっていただきたいのですけれども、今後、品川区としても公園新設改良時にそのようにしていくのかをお知らせください。","respondent":"溝口公園課長","answer":"管理事務所を新たに設置しておりますので、そういった中での防災備蓄倉庫を整備したり、そういったところでの整備というのは行っていきます。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも整備を進めていっていただきたいと考えております。これは同様に、今後の公園や改良時に進めていくべきだと私は考えているのですけれども、品川区としてはどのようにお考えか尋ねました。","respondent":"溝口公園課長","answer":"そこの公園・児童遊園を使って、災害時にどのように活動するのか、そういった中の一環として出てきているものです。地域から、かまどベンチの設置のお話が、そういったものはしっかりと整備をしていきたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"地域の方から、いざとなったらコンロとなる防災スツール、かまどベンチは、非常にいいので、ぜひ進めていってほしいというお声も頂戴しております。地域バランス的に防災広場を品川区東部のほうにも設置していっていただきたいなと考えているのですけれども、その点いかがお考えか尋ねました。","respondent":"溝口公園課長","answer":"今現在、防災広場の整備につきましては、木造密集地域の解消ということを目的に整備を進めているところです。そういったところの中で土地を購入し、広場として整備をしているといった事業ですので、ご理解いただきたいと思います。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"よくわかりました。東側は、木造密集地域が少ないので、やらないということでよろしいのか尋ねました。","respondent":"溝口公園課長","answer":"かまどベンチですとか、そういったものの設置のお話があれば、それはしっかり受けた形で整備を進めてきている。これまでも、これからも、しっかりとそういったご意見を聞きながら整備を進めていきたいというふうに考えているものです。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"しっかりと地域の声を拾っていただいて、必要なところはしっかりと整備をしていっていただきたいと考えております。この災害用設備を活用した訓練もやっていただきたいのですけれども、その点、区としてのお考えはいかがか尋ねました。","respondent":"溝口公園課長","answer":"私ども行政側がつくっただけでおしまいというわけではありませんので、その先、そういったところも１つ大切だと考えています。必要なところ、また、整備できるところはしっかり整備をしていきたいというふうに考えているものです。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"そして、ちょっと時間がありますので、３４１ページの八潮地区まちづくり検討経費について、お伺いをしたいと思います。そうした商業施設誘致などの仕掛けが必要だと考えていますけれども、その点、区としてはいかがお考えか尋ねました。","respondent":"中村都市計画課長","answer":"こういったものも課題の１つとしては捉えておりますけれども、入居開始してから約３４年ということで、将来のことについて考えていきたいと考えています。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、下水道管改修事業、河川管理費についてお伺いいたします。平成２８年１１月７日から、小山五丁目、六丁目、荏原五丁目の工事がスタートしておりますが、スケジュールを確認させてほしいと求めました。","respondent":"和田河川下水道課長","answer":"ご指摘の、立会道路の改修工事ですが、これは東京都下水道局の工事です。平成２９年１１月完了予定で工事を進めていたところなのですけれども、平成３０年５月中旬まで工事を延長する予定だというふうに聞いております。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"こちら、地域への事前の説明の徹底と、立会川幹線の再構築を着実に進めていただくことを都に要望していただきたいと考えております。報告義務の有無にかかわらず、区側もアンテナを張っていただいて、区民の安心・安全への取組みを強く要望いたします。","respondent":"和田河川下水道課長","answer":"幹線の再構築の、いろいろな幹線が東京都内にあるわけなのですけれども、優先的にこの立会川幹線を事業化して取り組んでいるところです。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっと専門用語も多いもので、詳しく、わかりやすく教えていただきたい部分があります。工事工法の概要について、わかりやすく、簡単で構いませんので、お願いします。","respondent":"和田河川下水道課長","answer":"今、下水道管は耐用年数が８０年程度で考えているですので、８０年サイクルで更新をしていかざるを得ないというようなことを記述されたものです。既存の下水道管の間に空隙ができるものですから、その空隙にモルタルを充填して固めて、全体として強度を強化するという工事です。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"次の質問、２点目なのですけれども、荏原南公園、子ども達のアイデアを活かした公園について、お伺いいたします。特に、以下の８つのポイントについて、詳細設計の内容を確認させてください。","respondent":"溝口公園課長","answer":"それぞれに、これまでと同様、子どもたちのアイデアを入れた遊具を設置していきたいというふうに考えてあります。今後も引き続き、事故等のない施工に心がけて、まちづくりを進めていきたいというふうに考えているものです。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"時間があれば、３４７ページの大崎駅周辺地区の再開発で、大崎エリアマネジメントについて伺いたいと思います。は地域住民からの要望があれば、交通管理者である警察に働きかけをしていただけるのかどうか、この辺についてお伺いします。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０につきましては、交通安全の対策の１つということで、推し進めているところです。今後も区民のほうに、地元の場所を知っていただいて、安全活動に役立てていきたいと考えております。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"どういう優先順位でこの４３カ所、３分の１のマックスのですから、１,５００万円以上の工事。これは多分１,５００万円では到底無理のような工事の感じがするのですけれども、これは働きかけを行っていくのか、それについて伺いたいと思います。","respondent":"鈴木建築課長","answer":"一定、東京都が５ｍ以上、傾斜が３０度以上でかけておりますが、大きいものから小さいものまで、さまざまです。こういったものを４３カ所のうちから抜き出して、アドバイザー派遣等を使って、働きかけをして、助成につなげていきたいというものです。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私、個人的にそういうの大好きなものですから。レディーメードのものがあるのか、それともこれはオーダーメードの１点ものなのか、それについて説明を求めました。","respondent":"溝口公園課長","answer":"ある１つのそういった造形の遊具等をつくるメーカーがありますので、関連する会社を含めてお願いして、ずっとつくってきているというのが共通点だというふうに認識しているところではあります。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問・要望","question":"シティプロモーションの１つとして広報していく、こういう手法もあるのではないかと思うのですが、いかがでしょうかというところです。ですから、この不思議な造形美を、ぜひシティプロモーションとして活用していただきたいと思うのですが、いかがか尋ねました。","respondent":"中島企画部副参事","answer":"ポスターでも、その公園の恐竜のほうを使わせていただいたところ、これは何とか、これはどことか、いろいろ反響がありました。区民が品川区にさらに誇りと愛着を持てるように、今後のシティプロモーション活動の中で、さらに活用できるか検討させていただきたいと思います。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ要望です。非常にちょっと心苦しいところがあるのですが、これはぜひ対応はしてほしいと求めましたが、いかがでしょうかというところ。","respondent":"溝口公園課長","answer":"今後も、地域の方、またはご利用者の方の声を聞きながら、ベンチの設置、そういったものは考えていきたいというふうに考えているものです。１２７カ所、そのうち、洋式のトイレが１カ所でもあるものが３８カ所になってあります。","id":"exchange-048"},{"speaker":"吉田委員","kind":"確認","question":"３５８ページ、３目区民住宅費、伺いたいと思います。検討する必要があると考えるのですけれども、その辺はどうなっていますか尋ねました。","respondent":"多並道路課長","answer":"品川区の場合は非常に歩道も狭い中でもありますので、基本的には車道の横を走るのを基本とするというのが、考え方の１つです。国全体で同じような、今後は進めていこうというのが示されて、区としてもそうやっていきたいというものです。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"それまでに、他区との連携も図られているように伺いましたので、それまでにきちんと整備されるように要望したいと思います。損害賠償の分も含めて入っていくということでいいでしょうか、確認させてください。","respondent":"多並道路課長、安井土木管理課長","answer":"平成２８年７月に示されたところでありますので、今後は品川区でも、その国の基準にのっとってやっていきたいと。今後もこのような形で、警視庁ともよく協議しながら進めていきたいという内容です。 利用者のを別にかけるということではなくて、自転車そのもの、それぞれにかけていくというような形になろうかと思います。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"さっき、伺うのを忘れました。一律でも、品川区の場合、それは無理だよねという、そういう道もあるように思うのですけれども、その辺どうなのか、もう１回お答えいただけますか。","respondent":"多並道路課長","answer":"１.５ｍとか、警視庁と連携して、そこの場所を通るのですよという。幅が０.５ｍもしくは０.６ｍとか、あくまでも、こちら側をこの方向に進むというのを標示で示していくというのが内容です。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"３５７ページの住宅総務費で、東日本大震災支援費の被災者受入住宅費と、東日本大震災支援費の中で住宅原状回復費ですね。それから合わせて、現段階で、東北から避難してきて品川区に住んでらっしゃる方の状況を説明を求めました。","respondent":"今井住宅課長、寺嶋木密整備推進課長、久保田総務課長","answer":"３５７ページ、東日本大震災支援費と、３５９ページの同じく支援費です。来年度につきましては、入居の期限等が今年３月までということになった世帯があり… 木密整備推進課で実施しています密集事業の中で従前居住者用住宅というものがございまして、３３９ページの下から６行目になります。状況としては以上です。把握しているものにつきましては、合計で３６世帯８３人、これが２月の時点での数字です。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"東京都は、該当者にヒアリングをしているのですが、品川区はこの状況を把握していらっしゃるのか、教えてください。この住宅支援費の打ち切り後、どうするのか決まっていない避難者が７割以上に上るということなのですが、品川区ではいかがか尋ねました。","respondent":"今井住宅課長","answer":"平成２９年３月末までに、それ以外の対象の方が、品川区内５世帯いらっしゃるというふうな認識です。今申し上げました５世帯につきましては、転居または福島県にお戻りになることを含めまして、全て４月以降のお住まいの先は確保されている状況です。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"避難者の方がいらっしゃるということなわけで、そういう方たちの状況というのは、把握していらっしゃるのでしょうか。不安定な立場の人が相談したいと考えたときに、品川区にはそれを受け止める窓口はあるのか、伺いたいと思います。","respondent":"久保田総務課長","answer":"２カ月に１回程度、２カ月に１回ですけれども、郵便でお知らせをしているです。ただ、住民票等を移されて区民等である方は、通常の区民の方と同じように、いろいろなご相談には応じているです。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"納付促進の費用が大変急増していて、どういう趣旨の急増かなということで伺いたいと思います。しごと応援センターですか、その機能をぜひ活用してほしいな、。","respondent":"今井住宅課長","answer":"１カ月、故意ではなくて遅れている場合もありますので丁寧に対応しているとともに、何とか回収できないかということで検討してまいりました。生活困窮者の自立支援相談窓口等ありますので、関係各課と連携しながら、相談等に対応していきたいと考えています。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は、暮らし・しごと応援センターで、家計相談、設置する必要がないのに始めたということを大変評価しております。その機能をぜひ有効に生かしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"３３１ページ、その後に八潮地区まちづくり検討経費、立会川・勝島地区まちづくりビジョン策定費について伺います。これからはどういうふうに進めていくのか、一連の作業工程、プロセスについて伺いたいと思います。","respondent":"和田河川下水道課長","answer":"マンホールトイレ設置公園の下水道の耐震化を進めておりますが、この災害復旧拠点等の耐震化も、平成２９年度に完了の見込みです。これにつきましては非常に時間がかかるということで、現在のところ、いつまでという目標を立てていない状況です。","id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"誰でも共通する思いですから、そういう計画は持っているというふうに聞いておりますけれども、そのあたりはどういうふうな状況になっているのか。これからどういうふうにしていこうか、いつまでにやっていこうかという、そこのところの内容を説明を求めました。","respondent":"和田河川下水道課長","answer":"東京都も考えているところですが、一般の住宅、一般のエリアへの展開に移っていくというふうに考えてあります。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"八潮の住民、関係者が入っていける、そういう設定にしていただきたいというのが１つあります。それから、集約建替余剰地活用というのは具体的にどういうことなのか、ちょっと教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"既存６９棟、１つはリフォームですとか、こういった様々なケースに応じて検討していく必要があると考えております。こういったところで、今後検討していく内容の１つの可能性として、掲げております。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"その中で集約をしていくと、そこは厳格にとっていただいて、進めていただきたいということを、ちょっと要望したいと思います。そこも握って離さないでいただきたいと考えていますけれども、改めて区の見解をお願いします。","respondent":"中村都市計画課長","answer":"そういったところが課題というふうに認識をしております。ただ、具体的な内容につきましては、やはりこちらも地域の皆様のご意見も伺いながら進めていかなければいけないというふうに考えてあります。","id":"exchange-060"},{"speaker":"沢田委員","kind":"意見","question":"２０２０年までということでしたけれども、買った場所がどうなっているのかなというところで、そういう土地がこれから増えていくのか。その辺の活用を考えていってはどうかと思うのですけれども、その辺のところのご検討というのはどういうことをされているのか、説明を求めました。","respondent":"中村都市計画課長","answer":"もうその１年から２年前には工事に着工しなければいけないというところを考えますと、かなり短い期間ということになると思います。この管理の方法も、ある程度まとまった時点で、道路の工事に着手するという、そういった可能性もあるというふうには聞いてあります。","id":"exchange-061"},{"speaker":"沢田委員","kind":"質問・要望","question":"地域の人ともそういったことを検討していってほしいと求めました。今どういう状況、そういうことがあるのかどうか、実際の状況について説明を求めました。","respondent":"溝口公園課長","answer":"実際、公園内での、ここ最近ですけれども、犯罪が起こっているという話は聞いておりません。公園内で何か犯罪が起きて、防犯カメラが必要となったというようなケースは、ここ近年ではございません。","id":"exchange-062"},{"speaker":"沢田委員","kind":"質問・要望","question":"今の防犯カメラはずっと見ているわけではないですから、ぜひ、こういった防犯カメラの設置というのは増やしていただきたいなと思います。その分の予算というのは、そういった課題と言うか、公園に防犯カメラを設置することに対する課題というようなところは何かありますか。","respondent":"溝口公園課長","answer":"すぐ、即日に警備員が対応できるような対応をとっております。そうしたところをして、より安全にご利用いただけるような公園づくりというのを目指していきたいというふうに考えているところです。","id":"exchange-063"},{"speaker":"沢田委員","kind":"質問・要望","question":"ぜひ、安心・安全に、公園もですけれども、地域もそうですけれども、しっかりとできるように、整備をしていってほしいと求めました。巡回の警備にかかるお金とか、そういったことも予算を考えて、ぜひ整備していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今後、それからもっと北側と言うのですか、水族館側の整備をお考えであるかどうか。ここの３５３ページに書いてある除却工事助成の木造一戸建て２００棟、アパート５０棟というのは、いかがお考えですかということ。","respondent":"溝口公園課長、鈴木建築課長","answer":"休めたり、そういったものができるのか、そういったところについては十分検討していきたいというふうに考えているものです。しっかり観光を推進する部署と連携を図りながら… 午前中もご説明しましたように、あるいは実施状況のホームページでの公表などを謳う基本的な内容になっておりまして、職員のほうが検討して。","id":"exchange-065"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それで耐震に関しては、ちょっと木密の今回のと絡めると、耐震の、今回、今、質問したものに関しては、助成額が増額をされる。やはり相乗効果で実績は上がっていくと思いますので、エリアの拡大ということを今後考えてほしいと求めましたが、いかがでしょう。","respondent":"鈴木建築課長","answer":"設計、耐震工事、これらで周知に努めてまいりたいというふうに考えてあります。","id":"exchange-066"},{"speaker":"塚本委員","kind":"確認","question":"この３２８ｋｍ、いわゆる一般的に区道というものが、ほぼ全て対象となるということでいいのかという確認が１つです。この２つ、まず２点お伺いをさせてください。","respondent":"多並道路課長","answer":"現在の点検というか、巡回を先ほどお話ししましたが、３地区に分けながら、今の巡回の点検というのを、人の目で行っているところです。月１回は必ず巡回をしまして、頻度の高いところは週２回行っているところで、このような頻度で行っていくというものです。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問","question":"このようなことで説明されておりますけれども、どの程度、でこぼこを検知するようなシステムなのか。そうではない場合も含めて、どの程度のものを検知するものなのか、説明を求めました。","respondent":"多並道路課長","answer":"今後注意したほうがいいだろうというのを、実際に通ってみて、それを実際に拾えるような形ですね。設定しながらやっていきたいというのが、どちらかと言うと、そういう形のものがやっていきたいという内容です。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"多分、耐久年度とか、そういうのでやっているのではないかと思いますが。そういう定期的な全面舗装みたいなことの計画にも生かしていけるのではないかと思うのですが、そういうお考えがあるかどうか、説明を求めました。","respondent":"多並道路課長","answer":"そこの柏市が、今のような長期的な、もしくは改修計画の１つの目安にしていると聞いているところです。いわゆる改修時期も、数値化を１つの目安にしながらやっているところも、そのような考えで進めていきたいと思っているところです。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"国が、こういった義務付けをして助成をしていこうというふうに定めた狙いというか、理由ですね、これをまず１つ伺いたいと思います。","respondent":"鈴木建築課長","answer":"倒壊危険度５の地区は、品川区内はございません。次に高い４地区が、この１１地区ですので、そこで重点的にやっていくというものです。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"人が歩いて建物を見てとかなのか、何か違うデータ等があってなのかというところを、ちょっとお伺いしたいというのが１つと。やってほしいようなところには何度も訪問するような、戸別訪問について、どれくらいの戸別訪問ができるのかというところを説明を求めました。","respondent":"鈴木建築課長","answer":"１軒１軒まずチャイムを押して訪ねて、そういったところを説明しながら、簡単なアンケートもその場でとりたいというふうに考えてあります。地区内の耐震化に対する考え的なところを最後取りまとめて、重点的に回るところも、その後考えていきたいです。","id":"exchange-071"},{"speaker":"塚本委員","kind":"提案","question":"これは提案なのですが、ぜひこの感震ブレーカーの普及と啓発と一緒にやっていただけると、大変に効果的なのではないかなと。地域的には、おそらくこの１１地区、かぶっていると思いますので、その点もいかがでしょうかということで、お伺いいたしますとの意見を述べました。","respondent":"鈴木建築課長","answer":"戸別訪問の委託先ですが、今現在、プロポーザルで事業者を選定する方向で、調整というか、準備を進めているところです。そういったところも、不安を解消しながら、しっかりＰＲを進めていきたいと思います。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっと最後に時間があるので、１つだけお聞かせください。３３９ページ、何かあれば、一言だけお聞かせほしいと求めました。","respondent":"中村都市計画課長","answer":"荏原町、来年度を予定しております。それ以降は、今、東急大井町線の中で下神明ですとか旗の台、そういったところも働きかけていきたいと考えております。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"やはり大きな突破口になるのではないかなというふうに思いますので、そういう考え方ではいかがでしょうかということについてのご見解をお聞きします。フラット型は３棟あるということなのですが、１棟はファミーユ下神明、あと２棟の助成金の期間はいつになっているか尋ねました。","respondent":"溝口公園課長、桑波田交通安全担当課長、中村都市計画課長、今井住宅課長","answer":"私のほうからは、大森駅水神口の地下機械式駐輪場の工事をやっている関係で、入庫ブースのスケルトンの関係についてお答えします。そういった中で… 近い方は、なるべく自転車のご利用は控えてくださいということで、これまでも訴えてきたところです。具体的な案等が出てくると思いますので… いや１０年、２０年、こういったスパンの中で考えていく必要があると考えております。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"区民住宅のほうですけれども、これはどうするのですかね。それをどのように考えていくのか尋ねました。","respondent":"桑波田交通安全担当課長、中村都市計画課長、今井住宅課長","answer":"大森駅周辺の駐輪場の整備状況ですけれども、大田区のほうについても、また新しくつくるというような状況は今のところ把握しているところではございません。専門家を入れて、そういった意見も聞きながら、取り込みながら進めていきたいと考えております。ある程度、一定程度の時間をかけて… フラット型家賃の１５年間終了に伴います対策についてですけれども、入居時、そして毎年の助成額の決定のときに通知を差し上げているところです。","id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それと、今出ていたので、３４１ページ、八潮地区のまちづくり、この辺をもう一度伺います。委託ですから、こんなところが留意点であるよと、今までのご答弁以外であれば教えてほしいと求めました。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"そういったところまで、さらに深く掘り下げる形で、皆様の意見をお伺いしながら進めてまいりたいと考えております。そういった中で、交通、賑わい、治安、先ほど委員がご指摘されました項目、個々に… 水辺の賑わい創出構想検討委託についてです。品川区内のいろいろな水辺のそれぞれの性格によって、どんな賑やかしができるかどうかということを、現状を踏まえて検討していきたいと考えています。","id":"exchange-076"},{"speaker":"渡辺委員","kind":"質問・要望","question":"この辺は、地域要望も多いと聞いていますので、拠点づくりの、今の内訳も含めた要望が結構あると思いますが、ぜひ検討いただきたいのが１つ。この辺も具体的に、区がリーダーシップをとって研究される必要性も含めて、お考えを伺えればと思います。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"他地区でもこういった団地の中で建替えを達成するまでに、２０年ほど検討に要したというところもあります。これも、地域の皆様のご意見も伺いながらというところになるかと思いますけれども、そのような進め方で考えております。 艇庫等の設置ですけれども、水辺の拠点としてどこがふさわしいのか、検討してまいりたいと考えています。様々な方法で、水辺の景観をどのように向上していくかというものを、委託の中で考えていきたいと考えております。","id":"exchange-077"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そして、という、何となくストーリーがある中で、計画と実施の、もう一度、スケジュール観と言うのですかね、この構想の検討の後どう生かしていくか。大変強い要望があって、会議体が招集されて、この４月にということで。","respondent":"和田河川下水道課長","answer":"先ほど申しましたように、２１７の運行をしたわけなのですけれども、しながわ水族館とか大井競馬場のご利用の提案がありませんでした。今度の４月１日と２日に、警視庁それから海上保安庁のご協力もいただきながら、河口部でマナーの啓発活動を行うというものです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"それに関わって、補助２９号線道路計画についても伺います。駅の北側と南側、それぞれ伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちら、五丁目１９番地区というところになります。駅の北側におきましては、ただいま、五丁目１０番地区におきまして、再開発等の勉強会等が行われているということで伺っております。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"その北側の五丁目１０番のところは勉強会ということですけれども、具体的な高さですとか、階数とか、用途というのは、わかりますか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"五丁目１０番地区につきましては、まだ勉強会です。具体的な高さ等につきましては、今後、地権者の中で詰めていくような形になります。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"手続きなど、スケジュールも合わせて、それぞれ伺います。そして、北側のところの勉強会は、どんなことを検討しているのかも伺います。","respondent":"東野まちづくり立体化担当課長","answer":"勉強会等が行われているところにつきましては、そちらの情報を注視しながら、区としての支援を今後考えていきたいというふうに考えております。現在、こちらについてもまちづくりの勉強会を立ち上げているところですので、その辺の情報についても収集しています。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"どういう検討をして、勉強会でやっているかというのもお聞きしたので、わかる範囲でそれをご答弁ほしいと求めました。過年度の検討成果もお聞きしましたので、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"それから過年度の検討成果ですけれども、特定整備路線沿道まちづくり推進費という中で、この地区についても考えられてきたところです。具体的に言いますと、こちらが過年度の検討の成果だと考えていますので、それらをもとにまちづくりを進めてまいりたいと思います。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"具体的に、戸越五丁目１９番の再開発についても伺いたいと思います。直近で事業化が予想されているということで、組合の認可や建物の解体・着工、完成などのスケジュールを伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"平成２９年度都市計画決定を予定するということになりますと、それから組合の認可につきましても、同じ平成３０年度が予定されます。建物の竣工につきましては、平成３３年度から、遅くとも平成３４年度ぐらいにはなってくるのかと思います。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問","question":"計画内容はどうなっているでしょうか。階数、高さ、用途、延床面積、そして総事業費、補助金、公共施設管理負担金、委託会社を伺います。","respondent":"東野まちづくり立体化担当課長","answer":"延床面積が約２万１,０００m2、金額的なところは、まだ情報については入ってきておりません。それから委託会社、こちらは事業協力者という意味でいきますと、大成建設が事業協力者になっております。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問","question":"土地、建物、借家、借地などの権利者について、全体が何人で、何人が参加・加入しているのか伺います。先ほどの大成建設は、参加組合員ということでよろしかったか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"借家人につきましては、増減あるところなのですけれども、私どもに届け出がある範囲では７５人というふうに聞いております。先ほどの土地建物所有者、借地権者２１件のうち、１９件が今、参加を表明しています。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"この１９番の再開発と、補助２９号線はどう関係しているのかも伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"五丁目１９番のところの再開発の範囲につきましては、今、０.３ｈａほどありますけれども、補助２９号線のところに一部かかってあります。先ほど委員からもお話がありました、公共施設管理者負担金という中での処理をしていくというふうに、私どもは聞いております。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"この１９番のところを、補助２９号線から立ち退かなければならない方の入居先にしようというお話もあるのか、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの五丁目１９番の再開発計画の１つのコンセプトとしまして、補助２９号線、またはほかの特定整備路線にかかる方の住居の受け皿としてつくっていきたいというようなことも聞いておりますので、そういう可能性があると思います。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"この商店街の分断で、住民にどういう影響を与えるのか伺います。地域商業機能の低下も、住民にどういう影響を与えるのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"ただ単純に危惧しているだけではなくて、今後のまちづくりを地域の中で考えていきたいというところで、この再開発計画も出てきたところです。区としては、そういったまちの声に対して、支援をしていきたいというふうに考えてあります。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"地域の方も危惧しているところで、この補助２９号線を、それが原因なわけですから、これをやめていけば、そういった課題はないわけでありまして、この補助２９号線を、そういった面からもやめていくべきだと思いますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"商店街の皆様のご意見を１つ取り上げてみますと、もう１０年以上前から、今まで様々な検討をされていらっしゃいます。協議会の方針として、そして区と、また東京都が連携して進めているものです。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"そんなところに超高層がふさわしいと思うのか、伺います。この面からも、超高層はふさわしくないと思いますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"この駅前の再開発につきましては、地元の皆様方がこのようにしたいという考えの中で、区としても支援をしているものです。この高さ自体が、すなわち皆様のコミュニケーションの障害になるという、そういったご意見は伺ってはいないところです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"区がどう考えているかということもお聞きしましたので、これがふさわしいと思うのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"区といたしましても、地元の皆様のそういった意向も踏まえて、また可能な限りの支援をしていくという考えです。こういったものを前向きに受け入れられる地元の方々の意思を尊重して、これからも支援を最大限続けていきたいと、そのように考えているところです。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"私は、３１７ページの交通安全啓発費、それから３２７ページの道路バリアフリー事業、３２１ページ、ＬＥＤからの質問をいたします。３３１万円余ですけれども、交通安全宣言から５０年ということでありますが、この事業の説明もお願いをしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"ここと連携を図りながら、区としても安全の教育を実施していこうということで、追加しています。これにつきましては、昭和４２年７月に、品川区において交通安全宣言を実施しました。","id":"exchange-092"},{"speaker":"木村委員","kind":"質問・要望","question":"蛍光灯、そして白熱灯、それから水銀灯とありますけれども、３種類の中からどれを取り除き、ＬＥＤに変えていくのでしょうか。その変えるわけというものもお聞かせを願えればと思います。","respondent":"多並道路課長","answer":"街路灯につきましては、国際条約の水銀に関する水俣条約に基づきまして、２０２０年までには水銀ランプ等の製造が禁止されるということを踏まえまして、平成３１年度までに、今の水銀灯をＬＥＤ化をしていくというのを、計画的に行っていこうというものです。","id":"exchange-093"},{"speaker":"木村委員","kind":"意見","question":"平成３１年に全てこの水銀灯がなくなるということでありますが、あと、これらも全て交換をしていく予定なのかどうかというのもお聞かせください。そして、平成３１年を目途に取り替えるということですけれども、先ほどのをお答えくださいとの意見を述べました。","respondent":"多並道路課長","answer":"水銀灯をＬＥＤ化していくのは、平成３１年度までに進めてまいります。ほかの水銀が含まれない製品についても、対象として考えていきたいというのが、今の考えです。","id":"exchange-094"},{"speaker":"木村委員","kind":"意見","question":"このＬＥＤなのですけれども、家庭の中で、普通の生活の中でも十二分に使えるものなのかどうかということも、説明を求めました。","respondent":"多並道路課長","answer":"我々、街路灯でやっているものは、かなり大きい製品でやっているものなのですけれども、それ以外、民生品についても、電気会社に聞くところによると、かなりエネルギー効率が高いということで、環境課のほうでも一般家庭のほうに普及啓発しています。","id":"exchange-095"},{"speaker":"木村委員","kind":"意見","question":"次に、３２７ページの上から２行目、道路バリアフリー事業ですけれども、大井町駅周辺バリアフリー工事、７,０００万円、計上されています。これは、高齢者の方々にとってみれば、大変なバリアになると思いますけれども、これはどうしてなのかも説明を求めました。","respondent":"多並道路課長","answer":"平成２７年から平成２９年の間、平成３１年度までということで、計画的に進めているものです。きれいに平坦化の整備をしていくと、そのような感じでやって、よりよい使い方ができるような形で行っているものです。","id":"exchange-096"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３３９ページ、京浜急行線連続立体交差化、北品川駅前広場整備等検討委託について、お伺いをいたしたいと思います。これもオーダーを出すときに、そういう考えもオーダーの中に入れていただきたいと考えていますが、そのお考えをお願いしたい。","respondent":"東野まちづくり立体化担当課長","answer":"先般行われました京浜急行の連続立体交差化事業の素案説明会と合わせまして、地元のほうに説明をさせていただきました。そういった地元の要望を聞きながら、今、進めているところですので、委員のご提案につきましても一考させていただきたいというふうに思います。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"提案","question":"本当にいいものになってほしいなと思っておりまして、大きさも含めて広告物みたいなところの規制が入ってしまうのかというのがよくわかりません。踏まえたけれども、それを超えてどういうふうにしていくというぐらいの、せっかく提案してもらうのなら、そういうことを１つとの意見を述べました。","respondent":"和田河川下水道課長","answer":"水辺の賑わい創出構想検討ですけれども、一方で、現在の守らなければならない景観というものも一方であります。我々のこの構想のほうもやっていかなければならないというふうに考えてございまして、検討を進めてまいりたいというふうに考えてあります。","id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"質問","question":"ここをどうやって、やはりそこは超えなければならない部分があるのだろうなと、すごく感じています。ありかなと思うので、もう一度、ちょっと考え方を聞かせてもらっていいか尋ねました。","respondent":"和田河川下水道課長","answer":"基本的には定期航路を、定期航路とはいえ、途中がしっかりと賑やかでないとだめだという意識も持っていると。先ほど来からおっしゃっている東京都の条例も、その辺を議論を深めていって、検討していきたいというふうに考えてあります。","id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういう提案をして、例えば第四日野小学校の卒業生に記念で配るとか、その板を何枚もつくっておいて。提案をして、そういう片隅を持っていてほしいなと思うのだけれども、考えを説明を求めました。","respondent":"多並道路課長","answer":"今の委員のご提案のとおり、やはり育ってきた学校の周辺でもありますし、やはり地元でも親しまれてきた桜ということですので、よくその辺は、地元もありますが、あと小学校も含めて幅広くご意見をお伺いして、有効活用できるのであれば図っていきたいと思うところです。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問","question":"具体的な方策をとっていくと思われますけれども、今後の、この老朽化への対策をどのように考えていらっしゃいますでしょうか。それについても改めて、行財政改革特別委員会でも少しお聞きしておりますけれども、改めてご説明願います。","respondent":"今井住宅課長","answer":"区営住宅の老朽化への対応ですが、計画的に修繕を行いまして、適切に進めているところです。平成２８年８月に、今後予定されております長寿命化の改修または建替え等を踏まえまして、計画を立てていきたいというふうに考えております。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問","question":"国の制度化された老朽化の観点で長寿命化という策定指針が出た、それに基づいて区としても進めていきたいというお考えを伺いました。１００％に近いぐらい、このバリアフリーの考え方は、その点についてもご見解を説明を求めました。","respondent":"今井住宅課長","answer":"手すりの設置ですとか、そういうもので対応してきたところですけれども、ほかの事業とも連携しながら見守りをしていきたいと考えています。一定、大規模な建替えや大規模な改修の時期に合わせて、大きなバリアフリーは進めていきたいというふうな考えです。","id":"exchange-102"},{"speaker":"こんの委員","kind":"提案","question":"実は平成２４年のときに、エレベーターの設置をというふうに提案をさせていただいた際に、日影の問題でつけられませんというご答弁だったのです。その当時と今とでは５年経っていますので、ここの住宅に関してのエレベーターの設置の可能性というのは、どのようにお考えか尋ねました。","respondent":"今井住宅課長","answer":"２カ所の大きくエレベーターを設置できる場所といっても、エレベーターの設置というのは、協議はしていますけれども難しいというふうな状況です。ほかの利用者の方々の状況を考えながら、検討は進めて、今後も続けていきたいと考えています。","id":"exchange-103"},{"speaker":"こんの委員","kind":"質問・要望","question":"理由を改めて伺ったのですが、ものすごく段差が高いのですよね、あそこ。ご答弁もう一言お願いいたします。","respondent":"今井住宅課長","answer":"複合施設であるということを踏まえて検討するとともに、または別の住宅等への住替えなどについても、またきちんとご案内できるように進めていきたいというふうに思っております。","id":"exchange-104"},{"speaker":"こんの委員","kind":"質問・要望","question":"こちらは先ほども質問が出ておりました、確認ですけれども、桐畑隧道を出てきた水神町会のお祭り広場の所を言っているのでしょうか。ここの徹底をどうされているのか、またしていただきたいのですけれども、いかがか尋ねました。","respondent":"多並道路課長","answer":"予定ですと、その後に、今、委員のご指摘にあったような場所を、今後やっていこうというところで、考えています。設置した後、そこの有効性というのは検討していきたいと、やっていきたいと思っているところです。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"そちらの、今の４つの駅の駐輪場の稼働率と言うのでしょうか。それから利用状況についてのご見解と、ここの人口増加の中で、それに対する今後の見通しについてお伺いいたします。","respondent":"桑波田交通安全担当課長","answer":"品川シーサイドにつきましては７４.９％ということで、それぞれの場所によって、需要、利用について大分差があるところです。そういった需要を含めまして、民間を含めて、今後また設置に向けて考えていくことが必要であると考えております。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問","question":"立会川のほうが８３％、あとシーサイドも、かなりマンションも多いということで、７４.９％ということであります。見通しで、少し探していくというお話でしたが、見通し的にはどのような状況か尋ねました。","respondent":"桑波田交通安全担当課長","answer":"民間も含めてやっているところです。そういったところも含めましてご案内して、ご利用いただくように進めていきたいと考えております。","id":"exchange-107"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"立会川のほうも、ぜひ今後の増加に備えて、用地の取得について動いてほしいと求めました。このような駐輪場、立会川・勝島まちづくりビジョン策定の中でどのような観点で計画案を立てていかれるのか、お教えほしいと求めました。","respondent":"中村都市計画課長","answer":"当然考えていく必要があると考えていますが、周辺の駅まで利用されるというところにおきましては、所管と十分調整をしながら進めていきたいというふうに考えております。","id":"exchange-108"},{"speaker":"高橋（し）委員","kind":"質問","question":"いろいろまちづくりの計画等が進められていますが、一般質問でもお尋ねしたのですが、マスタープランの中ではあまり具体的には出てきておりません。この人口増加について、東品川地区のまちづくりについて、改めて具体的にどのような取組みをなされるのか、お教えください。","respondent":"中村都市計画課長","answer":"四丁目で再開発が進められておりまして、マンションなども建替えも進んできているというところで、この辺を調和していくべき町並みの誘導を行っていきたいというふうに考えております。","id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今後この辺の東品川の地域をどういうふうにしていくかという、そういう話し合いの場を、これは要望としてお伝えしておきます。これは東京電力から借りているのだと思うのですが、今の月見橋の家が元に戻った場合、そこの場所をどのようにしてまた復旧していくのか尋ねました。","respondent":"溝口公園課長、和田河川下水道課長","answer":"平成２９年度に設計を行っていきますので、地域の声も聞きながら、検討していきたいというふうに考えているものです。これにつきましては段差をなくすという観点で工事を行いますので、階段等はないような形での工事を考えているもので… 一番北側にありますトイレの横に、高さ４ｍの六角柱、直径で言いますと３ｍぐらいの換気塔を作る予定です。仮施設を建てているものですが、その後の用途につきましては、今後検討してまいりたいと思っているところです。","id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"受託事業でそれを使って、従前、あるいはそれ以上の公園にしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"提案","question":"１つの提案なのですけれども、例えば角の場所を品川区が借り入れをして、イメージは渋谷のスペイン坂スタジオってご存じでしょうかね。まだ間に合うと思うのですけれども、検討すべきと思うのですが、いかがでしょうかという質問ですとの意見を述べました。","respondent":"多並道路課長","answer":"国道事務所と連携しながら進めてまいります。事業を進めている中で、全体的な中の、総合的に検討してまいることだと思っているところです。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"提案","question":"しかも目立つ角の場所ですから、品川区役所のイメージアップになると思うので、ぜひ検討をお願いをしておきます。いろいろな構想ができると思うのですが、構想として持っているのですが、いかがでしょうかという提案ですとの意見を述べました。","respondent":"溝口公園課長","answer":"はご理解、そういったものをいただきながら、公園の管理を進めてきているというところではあります。そういったものを考える際に、公園の管理も含めまして、検討していきたいというふうに考えているものです。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"提案","question":"その将来は、当然、この品川区民公園全体を考えていくこともあるでしょうし、水族館だって、毎年何千万円もかけて運営していくわけではないですか。５年、１０年、いかがか尋ねました。","respondent":"溝口公園課長","answer":"一方で、そういったところも踏まえながら、今後のあり方というのは検討していかなければいけないというふうに考えているところです。運営しておりますサンシャイン、または近隣の方のご理解をいただきながら、十分検討していきたいというふうに考えているものです。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"今、思い出しましたけれども、この水族館、閉園も含めた議論、相当されたではないですか、内部の検討会をつくって。それからベンチ、それから休憩する場所等の拡大も検討していくべきだと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"そういったところも含めて、いろいろ検討していきたいというふうに考えているところです。レストランも含めまして、平成２９年度に少し検討していく費用も予算化しておりますので、しっかり検討していきたいというふうに考えているものです。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問","question":"それから事業者を選定するのは時間がかかるでしょうから、それは１つのアイデアとして、いろいろな社会資源を使うことは今できるはずですよ。やってほしいけれども、そういう移動販売車等の活用をすべきと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"ケータリングカーについても、導入したりとか、そういったところも取り組みながら進めてきているところです。リピーターとして水族館に来ていただける、そういった取組み、できることから着実に進めていきたいというふうに考えているものです。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"私も一般質問でこのことを提案させていただきました。小学校や中学校の数も、やはりこのまちのあり方はもっと検討すべきということを提案させていただいたのですが、お答えをくださいとの意見を述べました。","respondent":"中村都市計画課長","answer":"生活施設ですとか、あるいは公共施設、こういったものの方向性についても含めて検討していく必要があると考えております。立会川地区と合わせて検討いたしますので、立会川地区との連携の仕方ですとか、こういったものも重要になってくるかと思います。","id":"exchange-117"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、３４７ページの大井町駅周辺地区再開発事業と、３５９ページの区営住宅について伺いたいと思います。６,０００万円という大きな金額ですので、詳しく説明を求めました。","respondent":"稲田都市開発課長","answer":"それからもう１つ、単独検討ですが、これは１,５００万円、これは区の検討です。区の庁舎の再配置の検討や、また導入施設等がどういうものが考えられるのか、そういうところを検討していきたいというふうに考えております。","id":"exchange-118"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません、どこに委託をそれぞれされるのか、伺いたいと思います。それと、大井プレイス構想での、ここの広町の位置づけなども伺いたいと思います。","respondent":"稲田都市開発課長","answer":"ＪＲとの共同検討におきましては、ＪＲと協議しながら、また決めていくということになっていきます。その後、大井町のまちづくりの構想等も立てておりまして、それに沿った形で、この開発やまちづくりを考えていきたいというふうに考えております。","id":"exchange-119"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それなのに、これだけ６,０００万円という金額だけが決まっているというのが、ちょっとわからないのですが、そこを伺いたいと思います。やはり、大井プレイス構想、具体化ではなくて、住民参加で住民が望むまちづくりを進めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"委託先ですが、やはりこれはＪＲとの協議を、今後詰めていくというところでございまして、それによって決めていくです。大井町、広町、これもまちづくり構想がありますので、これに沿った形で考えていくです。","id":"exchange-120"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"風呂釜の設置や撤去について伺いたいのですけれども、事務事業概要では１３団地４３９戸ということでいいのか、ちょっと確認させていただきたいのと。そして、設置していない世帯があるのか、伺いたいと思います。","respondent":"今井住宅課長","answer":"長く入居された方もいらっしゃいますけれども、自己負担で設置し、退居の際は撤去をお願いするというのがルールで運用してきたものです。風呂釜の設置が全くないというところの住戸につきましては、把握をしておりません。","id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問","question":"区営住宅は、要は所得が低い人が入っているのに、この自己負担はとても厳しいと思わないかどうか、区の見解を伺いたいと思います。ぜひ、区営住宅も、区の責任で設置していくと言うことに踏み込んでいくべきだと思うのですけれども、いかがか尋ねました。","respondent":"今井住宅課長","answer":"建替えを行っていく中で、浴室の設置を含め、バリアフリー化を進めていく考えです。計画的に浴槽の設置を進めるというふうには聞いておりますが、現在も都営住宅で設置をされていないところもあるというのは、品川区同様です。","id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、低所得者の住宅にはつかなくてもいいということなのでしょうか。区にもこの目標はあるのか、伺いたいと思います。","respondent":"今井住宅課長","answer":"品川区の区営住宅に対する浴槽設置の考えですけれども、こちらのほう、建替えに伴って進めていくというふうな考えです。建替え等を進めているところですので、風呂釜の設置について、区負担で設置する考えはございません。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もしつけられていない世帯があれば、まるでこの水準を満たしていない住宅を、区が提供しているということになるのではないでしょうか。ぜひ目標を持って、計画を持ってほしいと求めましたけれども、いかがか尋ねました。","respondent":"今井住宅課長","answer":"１人当たり２５m2というところで、１人ずつ増加している中で、一定の面積が配分されているものです。品川区の区営住宅、そして区民住宅等とともに、この国が定めました住生活基本法におけますこの水準をきちんと満たしています。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問","question":"浴槽について、私、伺ったので、ぜひそこに答えていただきたかったのですが、残念です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"それから、時間があれば、３３５ページの目黒川障害物調査について伺いたいと思います。そしてどんな交通手段を使っているかという調査をしているそうですけれども、こういう調査も合わせて活用しているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"こういったものを、将来の交通計画を考える上での統計ということで、行っているです。したがいまして、品川区もこの統計を参考にして、計画を立てているです。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"今のはパーソントリップ調査を参考にして計画を立てているという答弁ですので、どんな計画があるのか教えてほしいと求めました。この延長１００ｍと、幅員１６ｍということだそうですが、ご説明をほしいと求めました。","respondent":"多並道路課長","answer":"ここの補助１６３号線の今後の整備のあり方とか、一緒に連携を図りながら、ここの大井町周辺の基盤整備というのは考えながら一緒に進めております。東京都とも連携を図り、全体的な調整のところも進めて、総合的な観点で進めていくべきだと考えるところです。","id":"exchange-127"},{"speaker":"若林委員","kind":"質問・要望","question":"補助１６３号線について、目的と、特に成果、ここをしっかりとご答弁ほしいと求めました。いわゆる路線バスがなかなか法律上通れない、こういう課題がありましたので、そこはしっかりとご答弁を。","respondent":"多並道路課長","answer":"安全上の課題があるということで、認可をするにはその辺が課題だろうということで、話を聞いているところです。ここのボトルネックの解消に向け、早期整備を進めたいということで、平成２９年度も予算計上させていただいたところです。","id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"この補助１６３号線、こういった課題の１つが大きく進展をするというふうに理解をしますので、頑張ってほしいと求めました。予算・決算の委員会でも取り上げたところですので、調査、または工事の概要をご説明ほしいと求めました。","respondent":"和田河川下水道課長","answer":"五反田リバーステーションが、オリンピック・パラリンピックまでにできるということで、舟運が活性化することが見込まれます。平成２９年度、１年かけまして、３年計画でやっていきたいというふうに考えているものです。","id":"exchange-129"},{"speaker":"若林委員","kind":"質問・要望","question":"しっかり進めてほしいと求めました。除去することによって、少しかさが上がるかということは、あるのか尋ねました。","respondent":"和田河川下水道課長","answer":"喫水の関係で、それはございません。","id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"４目都市開発費、３４９ページ、再度伺いたいということ。近隣との折衝というか、トラブルがなかったかどうか、その辺をまずお聞きしたいと思います。","respondent":"多並道路課長","answer":"舗装してまいりまして、１７５m2ほど、全体的に施工したところです。地元の件ですけれども、１軒１軒お話しさせていただいて、ご了解をいただきながら工事を進めたです。","id":"exchange-131"},{"speaker":"松澤委員","kind":"意見","question":"そして、狭い所は売却するというような方針になっていると思うのですけれども、これは、どれぐらいの広さだったら道路として開放していくのか。このように囲い込まれている土地というのはどのぐらいあるのか、その辺、お知らせほしいと求めました。","respondent":"安井土木管理課長","answer":"若干囲い込みされている、不法占有されているような所が７８路線ぐらいございまして、その辺を順次指導をしているといったところです。大体は、もともとが水路で細い所が多いのですけれども、必ずしも一定というわけではないというところが、実態です。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"なおかつ、２軒にまたがっている、当然そうですよね、境ですから。この辺、何か要件が緩和されているということはあるのでしょうか、その辺をお聞きしたいと思います。","respondent":"安井土木管理課長","answer":"それぞれに行いながら、不法占有の解消、そちらのほうを対応していると。普通財産の処分については処理を進めることができるようになりましたので、そういった点でも、さらに進めていけるような形になってあります。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"これはどういうことなのですかね。今の話ですと、公共溝渠は、買いたい人が、自分たちで測量するということなのか尋ねました。","respondent":"安井土木管理課長","answer":"私どもとしては、不法占用の早期解消ということで、測量を積極的に、区のほうで負担いたしまして、さらに、測量するということで、不法占有の状態にあるということをご認識いただくということで、少しでも不法占有の解消を進めるという形で、事業を進めてあります。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"他人、ほかの方がいるものですからね。これについて、その後、どのような形で、地権者の方にお話をして、交渉が進んでいるのか尋ねました。","respondent":"今井住宅課長","answer":"平成２８年の一定のときに、総合的に検討してまいりますということで、処理経過を差し上げたものです。その部分の不適切な部分については改善していただくようお願いいたしまして、実際に、所有者の方が対応していただいたところです。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問・要望","question":"都市防災まちづくり事業に関連して、イトーヨーカドー跡地をもう一度伺います。区や地元が要望している店舗というもの、改めて見つかったのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"同店跡地につきましては、解体工事前の地盤調査を先行して行うというふうに聞いております。店舗探しにつきましては、歳入でもお話ししましたとおり、立地上、収益性上から、難航しているというふうに聞いてあります。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"歳入で質問の際に、区が借りることも検討しているというお話を伺いました。こういう民間のものを、どんな検討をしているのか、この辺をちょっとお聞きしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"店舗が見つからないという場合に備えまして、地元のほうからの要請もありますので、全部賃貸マンションにするよりも、地域にある行政ニーズに応えられるためのスペースを区が借りまして、施策展開していくというところを検討しています。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"ちょっと伺いたいのですけれども、これは賑わいにつながるのではないかなというふうに思っているのですが、この辺はいかがでしょうか。検討の余地はあるのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"地元の要望につきましては、賑わいの観点から店舗を入れてほしいということですので、私どものセクションとしては要望を続けてまいりたいと思います。区としての施策展開ということになりますので、委員ご提案も含めまして、担当所管とも調整してまいりたいと思います。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"要らないのではないかという声もありますけれども、なぜこれが基本設計委託、直すのでしょうか。あるいは何か、直してほかの使い方というものを考えているのでしょうか、その辺お聞きします。","respondent":"溝口公園課長","answer":"戸越公園につきましては、その管理事務所も老朽化、倉庫も含めて老朽化していることから、建替えというのを考えているものです。そういったものも含めて総合的に戸越公園の管理事務所の使い方を考えるために、設計の費用として、予算計上しているものです。","id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"荏原第四中学校の跡地に、今後２つですか。保育園に変えてやっていくということなので、それでは建て替える期間が足りないということで、ここにしましょうということなのか尋ねました。","respondent":"溝口公園課長","answer":"今ある倉庫も含めて、全体のところを見直し、改修をしていきたいというふうに考えているところです。戸越公園のところにつきましては、一応、今のところ、予定で行きますと、三ツ木保育園の改修に合わせて必要なものということで聞いているところです。","id":"exchange-140"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、その後、先ほども言われたように、その後の転用策を考えなければいけないというふうに思うのですね。あるいは恒久的な施設としてやっていくのか、その辺が本当に重要になると思うので、その点についてお聞きしたいと思います。","respondent":"溝口公園課長","answer":"平成３３年、平成３４年、２カ年の仮園舎としての使用を考えているところです。ただ、今後どういう形で、それ以降使っていくのかというのも、合わせて検討していきたいというふうに考えているところです。","id":"exchange-141"},{"speaker":"松澤委員","kind":"質問","question":"傾斜が急ですから、自転車が飛び出してくるのですね、それがある所。当然、品川区でしょうから、その点の考え方というのを聞いておきたいと思います。","respondent":"多並道路課長","answer":"地元の方からご要望がありまして、また警察とも協議して、今ご指摘いただいたような形にしています。ただ、またよりよい形があるのであれば進めていくところなのですけれども、なかなか限界があるのかなというのは感じているところです。","id":"exchange-142"},{"speaker":"藤原委員","kind":"意見","question":"もう２週間ぐらいしかないですけれども、これがどういう状況になるか、お答えください。３３５ページ、これはどういう経緯でああいう形になったか、お答えくださいとの意見を述べました。","respondent":"今井住宅課長、和田河川下水道課長","answer":"今回の定例会のほうに、２０年間の借上げの満期を迎えました２住宅のほうの返還ということで、議案のほうを提出しています。平成３１年度に１住宅、平成３１年度には、この地優賃の住宅はゼロという形になります。この設計変更の設計が完了いたしまして、３月いっぱいで家屋調査を行い、４月に工事を再開する見込みというふうに。","id":"exchange-143"},{"speaker":"藤原委員","kind":"質問・要望","question":"これの確認が１点。それと、３４３ページの天王洲公園の改修とか、３４５ページの八潮北公園の改修が出ていますけれども、この工事について、目的を説明を求めました。","respondent":"柏原企画調整課長、溝口公園課長","answer":"区を挙げて、このオリンピック・パラリンピックに向けての機運醸成ということでは、全力を上げたいというふうに思ってあります。景観の問題であったりとかありますけれども、なるべくそういうところをうまく使いながらということで… そういった中で、全てのトイレを１回、利用者が多い所については２回、清掃しています。いずれにいたしましても、オリンピック・パラリンピック機運醸成に向けた、公園課としての取組みの一環として行ってきたというのが、実情です。","id":"exchange-144"},{"speaker":"藤原委員","kind":"質問","question":"区は、このスポーツの動向の高まりをどう捉えているのでしょうか。これについてちょっとお伺いしたいのですけれども、この便所に関して、どう臭いを感じられているのか、教えていただけますか。","respondent":"小川オリンピック・パラリンピック準備課長、立川経理課長","answer":"１点目の、オリンピック・パラリンピック大会を契機としたスポーツの高まりにつきまして、お答えします。引き続き根づかせていくことこそが、ソフト面のレガシーという観点からも大切であるという考えのもと、事業を推進しています。 無洗浄式便器というのを導入しておりまして、ちょっと女性の委員の方はぴんと来ないと思いますので、ちょっと導入の経過等を説明します。委員ご指摘のとおり、人によっては臭いが気になるなどの課題があると考えているところです。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問・要望","question":"何か答弁があればいただきたいのですけれども。この土木部門とスポーツ部門、それとオリンピック・パラリンピック部門という形で、それぞれ、その公園に関してお答えをいただけますか。","respondent":"立川経理課長、溝口公園課長、小川オリンピック・パラリンピック準備課長","answer":"日常清掃に加えまして、詰まりの防止や臭気の軽減等を図っていくこととしましたので、今後とも快適にご利用いただければというふうに考えております。オリンピック・パラリンピックに向けた、それぞれ庁内での連携です。はスポーツ推進課、しっかり連携して… 例えば八潮北公園のスケートボード場の整備につきましても、同様なことが行われております。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"せっかくスポーツ推進課長が出てきてくださったのですから、スケートボードができるわけですから、オリンピック・パラリンピック部門が代表しないで、スポーツ推進課長も答弁をお願いします。","respondent":"池田スポーツ推進課長","answer":"３課連携いたしまして、これ１つを目標にいたしましてやっていきたいと思いますので、ご利用のほうをよろしくお願いいたします。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"３課だけではなくて、全庁挙げてやるのですから、３課中心に、全庁挙げてやってほしいと求めました。私も、２０２０、オリンピック、大成功することを祈って、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"あべ委員","kind":"質問","question":"ただ、午前中のご答弁では、２１７便で１,３００人と聞こえたのですけれども、これは１便当たり６人という数字になるのでしょうか。私はもう、それは１つの選択肢だと思うのですが、どのように考えて行っていらっしゃるのかというお気持ちを伺いたいと思います。","respondent":"桑波田交通安全担当課長、和田河川下水道課長、柏原企画調整課長、稲田都市開発課長、鈴木建築課長","answer":"年に３回ほど、大井ふ頭対策の会議ということで、対策を進めているところです。大井ふ頭で荷待ち、年度末を目途に実施していくというようなお話がご… 平成３０年度中に建築工事を着工、平成３１年度中に建築工事を完了し、元の場所に戻っていただくというスケジュールでやっているものです。… 月見橋の家の仮設が戻った後の土地の活用ということであろうかと思います。","id":"exchange-149"},{"speaker":"あべ委員","kind":"質問・要望","question":"あの道の部分、今の段階で、拡幅に向けて動いているのでしょうか。動き出す可能性はあるのか尋ねました。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"４３カ所以外の、助成制度も含めて、周知していきたいというふうに考えてあります。そういう中で、委員おっしゃったようなことも話をしましたけれども、それは難しいというような回答を得ております。","id":"exchange-150"},{"speaker":"あべ委員","kind":"質問","question":"御殿山小学校西側の道については、もし、スケジュール的な目途があれば、教えてほしいと求めました。この交渉が難航している背景に、放射第２号線の話もあるとお考えか尋ねました。","respondent":"稲田都市開発課長","answer":"私どもとしては、それは関係ないというふうに思っております。","id":"exchange-151"},{"speaker":"飯沼委員","kind":"質問","question":"３３９ページの特定整備路線沿道まちづくり、３４３ページのトイレ改修工事について伺います。一刻も早く、ＬＧＢＴ対応のトイレ、必要と考えますが、いかがか尋ねました。","respondent":"中村都市計画課長、島袋人権啓発課長","answer":"東京都が進める道路の整備に合わせまして、そういったことに要する説明会、また資料作成等の委託費です。 ＬＧＢＴ、あるいは性的マイノリティーの方に対する差別や偏見などは、様々な人権課題の１つであると考えております。国や都の動向を踏まえた上で、関係部署との連携をとり、対応をしてまいりたいと考えております。","id":"exchange-152"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住宅建替えは、耐震化、不燃化、そして公園づくりなどに、住民の願いに、切実なところに応えるべきと思いますが、いかがでしょうか。今日はトイレのことで言いましたけれども、ぜひ区役所に、ＬＧＢＴの指針づくりなど検討会の設置を求めますが、いかがか尋ねました。","respondent":"中村都市計画課長、島袋人権啓発課長","answer":"こういったことを総合的に、重層的に進めることによって、不燃化がより一層加速するものというふうに考えております。合わせて、耐震化のほうも、品川区内で取り組んでおりますので、委員ご指摘のところも含めて… 人権尊重都市品川宣言を活用し、普及・啓発を、地道ではありますが、積み重ねてまいりたいと考えております。","id":"exchange-153"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご要望・ご意見が届かないというところに、ぜひ、この間も質問したのですけれども、声が届かないというのは、見ようとしなければ見えないのですね。道路ごり押し、やめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-154"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それから最後に、３５７ページの空き家等対策事業でお伺いします。本会議の代表質問で、ブロック塀対策についてお伺いをしまして、周知については個別に説明をしていきますと。","respondent":"多並道路課長、鈴木建築課長、今井住宅課長","answer":"この平成２９年度予算の中で計上させていただきまして、踏切が１５ｍぐらい、より通行が円滑にできるような形ということで考えているものです。… ４月頃には作成し、ホームページ等で公表というか、配っていきたいなというところです。作成したチェックリストですとかパンフレットをお渡しして… 平成２８年７月から、または適正管理に対するご相談またはご苦情、所有者からのご相談等をお受けしているものです。","id":"exchange-155"},{"speaker":"たけうち委員","kind":"質問・要望","question":"しっかりその辺の計画も、国や都の動きと合わせてしっかり連動してお願いしたいなと、これは要望します。その辺のところを、では、ちょっと状況を説明を求めました。","respondent":"多並道路課長、今井住宅課長","answer":"もちろん１日でも早く工事をやりたいところなのですけれども、それを整え次第、１日も早く工事をやっていきたいと思っているところです。空き家ホットラインにつきましては、今、ホームページ等で周知しておりますけれども、確かにまだまだ周知が足りないところです。","id":"exchange-156"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大きなマンション計画が、今、大きいのが２つ続いています。この辺のところで、東品川のあの一画の関係をどう捉えていくのか、その点を説明を求めました。","respondent":"多並道路課長、中村都市計画課長","answer":"その中で今、国も非常に大きく進めていまして、ＩＣＴの紹介というのがいろいろあります。今後も、そういうようなものを踏まえながら、より道路のＩＣＴに向けた活用ができないかということを検討していきたいとは思っているところです。今、この地域に必要な施設のほうの整備を行い、マスタープランに示しております広域都市活性化拠点ゾーンとしての整備を進めてまいったところです。","id":"exchange-157"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"昨年のときには、まだ診断していないところがあるよと聞いていたのですが、そこがどうなったのかを教えてください。何かと言うと、オリンピックに向けて、ここの土地をどういうふうに交渉するかという、その辺の検討はされているのか尋ねました。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"消火活動や物資の輸送のための復旧・復興の生命線、大動脈となる道路の確保というところで、東京都が条例によって１３路線指定しています。平成２３年より取組みを進めているところですが、沿道対象建物が２０４棟ございまして… 広町の件です。平成３０年１２月には解体工事が完了するということで、利用は今のところは考えてはいないのですが、話はしています。","id":"exchange-158"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どう考えるかというのは、非常に、逆に聞きたくなってしまいます。これは課長でいいのか、区として今後どう考えるかというのは、どう考えたらいいのか尋ねました。","respondent":"稲田都市開発課長","answer":"確かに、建物が解体されていくと、広い土地ができるですが、ＪＲはＪＲで、この暫定の間、何らかの活用は考えているというふうに思われます。ただ、そういう中におきましても、区としての要望は伝えていきたいというところに考えております。","id":"exchange-159"},{"speaker":"鈴木（真）委員","kind":"質問","question":"長期的には平成３２年以降の検討ということをお聞きしていますし、区の単独の、庁舎の改築とかという問題も十分絡んでくると思うのですけれども。人の集まってもらえる場所にするべきだと、私は考えるのですが、あえてもう一言お答えいただけないか尋ねました。","respondent":"柏原企画調整課長","answer":"本格的な活用は検討ということではあるのですけれども、これだけ大きな土地が出るというのは、なかなかないというのは事実です。相手のあると言いますか、土地でありますので、そこは話を続けながらということになろうかと思います。","id":"exchange-160"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２３区の中でも、駅前にこれだけの土地ができるというのは、まずないと思うので、ぜひ成功に向けて頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-161"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/307926?Template=document&Id=1064#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":133282,"voices":401}},{"id":"h29-20170315-3","meetingId":"h29-c-budget","date":"2017年3月15日","dateIso":"2017-03-15","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件整理しています。","topics":[{"id":"topic-01","title":"平成２９年度品川区一般会計予算","agenda":"平成２９年度品川区一般会計予算","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"しかし、この６年間、一度も放射性物質が検出されていないとの報告を受けておりますが、これで間違いないのか確認したいと思います。今回、昨年の２５０万８,０００円から１２１万２,０００円と半減しておりますけれども、この内容についてお知らせほしいと求めました。","respondent":"有馬学務課長","answer":"委員ご指摘のとおり、この検査は３月の震災の後、１２月から実施しているものです。全校年１回としておりましたストロンチウムの実施方法を見直して、これは３カ年で全校検査をするというような回数の見直しを行ったものです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問・要望","question":"なぜストロンチウムの実施方法を見直されたのか、また検査の頻度が３年に１回ということですけれども、その根拠をお聞きしたいと思います。年２回実施しているということですけれども、なぜストロンチウムの見直しをし、説明してほしいと求めました。","respondent":"有馬学務課長","answer":"ストロンチウムの実施方法をなぜ見直したのかですけれども、汚染水問題が出たときに始めたということで、平成２６年度から始めております。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"今、伺いましたけれども、ということは、３年に１回にしましたということは、このまま３年間、結果的に続けてみる、続けるということなのでしょうか。その点をお聞きしたいと思います。","respondent":"有馬学務課長","answer":"今後、また汚染水の状況が変わったりしましたら、そのときは適切に判断してまいりたいと思います。現段階では、先ほど申し上げましたとおり、３年間に１度というような考えで実施したいと思ってはおりますが確定したものではございません。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"検査費用が安価とはいえ、役割は終わったのではないのでしょうか。原発いじめをなくすためにも、しっかりと調査すべきではないかと思っていますけれども、ご見解をお伺いいたします。","respondent":"有馬学務課長","answer":"当然、ヨウ素・セシウムにつきましても検討を行いました。２３区の状況も見まして、まだ半数以上の区で実施しているという状況もございまして、これについてはしばらく継続していこうという考えです。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"今、出荷制限の現状について、様々な食材の中でも出荷制限があるというお話も聞いています。現状と、市場の食材の安全性はどのようになっているのかお聞きしたいと思います。","respondent":"有馬学務課長","answer":"基本的には、関東甲信越でもそういうことで出荷制限にかかっているものもあります。ただし、それはあくまでも出荷制限がかかっておりますので、市場に流通しているものは基本的には安全だとは認識しております。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問・要望","question":"食の安全を守るために実施してきた。風評被害が広がる、そしていじめが広がるという現状の中では、しっかりと精査していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"３６４ページ、３目教育指導費、３７５ページ、図書館経費、３９１ページ、脊柱側わん検診について伺っていきたいと思います。公明党からもそれを提案しているので、当然、それをきっかけとしていじめの原因にもなるというようなことも全国的にはあるようでありますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"いじめアンケート等を含めて学校からこちらに上がってまいりますが、そういう件については、現在のところは私のほうに入っている状況ではございません。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"私も実体験としてあるわけですから、冒頭申し上げたとおり、便育の取り組みが非常に大事ではないかと考えています。その絵を指摘しながら、非常に共感するところであるわけでありますけれど、この便育に関する取り組みについて説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"小学校に入ったときに、新１年生にはガイダンスとして、トイレの使い方等をまずしっかり子どもたちに伝えます。我慢するということではなく、健康のためには十分必要であるというようなこと、その辺についても指導はしています。","id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"機会を通じて様々提案してまいりたいと思います。なので、過去にも提案させていただきましたが、その後の検討状況を説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"具体的に各学校で何か取り組みをということはこちらのほうには入っていないのですが、校長先生が先生方に対して、「笑点」を見ようと。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"改めてですけれど、品川区でも教師の方にお伝えしているということも伺っておりますので、取り組んでいただけることを検討ほしいと求めました。なので、返却ボックスが、そういう大型図書でもちゃんと返せるような改善というのは対応できますか尋ねました。","respondent":"木村品川図書館長","answer":"あるいはそれを置く場所でありますとか、そういう部分も含めまして、なかなか厳しいかというところはあります。引き続きお知らせなどご案内を丁寧に進めてまいりたいと考えています。","id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"機会を捉えて、そういうボックスなどを入れかえる際には、そういったものも返却できるような口のつくりのものを検討ほしいと求めました。提案というか質問させていただきましたが、図書館での取り次ぎサービスの提案をさせていただきましたが、その後の検討状況を説明を求めました。","respondent":"木村品川図書館長","answer":"実際に検討いたしました。そういうものと何か連携して、引き続き研究してまいりたいと考えています。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"間接的にも、やはり健全な児童・子どもの育成につながるのではないかと思いますので、取り組みを様々工夫してほしいと求めました。次に脊柱側わん検診ですが、これについては、まず現在、今年度からということで、実施状況について説明を求めました。","respondent":"有馬学務課長","answer":"対象は５年生・７年生ということで、成長が著しい時期のお子さんということで設定して行いました。受診率はほぼ１００％に近いという形になってあります。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"その中で、治療が必要な生徒がいたのかどうかなど、傾向性の部分も説明を求めました。","respondent":"有馬学務課長","answer":"中学生のほうは１,５５４人のうち２６人ということで、１.６７％が２次検診です。その結果、最終的に要治療となりましたのが、小学生で８名、０.３５％と中学生で２０名、１.２８％の合計２８名で０.７３％となっています。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"モアレ検査を提案させていただいて導入していただいたわけでありますけれども、当然、現在もやっていただいていると思うのですが。本当に子どもの幸福のために身を削っていける、鉛筆のような教育委員会として、これからも品川区に頑張ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"性的マイノリティーの子どもたちのいじめ被害について、なぜ多い傾向があるのか、教育委員会の見解を伺います。性の多様性について子どもたちが小・中学校で学ぶ機会は、どのような場があるのか、現状を伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そういうところも含めて、子どもたちに対しては、正しい認識・知識を持たせていかなければいけないかと考えているところです。ただ、いわゆる教科指導ではなく、どちらかというと生活指導による個別対応というところで、個々に対応しているのが現状です。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"もう３０年も前のことですけれどもＬＧＢＴなど性の多様性について、当時は授業で異性愛を前提とし、当時の学習指導要領を伺いたいと思います。現在は授業では取り扱っていないということですけれども、今後も含めて授業の中でどのように取り扱っていくのか、お考えも伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"１点目ですけれども、認識が起きたのは、本当にごく最近の考え方だと捉えております。今、先生方に、これについての正しい認識を持たせなければならないというような現状です。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"その学校はどこかということと、私は全ての小・中学校で図書の配置と啓発ポスターの掲示を求めますけれども、いかがでしょうか。そして、新聞などを使用しての授業の話もありましたけれども、性の多様性について教材の作成と授業の実施を求めますけれども、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"「多様な性があることを知っていますか」ということで、こういうものを１つ、形として教員には伝えております。ＬＧＢＴにつきましては当然、教育の大きな１つの課題だと受けとめておりますので、そういうところで連携しながら進めていければと考えています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"２０１３年のホワイトリボンキャンペーンの調査では、子ども時代に何らかの形でいじめや暴力の経験があったと答えたのが７割とあります。伺いますけれども、体が男性で心が女性のトランスジェンダーの場合、学校でなぜこのような傾向があるのか、教育委員会の見解を伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"特別支援コーディネーターを含めて、このＬＧＢＴについてはしっかり、昨年度から本年度も含めて検証を進めています。きちんとした個別対応ができるような体制、いじめ、また偏見等がないよう進めていこうと考えております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"」ということへの誤解が、子どもをはじめ、社会全体に存在しているからではないでしょうか。まずは教育委員会でもチームを作って、抜本的に体制を強めていくことが必要だと思いますけれども、チームを作ることはいかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"教育内容の検討、有効性等、やはり意図的・計画的な施策を準備しなければならないと考えています。学習指導要領が今度、新しいものが出ますので、その辺との兼ね合いも含めながら検討を進めていこうと考えております。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"お話を伺ったりすると、例えば恋愛トークでは話を合わせたりと、いじめも含めてとても苦しい体験をしている方が多いということを実感します。学習指導要領の改訂はもちろん、品川区小中一貫教育要領にまずはしっかりと位置づけることが必要だと思いますけれども、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"養護教諭との連携を図りながら、まず個別支援、個別対応を優先すべきものだと考えております。対応について考えていくかにつきましては、今後、市民科の中でどのような扱いをしていくかについて検討したいと考えております。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"どちらもオネエタレントとして扱われ、単に異性愛が前提という固定観念から、どちらも男性が好きだという新たな誤解も生まれております。この問題は私は緊急性があると思いますので、ぜひ積極的に、教材や授業で取り上げていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"最初に３６７ページのいじめ防止対策費ですけれども、「いじめは重大な人権侵害であり、決して許されません。現在のいじめと、理事者の皆さんの頃のいじめの違いというものは、どのように変わってきたと思いますか、説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"いじめに関する認識の変化というようなご質問だと思います。そこにやはりいじめというようなものが入ってこないように、それについては子どもたちに正しく、現在も指導しています。","id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"品川区の事例というのでしょうか、どのようにそれを解決できたのか、ご紹介ください。","respondent":"村尾教育総合支援センター長","answer":"各学校において、子どもたちに、いじめ防止という取り組みとして、本年度もバッジを作り、子どもたちの意識啓発を図っているところです。そして学校支援チームのＨＥＡＲＴＳが学校のほうに伺ったりしながら、また継続観察をするなど、きめ細やかな対応しています。","id":"exchange-023"},{"speaker":"木村委員","kind":"質問","question":"学校での教師は父親であり母親であるべきですし、生徒たちの前では毅然とした態度で振る舞ってほしいと思っています。人に優しくできるのではないかと考えますけれども、どのように考えているでしょうか、説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"各学校教員一人一人が、子どもたちに、いじめは絶対許さないのだということで徹底した指導を進めています。子どもたちとの信頼関係を築くことも優先的に考えておりまして、この２面で現在、教育を進めているところです。","id":"exchange-024"},{"speaker":"木村委員","kind":"質問・要望","question":"頑張ってほしいと求めました。次に３６９ページの上から９行目、１つのことに精通した方々の経験談は何物にもかえられないし、説明を求めました。","respondent":"熊谷指導課長","answer":"まさにそういった視点に立った、まちの人々に学ぶ授業ですけれども、やはり私ども教員だけでは深めることができない学習活動というのが多々あります。地域の方々の専門性、また経験といったことを、また子どもたち自身に地域の一員としての自覚が育つ授業であると感じております。","id":"exchange-025"},{"speaker":"木村委員","kind":"意見","question":"しかしながら、幼児期や小学校での運動経験や環境などが影響しており、１日や２日といった短期間の取り組みだけで改善するような問題ではありません。体力的、そして学力的にはどのように変化があったのか、もし大きな変化があれば説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"７年生から８年生用ということで、まさにこの取り組みは、毎日少しずつ子どもたちに運動習慣をつけさせようというのが目標で進めているところです。今年度はモデル校実施になりますけれども、本年度は４０％ということで、やはり運動習慣が拡大しているかと考えているところです。","id":"exchange-026"},{"speaker":"木村委員","kind":"意見","question":"頑張ってほしいと求めました。地域の住民は午後３時から、そして朝の８時ごろ散歩とありますけれども、その点だけ説明を求めました。","respondent":"品川庶務課長","answer":"８３運動のほうですが、教育委員会としましても、毎年、予算化しておりまして、啓発グッズ等をつくる費用で支援をしております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"３９３ページ、また時間があれば３７５ページ、文化財保護事業における指定文化財についてお伺いいたします。そこをお伺いいたします。","respondent":"有馬学務課長","answer":"まず学校のほうに、老朽度といいますか、取りかえの希望調査をまず行います。その後は、校長のほうでしっかり検査をしていただくというような形での品質の確保を行っているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"提案","question":"仕様変更の提案があった場合は、複数の専門業者、第三者の目からアドバイスを受けた上で決定すべきです。今述べたような問題解決のための提案の内容を、区のお考えはいかがでしょうか、お知らせくださいとの意見を述べました。","respondent":"篠田学校計画担当課長","answer":"かなり細かいところまでを設計に落とし込みまして、それを工事業者が施工図に落とし込んで、実際に工事を実施していく。規格の安易な変更ですけれども、同等の規格に仮に変更するとしても、こういった点での品質の低下が起きるということはございません。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"おそらく学校にいるとき一番長く見るもの、接するものですから、区としてもぜひとも行っていただきたいと考えております。厳しいチェックの目を向けていただきたいのですけれども、品川区のお考えとしてはいかがか尋ねました。","respondent":"小林施設整備課長","answer":"建設共同企業体で頑張っている施工者と、あとそれを見る現場の管理者として、第三者の設計事務所を入れております。そちらのほうでまず現場の管理をして、あと施設整備課の職員も含めて最終的な完了検査というのをやっております。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"実際、報告が届いていない可能性もありますので、ぜひともメーカーなどの専門業者のチェックの目を入れていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"区内開催・応援３競技体験教室、３７５ページ、ＰＴＡ活動支援のことを質問させてほしいと求めました。初めに、教職員健康管理費についてお伺いしたいと思います。","respondent":"品川庶務課長","answer":"教職員の健康管理ですが、定期健康診断につきましては、平成２６年、平成２７年と、両方とも受診率１００％となっています。それから本年度、平成２８年についても、ほぼ１００％に近くなっておりますので、月末までには１００％にいくと考えています。","id":"exchange-032"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"心のケアについてお知らせほしいと求めました。","respondent":"品川庶務課長","answer":"職員のメンタルヘルスの件ですが、平成２４年度から品川区独自でストレスチェックを行っております。教育委員会のほうから産業医等を通じて面談等をしたり、その面談の中で、やはり重い状況であれば病院を勧めるというような体制をとってあります。","id":"exchange-033"},{"speaker":"高橋（伸）委員","kind":"質問","question":"その学校に所属している学校長や副校長などが、ベテランの先生も含めて対応されてから、そういった診療をされるという認識でよろしいのか尋ねました。","respondent":"品川庶務課長","answer":"これはケースによって違ってくる場合もあります。上司である学校長、副校長を通したり、または通さなかったりというような個別の事例によって対応を変えているという状況です。","id":"exchange-034"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３７１ページ、区内開催・応援３競技体験教室のことをお伺いさせてもらいます。区内３競技を区内全校で、それぞれ３競技ありますので、今現在の状況をお知らせほしいと求めました。","respondent":"熊谷指導課長","answer":"平成２８年度はブラインドサッカーが１６校、そしてホッケーは５校で実施しております。平成２９年度からは、各校１種目ずつローテーションで実施いたしまして、平成３１年度までに全ての学校で３競技の体験教室を行っていく予定です。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３７５ページ、ＰＴＡ活動支援について、関連した話をさせてほしいと求めました。けれども、その辺のところの認識を教えていただければと考えています。","respondent":"熊谷指導課長","answer":"マラソン大会等に教員が土日に出ることですけれども、それにつきましては勤務として振り替えることができますので、子どもたちの応援をたくさんしてもらって、そして教員の力にもそれが返ってくると思いますので、ぜひ参加させていきたいと考えています。","id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、各小学校の校長を含めて、啓発というか、ぜひ参加というか、応援に来ていただきたいと考えています。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、あとストロンチウムの検査で、汚染水の状況を見てということも伺いました。その検査の回数が、もとに戻ることなどはないのかということも、重ねてお伺いいたします。","respondent":"有馬学務課長","answer":"これについては、平成２９年度も平成２８年度と同様に行っていく予定です。それから、ストロンチウム検査を３年で１巡にしたということの理由ですけれども、これについては様々私どもも検討いたしました。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"ストロンチウム検査の仕組みなのですけれど、保護者からも不安の声や不公平感の声というのは上がらないとは思うのです。不公平感が生まれないような仕組みができているのかということが聞きたかったので、そこを伺いたいと思います。","respondent":"有馬学務課長","answer":"そういう意味だと、今までどおり、年１回、各学校でやっていたという意味では公平だったですけれども、これまで３年間やってまいりました。どこまでやるのかというと切りがないと思いますけれども、これまでの３年間の状況を見て、今回はこのように判断させていただいたです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"そこでもやはり、消費者の立場でも、検査して、その計測結果を見て判断することは大切だと私たちは伺いました。見解を伺います。","respondent":"有馬学務課長","answer":"出荷停止の状況については、毎年やはり件数的には、基準値を超える出荷物というのが減ってきているという状況が１つあります。もう一つは、それぞれの立場のところでやっていただくというのが原則でありまして、品川区がそこまで手を出すというつもりは今のところございません。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"２０１６年度予算特別委員会でＬＧＢＴ対応の質問を幾つかしたときには、それぞれ前向きなご答弁だったと理解しております。教育総合支援センター長は、何よりもまずは教員への研修が第一」と答弁されていますが、現時点で教職員への研修はどの程度進んでいるのか伺います。","respondent":"村尾教育総合支援センター長","answer":"本年度、大きく４点の研修でＬＧＢＴを捉え、教員に研修を行いました。特別支援教育コーディネーター、これは各学校に１名配置しておりますけれども、認識を持たせるような研修を進めております。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"ＬＧＢＴに特化した教員向けの研修だったのでしょうか。もう一回、教えていただけますか。","respondent":"村尾教育総合支援センター長","answer":"ＬＧＢＴということで、性的マイノリティーに関する人権を含めての研修です。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"２０１６年度予算特別委員会のときに、ＬＧＢＴの子どもへの対応を伺ったところ、進めていくということを伺いました。具体的に挙げていただいた細かな個別の配慮はどの程度達成されているのでしょうか、伺います。","respondent":"村尾教育総合支援センター長","answer":"保護者への対応、それにつきましては各学校、どのような形でも対応できるように準備は進めているところです。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"ＬＧＢＴの子どもたちからの相談を待つだけではなく、相談機能もしっかりと学校の中に配置していこうと考えているところですと答弁されています。現在の相談機能の配置状況と、子どもたちへのメッセージはどのように発信されているのか伺います。","respondent":"品川庶務課長、村尾教育総合支援センター長","answer":"トイレの件ですが、改築する学校については、必ず、だれでもトイレというものを設置しておりますので、そういうもので対応しているという状況です。コーディネーターなどの活用により、どのような形でも、子どもが相談できる相談窓口は各学校に十分配備できていると考えております。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"いじめ防止対策推進法が制定され、その中で、各学校は、学校いじめ防止基本方針を策定することが求められました。現在、法律に基づいて、学校の基本方針策定状況はどの程度、進んでいるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"各学校におけるいじめ防止基本方針の状況というようなご質問です。いじめ防止対策推進法に規定された１３条で、いじめ防止基本方針を定めることとなっておりますので、この防止基本方針を持っているところです。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"伺ったところによると、法の求めに応じて基本方針を策定している学校も、２０１７年に向けて新たに方針を策定していると伺いました。どうしてこのような２度手間になるような事態になったのか、学校のほうが待つべきだったのでしょうか、伺います。","respondent":"村尾教育総合支援センター長","answer":"その後、実はこの基本方針というのは、学校の実態に応じて毎年、見直しを行うものです。区で行っている様々な取り組みを、この対策基本方針をつくっておりますので、毎年の変更について学校からの問い合わせ等は特にございません。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"この学校いじめ防止基本方針というのは、各学校の特色が出てこそなのではないかと思います。これだと、何か品川区の定めた基本方針に沿わなければいけないというふうに、何となく思ってしまうのですけれど、そのところはいかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"各学校がつくっております基本方針については、どうしても、やはり基本的なベースは似ているかと考えています。ただ、いじめ防止という部分につきましては、全てにおいて共通する内容も当然含まれていくものと考えております。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"学校の先生方はとても忙しいと認識しています。学校に余計な負荷をかけるべきではないという立場と各学校の特色も踏まえて作成されたほうがいいのではないかという意味で質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先日の一般質問でもやりましたが、この前の日曜日に新聞社主催の「ＡＩ時代に求められる教育とは」というフォーラムに参加してまいりました。もう一歩踏み込んださらなるキャリア教育が必要ではないですかと質問をさせていただいたときに、汎用的能力を育む学習を取り入れていくと。","respondent":"熊谷指導課長","answer":"そういった能力のことですけれども、理解していること、できることをどう使っていくか。未知の状況にも対応できる、そういった力、思考力・判断力・表現力を活かした、そういった能力が必要であると考えております。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"意見","question":"これからすごい時代に突入するというご認識を教育委員会がお持ちで、どういう未知の状況に対応する能力を養っていくのか、ということでありました。京陽小学校について、ご答弁がまだでしたねとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"本区においては、プログラミング教育におきましては、委員のご指摘のとおり、京陽小学校で３年間の研究を進めてまいりました。そういうことに対して、そういうものを子どもたちの学習の中で、様々なものに含めながらスタートしていくというような考えで行ってきております。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問","question":"ＡＩというのは、様々調べていくと、どうしても出てくるのが、ＳＴＥＭ教育という名称が出てきます。今回の京陽小学校の取り組みは、このＳＴＥＭ教育の一環として見ていいのかどうか、お伺いします。","respondent":"村尾教育総合支援センター長","answer":"その中で、子どもたちは情報技術を効果的に活用して、まさに論理的・創造的な考えができる。１つの大きな、総合的な理科系の教育の考え方ではありますけれども、様々な形で含まれていくものと考えております。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"子どもたちに求められていく力というのは、ではどういう職がいいのですかという質問をみんな投げかけるのですけれども、そんなことはわかりませんと。そのためにどういう力を養成していくのか、改めて伺いたいと思います。","respondent":"熊谷指導課長","answer":"知・徳・体をしっかり持った上で、品川区の生き抜く力を育てていきたいと考えています。その上で、品川教育検討委員会を進めてまいりたいと考えています。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３７３ページの人権教育というところで伺います。先ほどご答弁にもありましたけれど、多様性に関する理解力、差別解消といったものを学ぶ時間というのはどこにあるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"その取り組みを全校に広げながら、子どもたちの人権教育というものを今進めているところです。特別支援学校の子どもたちと、様々な形で、障害のある子どもたちとの触れ合いを通して学んでいくというような取り組みも進めているところです。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"企画調整課長に伺いたいのですけれども、２３区の中で、２０２０年から人口が減る１１区のうちに名指しされておりました。この根拠は何なのですかと私も問い合わせをしましたら、２０１３年の東京都の調査ということだったので、確かにそのとおりになっていました。","respondent":"柏原企画調整課長","answer":"その人口の全体のピークというのは５年先に延びておりまして、平成３７年がピークということで、東京都は新たに出しています。それで、品川区の人口推計で言いますと、平成３９年がピークということで、そこから緩やかに減るという状況で推計を出しています。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただし一方で、これも長期計画の範囲内ですから、平成３９年まで、予想を超えて若年人口が増えていくとしている。この犯人は、意思疎通が困難な人が誰なのかをわざわざ職員に確認してから、１９人の知的障害者の方を選択して殺害した。","respondent":"村尾教育総合支援センター長","answer":"差別を行わないというような１つの方向、自治的活動領域、いわゆる道徳実践や社会的判断という中に福祉教育というものが大きく入っております。子どもたちに、正しい認識だけではなく、豊かな人間性や社会性というものをしっかりと身につけていこうと考えております。","id":"exchange-055"},{"speaker":"横山委員","kind":"質問","question":"３７１ページ、３６７ページ、いじめ防止対策費についてお伺いいたします。１点目は、いじめ防止対策費についてお伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"都のほうから出されたものにつきましては、３つのアプリケーションを３月に公開予定と聞いております。同じグループなのですけど、学校のほうで対応するとともにＨＥＡＲＴＳも派遣し、すぐに対応させていただきました。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"情報モラルの研修にも参加していただいて、警察からも情報を得て連携しながら活動されているということをお聞きいたしました。そういった方を中心に研修を進めていただきたいと思うのですけれども、こちらの点、もう少し答弁をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"そこで本区では、情報モラル研修に、専門の外部機関の方に来ていただいて、研修を実施しています。教育委員会としても連携を図りながら、相談体制をしっかりと置きながら、子どもたちのトラブル解消に向けて取り組んでいこうと考えています。","id":"exchange-057"},{"speaker":"横山委員","kind":"質問","question":"そして、児童相談所移管推進に関連して、一時保護児の学校の扱いと、学校と一時保護所の連携についても、現状どうなっているのか教えてください。区だからこそできる部分が大いにあり、可能性を感じておりますが、区のお考えを説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"学校と一時保護所との連携につきましては、３つ目のご質問にもありますように、様々な形でケアをしております。現在、そのような状況で学校と取り組みを進めているところです。","id":"exchange-058"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目は、品川英語力推進プラン、オリンピック・パラリンピック教育推進事業の国際理解についてお伺いいたします。青山学院大学、アレン玉井教授が携わっておりますが、どのような経緯で導入されたのか尋ねました。","respondent":"熊谷指導課長","answer":"既に平成１８年度から実施してきているところですが、１年生から６年生に関しましては、全ての学校で３５時間実施していくところです。平成３０年度には、５・６年生には７０時間ということで、全校実施を行っていく予定です。","id":"exchange-059"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ、品川区の今まで進めてきた英語教育に加えて、今回の改訂を含めまして進めてほしいと求めました。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今後のスケジュールを教えていただきたいのが１点です。品川区は市民科という教科がありますけれども、文部科学省の道徳の教科化と市民科との整合性をどう考えているのか、お伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"まず５月ごろに、教科用図書調査検討委員会という、まず組織を立ち上げます。検討した上で、改めてこの検討委員会に提出し、８月までに決定するというような大きなスケジュールになっております。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして面接などで、資料を様々集めて、考え方から行動に至るまで全面的な評価を行うように求められると思っています。内心の自由に踏み込んだ評価を教員がしていかなければならないという、このことに対して、区教育委員会の所見をお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そのステップ２の内容が、市民科の授業を、これまでと同様に進めていければと考えているところです。いわゆる評価としての考え方ですので、より子どもたちの道徳性の育成という部分につきましては、今後とも進めていければと考えています。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"新しく教科の本ができるということにおいて、品川区は今までの市民科の流れの中で道徳の教育ができていくのか、また評価が同じようなものとなるのか。この危惧を持っているのですけれども、今までと変わらない状況の中で道徳をやっていけるのか、もう一度お伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"子どもたちの人間育成については進めていければと考えていますし、当然、様々な教育課題に対応できるものとしての市民科もあります。今後、国の道徳の教科化も含めながら、品川区ならではの市民科を進めていこうと考えております。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教職員が子どもたちにしっかりと向き合ってほしい、多忙化を何とか急いで解消していただきたいと思って質問します。多忙化の現状と課題をどのように認識されているのか、改めて伺います。","respondent":"熊谷指導課長","answer":"しかしながら、これについては省略できるのではないかというところについては時間短縮をということで取り組んでいるところです。そうした中で、現在、様々ではありますけれども、校長、副校長の働きかけにより、実態としましては勤務時間が短くなる状況にあります。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"現状のところがちょっと一般論かと思って伺ったのですけれども、具体的につかんでいらっしゃるのでしょうか。数字で教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"ご質問にお答えしますが、勤務時間としては把握はしてございません。土日の勤務状況の把握ということがございましたけれども、土日につきましても打刻はできますので、打刻ができないという状況はございません。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それを、一体どこでどうやってつかんでいるのか、ぜひここを教えていただきたい。ぜひ、実態をどれだけつかんでいるのか、もう一回お伺いします。","respondent":"熊谷指導課長","answer":"先ほどご質問がございましたけれども、打刻ができないということにつきましては、土曜授業ですとか行事のときにできます。超勤につきましても、超勤４項目が決まっておりますので、それについては校長が職務命令として認めることができます。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"意見","question":"そして、そこで仕事をしているにもかかわらず、本人が記録をとらない限り、その人の仕事状況がわからないのです。こんな状況ではとてもいかないと思いますので、ぜひつかんでくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"松永委員","kind":"質問","question":"水害など、いつどこで起きるかわからない災害に対してどのようなシステムで行動されることになっているのでしょうか、伺います。あわせまして、災害に対して、どのような教育がなされているのか、その内容について伺いたいと思います。","respondent":"熊谷指導課長","answer":"まず夜間・休日等、それから初期消火への従事、および教育長が指定する各種防災訓練への参加が義務づけられております。３回、それから避難訓練等にも活用することで、教職員として子どもへの安全教育にそれを活用しています。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問","question":"年３回ということなのですけれども、昨年、震度７クラスの地震が発生したことを想定して、１２月５日に防災訓練が行われました。そのときに、教職員の方々はどのような形で防災訓練に参加されていたのか、そのことについて伺いたいと思います。","respondent":"熊谷指導課長","answer":"今のご質問ですけれども、直接、待機寮に入居している職員がそれに参加して、どのような動きをしたのかということはつかんでおりません。","id":"exchange-069"},{"speaker":"松永委員","kind":"質問・要望","question":"平成２９年度予算には、寮が２寮となっておりますけれども、現在何世帯住んでいて、災害対策の教職員が何人住んでいるのか、伺いたいと思います。水害だったらこの人が行くというようになっているのか、そのことについて、もしわかればいいのですけれども教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"それから伊藤寮ですけれども、伊藤寮につきましては８世帯入居、そして入居者は８名となっています。実際にどのような役割分担がなされているかというご質問ですけれども、現段階では特段、役割といったものは課してはございません。","id":"exchange-070"},{"speaker":"松永委員","kind":"質問","question":"もしかしたら、これは独身の方なのかというふうな感じには読み取れるのですけれども、その辺について改めて伺いたいと思います。そして警察との連携について、どのような連携がとられているのか、また災害対策の教職員の男性と女性の割合がわかりましたら説明を求めました。","respondent":"熊谷指導課長","answer":"こちらは偶然なのですけれども、男性が０名、女性が８名です。消防団等との連携ですけれども、消防、消防団とのつながりの構築がなされていると聞いております。","id":"exchange-071"},{"speaker":"松永委員","kind":"質問・要望","question":"本区では、昨年も同様、１０人となっておりますが、２３区内で比べまして１０名が妥当なのかどうか伺いたいと思います。先ほど巡回相談員について、ＬＧＢＴの知識も持っていると伺ったのですが、改めてその辺も伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"１０名で、各小・中、それから義務教育学校を巡回しながら対応はできていると考えているところです。特別支援教育係にこの巡回相談を束ねるチーフがおりますので、そことも連携しながら、児童・生徒の支援に回っているところです。","id":"exchange-072"},{"speaker":"松永委員","kind":"質問・要望","question":"３６７ページの品川学校支援チーム（ＨＥＡＲＴＳ）との関係性について、どのようになっているのか、それについて伺いたいと思います。たしか私は、いじめ等根絶普及啓発事業の中で啓発バッジについて質問させていただいたのですけれども、それについて少し伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"特に重点的に行っていかなければいけない支援はどこだ、お互いに協力しながら進めていく、そのような関係です。その６年生は今度、それは、１年生などその他で使っていくということで考えております。","id":"exchange-073"},{"speaker":"松永委員","kind":"質問","question":"ポスターもお願いしたいのですけれども、そのときに行われたのかどうか、実績について少し伺いたいと思います。目安箱というのを質問させていただいたのですが、実績、必要性があるのかどうかというのも改めて伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"今回、いじめ防止については進めているということで、またポスターについては少しこちらのほうでも研究させていただければと考えているところです。昨年度同様、そして学校に行き当該の児童・生徒と話をしたりするような取り組みは、現在も進めているところです。","id":"exchange-074"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、教育委員会として、なぜ差がついているのかについて、どのように考えているのか伺います。今後、保育園を卒業される方が小学校に上がった場合の、受け入れ体制について伺いたいと思います。","respondent":"有馬学務課長","answer":"今後は、各学校がそれぞれ良い教育に裏づけられた内容を進めていくことが大事だと考えています。就学人口につきましては、人口推計を毎年行っているところです。","id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"意見","question":"それと３８９ページの給食運営費に関連して、３９１ページの保健運営費に関連して、インフルエンザ罹患の中学生の転落事故についてお尋ねいたします。性感染症と性教育についてお尋ねしますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"性感染への問題意識のご質問ですが、ＡＩＤＳおよび性感染症の部分につきましては、現在、増加傾向、また低年齢化ということがうたわれておりますので、これについては教育委員会として高い問題意識を持っております。","id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問","question":"性感染症は、正しい知識と注意深い予防、そして、もしも罹患したときは早期の発見と早期の治療が極めて重要だとされています。例えば校外の医療関係者による性教育の授業などは考えられていたり、現在行われているのでしょうか、ご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"７年生におきましては、そして９年生においては、進めているところです。現在、各学校においても外部講師による授業は行われておりませんが、基本的には養護教諭が連携して授業をしていると聞いております。","id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問","question":"平成２０年１月１７日の中教審答申では、以下のような、健やかな体を育む教育の在り方に関する専門部会の見解を踏まえて、告示、公示されました。この答申は極めて妥当な見解だと思われますが、この見解に対する教育委員会のお立場も踏まえて、最後にまとめのご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"国も様々な形で性感染につきましては予防対策を進めていると、こちらも認識しております。これが教育の基本として考えております。","id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回の事例を踏まえて品川区ではどのような対応がなされているのでしょうか。ノロウイルス感染症を含む感染性胃腸炎に対する学校現場の今現在の対応についてもご説明をお願いいたします。","respondent":"有馬学務課長","answer":"過日、立川市で発生した集団食中毒に対する区の対応ですけれども、私どものほうから衛生管理の徹底に努めるようにという通知をまず出しています。","id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問","question":"特に感染性胃腸炎の臨床検査については、現場ではどのように指導されているのでしょうか。ノロウイルスを含めた感染性胃腸炎一般について、現在の学校現場での感染予防の方法・指導についてご説明ください。","respondent":"有馬学務課長","answer":"今回の事例を受けて特に過剰な反応、何か、下痢をしたからすぐ医者に行けなどという指示は特に行っておりません。トイレを使った後あるいは食事を作る前といったところは、きちんと手洗いをするようにと、従来からの指導に努めているです。","id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"質問","question":"マスコミ報道に関連しまして、２月１４日、区内中学生が自宅マンションから転落死したという報道がありました。今回の事例の大まかな経過についてご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"その後、また警察から第二報、第三報と入る中で、教育委員会としても緊急対応をとって体制を整えてまいりました。現在、子どもからの相談はありませんし、保護者からの問い合わせも特になく、学校も終業式を含めて予定どおり進んでいるという状況です。","id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問","question":"リレンザを服用したというような表現のニュースが多かったのですが、抗ウイルス剤については何か学校現場や教育委員会のほうで対応などはされたのか尋ねました。","respondent":"有馬学務課長","answer":"それから、２日間は特にそういう行動が多く見られるので、なるべく１人にさせないような配慮が必要だと言われているということ。それから、今言ったようなことを、ちゃんと学校内でも情報を共有してくださいというようなことを、校長会で伝えたです。","id":"exchange-082"},{"speaker":"西本委員","kind":"意見","question":"３６７ページの、いじめ防止の点で、福島県のほうから避難されている方がいらっしゃると思います。原発に関するいじめがあるのか、ないのか、そういう調査をしたのかどうかお尋ねしますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"原発に関する避難の子どもたちへのいじめということで、私も新聞を見て大変心を痛めました。学校のほうでも、それについては今後、十分気をつけていくようにということでお答えをいただいています。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"私は、もう６年過ぎている中で、税金を使ってこれの検査をするという意味があるのかどうかということを非常に疑問に思っております。それについてのお考えをほしいと求めました。","respondent":"有馬学務課長","answer":"あくまでも食の安全の確保ということです。一気に廃止というのは、まだもう少し様子を見たいということで、今回はこういうご提案をさせていただいたところです。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問","question":"それで、品川区の給食では、保育園・幼稚園もそうですけれども、チェックされているものを使っているのですよね。そこでチェックしていないものを使っているのか尋ねました。","respondent":"有馬学務課長","answer":"安全を確保するために、一歩踏み込んでという形にはなりますけれども、それで実施してきたということです。全体の方向としてみれば、私どもについても、このまま縮減の方向に向かっていく事業であるかとは思っているところです。","id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"現在、不登校は何人いらっしゃるのか、そして要因はどのように分析をされているでしょうか。は病気等、それぞれの不登校になっている要因というものがわかっているのかどうか、説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"平成２７年度につきましては、昨年度からの比較というのも変ですけれども、同じような横並びの数値になっているのかと考えているところです。その辺を含めまして、各学校においてもその辺を十分に注視しながら、子どもたちへの対応を、今、進めているところです。","id":"exchange-086"},{"speaker":"西本委員","kind":"意見","question":"それに対しての、何か原因を探るという、本人の状況で異なるかと思いますけれども、その要因をどのように解明していくのか。様々なサポートをする体制などは研究されているのか、実際やられているのか、お知らせくださいとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"現在、対応といたしましては……。","id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"それから３９１ページ、かみ合わせの矯正について、それから時間があれば３８１ページの学校ＩＣＴ活用経費をお伺いしたいと思います。そういったときに、保護者、生徒、そして学校という３者の中で、現状としてどういった対応をしていくような体制になっているのか、まずお伺いします。","respondent":"村尾教育総合支援センター長","answer":"地域の主任児童委員との連携を図りながらも含めて、きめ細かく一件一件、対応させていただいているところです。年間、また保護者の支援が子どもの学校復帰にはとても重要かと考えていますので、センターとしてもできる限りの対応を進めていこうと考えております。","id":"exchange-088"},{"speaker":"塚本委員","kind":"質問・要望","question":"もとに、学校に通えるようにと思うために、学校側にも様々な対応を求めてくる場合もあるかと思います。そういったことは良いことなのか、どうなのか、考え方としてどう思っていらっしゃるかお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"特別教室を使って、子どもをそこで、様々な形で対応できるようにしているというのが一般的だと考えております。中学校で言うと、また教科書を一緒に時間があればやってみるような形で、やはり個別に学校のほうでは対応していると聞いております。","id":"exchange-089"},{"speaker":"塚本委員","kind":"質問・要望","question":"では次に、平成２４年の我が会派の一般質問でこの問題を取り上げまして、まずは国の保険適用の動向を注視したいというご答弁でありました。かみ合わせの状況で大変に心配だというようなことは、常々ご要望、お話があるところです。","respondent":"有馬学務課長","answer":"それで、申しわけございません。歯科の部分だけの統計は、今資料を持ち合わせてございません。","id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"適宜、適切な対応ができるように今後とも対応してほしいと求めましたので、よろしくお願いいたします。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"沢田委員","kind":"意見","question":"それから３７３ページの代替職員雇用費について、それから時間があったら３６９ページの市民科の士業を活用した授業について聞きたいと思います。最近されているのか、またどういった基準で品川区の学校に教育実習の学生が来ているのか、説明を求めました。","respondent":"熊谷指導課長","answer":"実習の受け入れですけれども、平成２８年度、品川区では、幼稚園２９名、小学校５１名、中学校２６名、受け入れてあります。大学によっても、その受け入れ、どのように依頼をしてくるかというのは異なっているところです。","id":"exchange-092"},{"speaker":"沢田委員","kind":"意見","question":"学校としても良いことだし、品川区としても良いことだし、子どもにとっても良い影響があると思うのです。受け入れる先生たちの意識、学校の意識というのはどういう形で、その辺のお考えを説明を求めました。","respondent":"熊谷指導課長","answer":"ですので、学習指導、生活指導、進路指導、それぞれきちんと指導を行って受け入れをしています。この教育実習の場であると思っていますので、そういったことも踏まえながら、学校としては組織的に支援をしていっているところです。","id":"exchange-093"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは年間、どれぐらいの代替の教員がいるのか、また代替の教員の質というものがどうなっているのか、お聞かせください。どういった方が代替で来ているのか、どういった方を採用しているのか、説明を求めました。","respondent":"熊谷指導課長","answer":"その上で、決定が下った後に、その名簿から候補者を選んでいるです。そして義務教育学校では育休代替が９人、産休代替が０人ということで、７３名の育休・産休代替教員が教壇に立っているところです。","id":"exchange-094"},{"speaker":"沢田委員","kind":"意見","question":"その質というのはやはり重要だと思うのですけれども、これはどういった研修体制を整えられていて、また代替で来るとすぐに授業をやると思うのです。そういったときに、どのように代替教員のサポートをしているのか、その辺のところの体制について聞かせてくださいとの意見を述べました。","respondent":"熊谷指導課長","answer":"ＯＪＴもしっかりとっておりますし、また区の研修、都の研修にも参加できるような体制をとっております。基本的には、校長、副校長を中心にサポート体制をしっかりとって、実際には子どもたちへの授業力向上に向けて支援しています。","id":"exchange-095"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったサポートをしっかりやっていってほしいと求めましたし、教員を抜けられていたりされていて、来られる方だと思うのです。校長、できれば品川区の他の先生がしばらく、そのあたりの体制をもう一度聞かせてください。","respondent":"熊谷指導課長","answer":"比較的、品川区の場合は、継続して行ってらっしゃる先生をお願いしているケースが多うあります。ただ、若手の代替教員もおりますので、学校としてサポート体制を今後もしっかり組んでいきたいと思います。","id":"exchange-096"},{"speaker":"南委員","kind":"質問","question":"３８８ページの学校給食費について伺います。子どもたちの命と安全を守る上での自治体の役割として、これはしっかり検査するべきだと考えていますけれども、その点について伺います。","respondent":"有馬学務課長","answer":"２３区の動向、それから他の地方の都市の状況というところも、まだ検査をしているところもあります。あわせて、それらの動向を見ながら、あるいは出荷停止の状況等、様々見ながら考えていきたいと思ってあります。","id":"exchange-097"},{"speaker":"南委員","kind":"質問・要望","question":"私は、品川区の自治体としての立場をしっかり守って、必要な検査はきちんと続けていただきたいと改めて要望したいと思います。この給食費補助を導入した理由というのはどういうことなのか尋ねました。","respondent":"有馬学務課長","answer":"これにつきましては、事業を開始したのは昭和５５年となります。区立の小・中学校、経済的理由によりこれを負担することが困難と認められる保護者に対して、負担の軽減を図るということで開始しているものです。","id":"exchange-098"},{"speaker":"南委員","kind":"質問","question":"昭和５５年という、大分、何年も前なわけです。１・２年生、３・４年生、それぞれ区分けしているグループで月額を説明を求めました。","respondent":"有馬学務課長","answer":"給食につきましては、単価はそれぞれ、低学年が２４０円、中学年が２６０円、高学年が２８０円、中学生は一律３２０円となっております。これの食数、月分という形になります。","id":"exchange-099"},{"speaker":"南委員","kind":"質問・要望","question":"中学生も４,８７３人、計算を合わせると大体１億１,０００万円ぐらいあると、これは品川区の今の財政状況から見て十分可能ではないかと思います。この社会経済状況の中で、収入が下がっているということについての現状認識をどういうふうに考えているか、まずそこを伺いたいと思います。","respondent":"有馬学務課長","answer":"今、平均すると、大体２万人、生徒がいらっしゃると思います。それで、月額５,０００円ですので、年に直すと６万円程度になりますので、これを単純にすると１２億円という計算になります。","id":"exchange-100"},{"speaker":"南委員","kind":"質問・要望","question":"数字の違いは訂正したいと思います。１２億円にしても、本当にこの不況の中で、その負担を軽減するという立場に立ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"３６７ページは校外授業費のところで伺ってまいりますので、よろしくお願いいたします。それと、１つ私ども、ずっと、兄弟枠というのですか、優先をお願いしていた経緯もあります。","respondent":"有馬学務課長","answer":"兄弟枠につきましては、小学校で３名が入れませんでした。これは昨年１０名でしたので、これも多少は改善されているという状況です。","id":"exchange-102"},{"speaker":"渡部委員","kind":"質問","question":"そもそもの位置づけというのですか、移動教室ですから、もともとどういう質のものなのかというところを教えてください。お願いします。","respondent":"有馬学務課長","answer":"６年生と７年生で実施していますけれども、それから集団生活をそこで行って、規律や連帯感を養う。実際には、これは教育課程上の一環ということで行われているものです。","id":"exchange-103"},{"speaker":"渡部委員","kind":"確認","question":"５年生の段階から徐々に始めて、その集大成として移動教室なのか、改めて確認するというような意味合いの授業というのはできないのか。例えば５年生ぐらいから、どこに行くためにはどういう勉強を重ねて、それの確認がしたいからどこへ行こうというような活動ができないかと思います。","respondent":"有馬学務課長","answer":"まず日光の光林荘を６年生は使っておりますけれども、ここは従前、学習室やレクリエーションホールといったものもそろっています。宿を借りるときにはアルコールの自動販売機は全部禁止するですとか、細かいルールもありますので、なかなかちょっと難しいかと思ってあります。","id":"exchange-104"},{"speaker":"渡部委員","kind":"質問","question":"費用的なところですとか、様々な問題点が多いのはもう承知しております。どういうふうにやったら何か可能なのかなどと少し考えながら、またいつか質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"あべ委員","kind":"質問・要望","question":"３６４ページにかかわって、特別支援教育費ですとか、そしてまた３８１ページにありますタブレット端末等の導入などについて伺いたいと思います。指導課長に以前、その後、ご体験していただいたかどうかということをお伺いしたいと思います。","respondent":"熊谷指導課長、村尾教育総合支援センター長、有馬学務課長","answer":"ダイアログ・イン・ザ・ダークにつきましては、委員からご説明いただきまして、私、個人として非常に興味深く思ったところです。しかしながら… 更衣室については、どこがあいているかみたいなものについては、十分やはり検討できる内容かと考えています。できる限りということで… 大体、教員の８０％ほどが毎日使っている、週に３回以上は使っているということで、大分、浸透はしてきていると考えています。","id":"exchange-106"},{"speaker":"あべ委員","kind":"質問・要望","question":"不登校の子どもたちに対しての学習支援策の一つとして、ぜひタブレットを使っての学習というのを導入してはいかがかと思いますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"ｅラーニングという形で、パソコンを使って、自分のつまずきのところまでさかのぼって学習ができるような仕組みをとっております。モデル的に進めていまして、全学年対応で１年生から９年生までの内容が入っておりますので、様々な形で拡大できればと考えています。","id":"exchange-107"},{"speaker":"あべ委員","kind":"質問・要望","question":"この機会に、これからの品川区の教育について私の考えを少しお伝えし、また教育委員会のお考えも伺いたいと思います。この荒波、変化する社会の中で、生きていけるだけの力を持つ子どもたちを育てていくことが、教育委員会、そして大人たちに求められていると思います。","respondent":"中島教育長","answer":"今までは学校の教員が中心となって進めてまいりましたけれども、学校だけでは解決できない要素もそこにたくさん入り込んできております。今、まさにそういったところの連携を図って、これからの子どもたちを育てていける１つの仕組みではないかと考えております。","id":"exchange-108"},{"speaker":"こんの委員","kind":"確認","question":"プラン２１推進事業に関連して、学校選択制について、小学校における兄弟枠の受け入れの考え方についてお聞きしたいと思います。確認したいのですが、保護者の方の状況などを踏まえて、どのように捉えていらっしゃいますか尋ねました。","respondent":"有馬学務課長","answer":"これはやはり当然、兄弟は同じ学校に行ったほうが、そのお子さんのためにもなるだろうというような配慮はあったと考えています。それから、これまでもブロック外で、指定校変更によって希望があったかですけれども、毎年数件は発生しております。","id":"exchange-109"},{"speaker":"こんの委員","kind":"意見","question":"これは１つの事例を申し上げたいのですけれども、２人のお子さんを持つご家庭の事例であります。今後どのように、こうしたことの対策としてお考えになっていることがあるのであれば、お聞かせ願いたいと思いますとの意見を述べました。","respondent":"有馬学務課長","answer":"しかし、基本的なルールといたしましては、まずは区域内のお子さんは必ず受け入れるという責務もありますので、それは最低限行うです。今回の事例もまた課題だとは捉えておりますけれども、全体を見通して、また兄弟枠のあり方については考えていきたいとは思ってあります。","id":"exchange-110"},{"speaker":"こんの委員","kind":"質問・要望","question":"教育の公平性というところで、やはりご家庭の事情があっても、その子には行ける権利というのがあるというところを担保していただきたい。ご事情をよくよく聞いてご判断していただく仕組みなども、今後考えてほしいと求めましたが、もう一言ご答弁をお願いできますか尋ねました。","respondent":"有馬学務課長","answer":"個々の事情は本当にそれぞれケースがあると思いますので、きちんと聞いていきたいと思います。その中でご家庭も判断されることだと思いますし、我々も１つのそういった兄弟枠についての課題だとは、今回は受けとめてあります。","id":"exchange-111"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。どういう手だてを、またどういうサポートを、品川区としてされているのか教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"今年から始まったので９年生が入って、センターのほうに合格の報告に来て、みんなで喜んだということもあります。進学というのを１つの目標として子どもたちは頑張っておりますので、２次募集を含めて、様々な形で対応していこうと考えております。","id":"exchange-112"},{"speaker":"こんの委員","kind":"質問","question":"それは、やはり同じようなものが情報提供されて、進路が決まっていくものなのか。連携をとっているといっても、より細かく情報提供ができるのはマイスクールの先生のほうかとイメージしているのですが、その辺はどうなのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"直接、当然ながら連携を図りながらということはありますけれども、学校とマイスクール八潮はしっかり連携を図りながら進めていく。必ず毎月、学校とやりとりをしながら情報交換をしているということもありますので、今後とも引き続き行っていこうと考えております。","id":"exchange-113"},{"speaker":"こんの委員","kind":"質問・要望","question":"私が少し問題として思ったのが、確かに学校に来る情報のほうが多いですから、そこから合ったものを情報提供しながら進路を選んでいく。毎年、進学が進むように、これからも頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"渡辺委員","kind":"質問","question":"そして、４つのアクションがその後、続いて、今後やりたい抱負というのですか、目的がある。あるいは次年度、どんな予定で、この４つのテーマがそれぞれどう進めていかれるのか説明を求めました。","respondent":"村尾教育総合支援センター長、熊谷指導課長","answer":"これも１つの教材開発かと考えています。本当にその地域の特色ある教育活動を進めたり、今後とも様々な形での外部人材の活用、また教育の質の向上に向かって進めていければと考えております。 今年度は、オリンピアンが１７校、そしてパラリンピアンが９校で実施したところです。オリンピックもパラリンピックもできませんので、環境の取り組みといったものを中心に、子どもたちには学習をさせているところです。","id":"exchange-115"},{"speaker":"渡辺委員","kind":"質問","question":"国際感覚を養うという点で、もう一言、こういう課題に対してどう取り組むのか教えてください。この辺で、障害者スポーツの啓発を含めて、学校教育の件、抱負をお知らせください。","respondent":"熊谷指導課長","answer":"国際交流ですけれども、国際理解教育におきましては、現在、区内の全ての学校、幼稚園で、世界ともだちプロジェクトを実施しているところです。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校選択制なので、３６３ページの就学事務費か、先ほどのプラン２１推進事業なのでしょうか。どのように整合性をとって、品川区の新しい教育要領を策定していくのか尋ねました。","respondent":"有馬学務課長、村尾教育総合支援センター長、熊谷指導課長","answer":"とれないです。学校選択が終わった後の指定校変更の中で、幼稚園へ行ったときに、そういった理由でその小学校への進学を希望されている方はいると認識して… 私からは、特別支援教室におけるご質問にお答えいたします。これにつきましては、学校の様々な状況、また理由により、校長の判断で行ったと聞いております。実際にカリキュラムの中でもリテラシーを行ってまいります。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"あわせてご見解を伺います。普通教室の担任となった先生には、兼務発令ということで、そして特別支援教室の継続した指導についてのお考えを伺います。","respondent":"有馬学務課長、村尾教育総合支援センター長","answer":"例えば保育園でも、スクールステイというようなことで、保育園も連携しているようなところもあります。そうしますと、大分、対象も広がってしまったりしますので、これは慎重な検討が必要だと考えております。 継続性につきましては、通常、きちんとした引き継ぎを行っていくというような考えです。なお、兼務発令等については、今年度、特には行っていないということなので、これについては交代ということで進んでいるところです。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、志望する保護者の方や児童が増えて、特別支援教室の希望者が増えているとお聞きしています。ですから、その成果をぜひ来年度に活かしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３６３ページの学事制度検討経費に関連して、学校選択制について伺います。現在行われております学事制度審議会の検討項目に学校選択制を入れた区の問題意識を伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"学校選択制につきましては、平成１１年・１２年から、小学校・中学校という形で導入されてきました。今年度から品川区教育ルネサンスという形で新たな展開を進めている中で、学校選択制についても検討項目の一つとして入れてきたものです。","id":"exchange-120"},{"speaker":"のだて委員","kind":"質問","question":"なぜ入れたかをお聞きしたので、区の問題意識をお答えほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"１つの制度ですので、必ずしも１つの制度が永久に続くわけでもございませんし、ここでの検討の項目として改めて入れることとしたものです。","id":"exchange-121"},{"speaker":"のだて委員","kind":"質問","question":"人口の変化や、選択できない状況、永久に続かないというお話もありましたけれども、まだこの選択制については、学事制度審議会の議題にはなっていませんけれども、自由発言のときなど、この間の審議会では、学校選択制についてどういう指摘があったのか伺います。","respondent":"篠田学校計画担当課長","answer":"必ずしも地域との結びつきという部分ではうまくいっていない部分があるのではないかというような率直なご意見をいただいているところもあります。","id":"exchange-122"},{"speaker":"のだて委員","kind":"質問","question":"学校選択の結果、別々の３つの小学校に通っているような現状もあり、町会側がどこの学校とかかわればよいか迷っているという意見も出ています。選択制によって、地域とのつながりが弱まっているのではないかと思いますが、いかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"他の地域の学校に行ってしまうといった形で、町会活動等にも影響が出ているというようなお話もいただいているところではあります。学校との結びつきといった観点で考えますと、そういった意味では、そういった考え方も変化してきているのではないかと考えているところです。","id":"exchange-123"},{"speaker":"のだて委員","kind":"質問","question":"一応、弱まっているという声もあると。導入から、こういった、学校選択制によって地域とのつながりが弱まるという声が根強く上げられているのはなぜだと考えているのか伺います。","respondent":"篠田学校計画担当課長","answer":"例えば、今、実際に学校に通われている方の７５％は学区域のお子さんでいらっしゃいます。ですので、そういった意味では、必ずしも地域との結びつきが弱くなってしまっているという形では捉えてはおりません。","id":"exchange-124"},{"speaker":"のだて委員","kind":"質問","question":"なぜ弱まっているという声が上がっていると考えているか、なぜなのかということをお聞きしたので伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"それは、それぞれ地域ごとに、必ずしも全ての地域で全てのお子さんが地元の学校に行かれているとは限りませんし、比較的多くのお子さんが別の学校に行かれているといった地域もあると思いますので、それぞれの地域特性によるものと考えております。","id":"exchange-125"},{"speaker":"のだて委員","kind":"質問","question":"選択制で地域のつながりが分断されているという声も寄せられます。学校選択が地域のつながりを弱める一因だと考えているのか、伺います。","respondent":"篠田学校計画担当課長","answer":"制度実施による１つの結果ですので、地域の７５％の子どもはそれぞれ地域の学校に行かれているというような状況もありますので、一概にそれだけが原因という言い方はなかなかできないのではないかと考えているところです。","id":"exchange-126"},{"speaker":"のだて委員","kind":"質問","question":"様々な理由があるということでしたけれども、私が聞いたのは、学校選択がその一因でもあるかということをお聞きしたので、伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"ただいまご答弁申し上げたとおり、様々な要因の中で、要因であることは否定はできないけれどもという形を申し上げたので。ただ、それだけではないと考えているところです。","id":"exchange-127"},{"speaker":"のだて委員","kind":"質問","question":"どの学校にするのか選ぶ心理から、学校の内側からでなく、外側からの視点が強くなってしまったのではないでしょうか。教育委員会の見解を伺います。","respondent":"篠田学校計画担当課長","answer":"保護者の方の選択という観点ももちろんあるのですけれども、そもそも学校が地域に対してどうやって開かれていくかということ。特に、地域との結びつきが弱いといった中で、学校がどう変わっていくかといったために導入された制度であると認識しております。","id":"exchange-128"},{"speaker":"のだて委員","kind":"質問","question":"親の心理が変わってしまったのではないかということをお聞きしたので、その見解を伺いたいと思います。","respondent":"有馬学務課長","answer":"全体では７割、８割の方がいらっしゃいまして、学校の活動にも入っていますしＰＴＡの活動にも入っております。そして、それなりにきちんと活動はされている状況は、かいま見られるのではないかと考えております。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問","question":"杉並区では、学校関係者からも、廃止の声が３８.１％、見直しが３４.４％ということでアンケート結果が出ておりまして、既に廃止しました。中学校で６名いるわけですから、見直す必要があるのではないでしょうか、伺います。","respondent":"有馬学務課長","answer":"希望校に入れなかった人数というのは１１０名、小学校が約７００名、中学校でも６００名を超える方が希望している中での数字です。６００名を超える中での６名が入れなかったということですので、全て選択制がだめだとは、まずならないのではないかと考えております。","id":"exchange-130"},{"speaker":"のだて委員","kind":"質問","question":"やはり、公教育、義務教育ですから、悩んで選択しても入れないと。この状況をどう考えているのか、伺いたいと思います。","respondent":"有馬学務課長","answer":"理想を申し上げれば、１００％受け入れられる状況をつくり出す、そういう努力をするのが必要だとは思っています。１００％ではないかもしれないですけれども、できる限り応えているというのが今の現状です。","id":"exchange-131"},{"speaker":"のだて委員","kind":"質問","question":"１,０００人いる学校から１学級しかない学校など様々あって、そういったところで、義務教育のところで競争が生まれてしまっています。こういった学校の競争を行っていく中で、特色を出すのに力を入れ過ぎて子どもと向き合えなくなってしまっている可能性はないのでしょうか、伺います。","respondent":"有馬学務課長","answer":"基本的に、競争によってとは考えてございません。クラブ活動だとか、そういうことが優先されておりますので、そういったことはないと理解しております。","id":"exchange-132"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校選択制によって、様々地域の繋がりなどの問題が発生してきております。ぜひ廃止も含めて見直しをしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"伊藤委員","kind":"質問","question":"品川女子学院にお伺いした際、多分、生徒が作成したパワーポイントを使ってプレゼン等をしていく。これからの品川区のＩＣＴ化の方向について、こういうことを例にして具体的な展開をしていくべきと考えますが、いかがでしょうかという質問です。","respondent":"熊谷指導課長","answer":"今ご指摘いただいた品川女子学院の例ですけれども、確かに非常にすぐれた取り組みをしていると感じています。そうした事例につきましても今後、発表して、様々な学校でその取り組みを活かしていけるよう努力していきたいと思います。","id":"exchange-134"},{"speaker":"伊藤委員","kind":"意見","question":"やはり、それがこれからの方向性として可能だと思うのだけれども、その具体的な今後の計画、見通し等についてお知らせください。お願いいたしますとの意見を述べました。","respondent":"有馬学務課長","answer":"小規模校の支援ということで、中学校２校につきましては、１人１台のタブレットを配備しています。あわせて、校内ＬＡＮを整備しまして、そういった環境を整えていきたいと考えているところです。","id":"exchange-135"},{"speaker":"伊藤委員","kind":"意見","question":"年齢の関係があるからなかなか難しいのかもしれないけれども、タブレット端末等を貸与して、それを活用して授業を展開していく。それが次のステップだと思うのだけれども、もう一言、答弁をお願いいたしますとの意見を述べました。","respondent":"有馬学務課長","answer":"今後、どこまで広げていくかですけれども、その効果を見ながらというのが１つです。全教室に対するプロジェクター等の整備も同時に行いますので、そういったことを踏まえて、また検討していきたいとは思ってあります。","id":"exchange-136"},{"speaker":"伊藤委員","kind":"意見","question":"逆の現象ですよね。だから、例えば世界文化の多様性に応じた教育の展開をすべきではないかという意見があったので、そのことについて品川区の見解をお願いいたしますとの意見を述べました。","respondent":"品川庶務課長","answer":"学校では、１年生のときに生活科の中で、トイレのことを勉強するということがあります。そこで、１年生も和式トイレの使い方などを勉強するというような教育体制を図っております。","id":"exchange-137"},{"speaker":"伊藤委員","kind":"質問","question":"世界の中で多様な文化があるわけですから、そのことの、もう一つ答弁をお願いしたい。そういう教育の現場では、１つの方向性のみ推し進めていくのではなくて、いかがでしょうかという質問なのです。","respondent":"村尾教育総合支援センター長","answer":"当然教えていくべきものだと考えておりますし、また子どもたち同士が様々な形で話し合ったり考えたりする、必要になってくるかと考えております。","id":"exchange-138"},{"speaker":"伊藤委員","kind":"意見","question":"ざっくりとした答弁で、要は１つの固定観念を中心として教育を展開していくと、様々なところで弊害が出てくるわけだと私は思うのです。そういうことで様々弊害が出る可能性があると思うので、あと約５０秒ありますから、これからの方向性についてだけご答弁をお願いいたしますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"１年生から９年生という義務教育の中で、きちんと社会の中での現実を見せ、それに対して子どもたちの意見をまとめながら教育は進めていく。その中で市民科が中心になっていくべきだと考えております。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"３７３ページの特別支援教育費と、３６４ページの教育指導費、これはがん教育について伺いたいと思います。特別支援教室のない学校はあるのか、あったら数も教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"当然、子どもたちは様々個別対応が受けられますので、その学校の特別支援教室で特別の支援を受けるというような形になっておりますので。この特別支援教室の考え方は、全校で実施していますので、この教室がない学校はございません。","id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"施設に行ったときも伺っておりまして、これまでは２年生と聞いていた覚えがあるのですが、この辺をちょっと教えてほしいと求めました。そして今後どういうふうに、平成２９年度、そこをお聞かせほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"Ｗｉｓｃ検査につきましては、１年生から６年生、どの学年でも対応できると考えています。今後、がん教育については、より進めていければと考えております。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問","question":"それから、あと、この前伺ったら、美理容の学校も定数割ればかりだと。それで、では木育というのはあまり学校で聞かないと思っていたのだけれども、こういう木育という捉え方はどうお考えかというのをまずお聞きします。","respondent":"村尾教育総合支援センター長","answer":"図工の中で木を使って様々なものを作るというような取り組み、どういうふうな中で自然とのかかわりがあるのかなどについても学習をしている。トータルで言うと、木に触れる教育というのは、実はまだまだ学校の中にはあるのかと考えております。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはお願いで、要望だけでやめます。だから、そこら辺の点を公の部分としてどうお考えなのかというのを教えていただきたい。","respondent":"熊谷指導課長","answer":"実は本区におきましては、私立幼稚園の教員も、それから保育士も一緒に学ぶための研修会も実施しているところです。私立の幼稚園のほうは、こちらのほうで把握してございませんけれども、そういうところです。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"「わからないことが多い」と回答した子どもは、小学校５年生で困窮層で２８.７％、中学２年生では５１.５％に上りました。子どもの学習指導をしている教育委員会は、このことについてどのようにお考えか尋ねました。","respondent":"熊谷指導課長","answer":"子どもたちの置かれている様々な環境、それに伴って支援していくということは、とても重要だと思っています。コミュニティ・スクール実施に伴い、放課後の学習支援、そして長期休業中の学習支援ということで。","id":"exchange-144"},{"speaker":"須貝委員","kind":"意見","question":"例えば、この子たちが、授業の３分の２しか受けられない、半分しか受けられないのだったらわかります。それについて、責任というか、そういうものをお感じになりませんかとの意見を述べました。","respondent":"熊谷指導課長","answer":"本区でも放課後の学習支援をやっていますけれども、保護者、一緒にやって学習習慣を定着させている。そこのところで子どもたちの学力がぐんと伸びていると聞いております。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"他自治体でやっているのですから、何で品川区ではできないのですかということを、まずお聞かせください。やはりきちんとした成果というのを出さないと、教育の現場としても私はおかしいのではないかと思うのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"委員が今、品川区はなぜできないのかというご質問があったのですけれども、大丈夫です。ですので、そういった苦手分野を克服するための支援を、学校でもそうですが、放課後の学習でも行っていくことが重要だと考えております。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうものを求めていくには、学力がないと、やはり難しいではないですか。そういう状態になってほしいのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"そういった子どもの顔を見ながら、その時、その時で対応していく。それが私たち教員の存在意味だと思っています。","id":"exchange-147"},{"speaker":"須貝委員","kind":"意見","question":"教員の負担は絶対、どう考えても重過ぎます。きちんと学べるような、私はそういう学校を、教育現場をつくってほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-148"},{"speaker":"石田（し）委員","kind":"質問","question":"３６５ページの学校ＩＣＴ化推進経費について、３８１ページの学校ＩＣＴ活用経費について、時間があれば図書館経費についてお伺いいたします。伝統文化の発信能力育成事業等もやられているので、非常に効果的ではないかと思うのですが、どのようにお考えか尋ねました。","respondent":"熊谷指導課長、有馬学務課長、村尾教育総合支援センター長","answer":"先に組織間連携ツールについてお伝えしたいと思います。指導課、教育総合支援センター、それから学校管理職がモデルとして実施することによりまして。来年度は８校分、新たに校内無線ＬＡＮを設置する予定でございまして、約１,１４０万円というものを見込んです。これにつきましては… 愕然とするほど、主体的に学習に取り組んでいないというような結果があらわれたと、そこで大きく取り上げられたものかと考えております。","id":"exchange-149"},{"speaker":"石田（し）委員","kind":"質問","question":"月、何回会議があるかだけ教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"会議ですけれども、大体、週に１回は、職員会議、もしくは研修会、研究会というのがありますので、大体、月にしますと多くて５回ぐらい、４、５回だです。","id":"exchange-150"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"情報収集、そして小規模校の支援にぜひ活かしてほしいと求めましたが、いかがでしょうか。これはぜひこういったデータをしっかりと蓄積して活用していただきたいと思うのですが、ご見解をお知らせください。","respondent":"有馬学務課長","answer":"平成２５年に一度、導入を検討するまでには至りませんでしたけれど、こういうものがあるのだということで認識したものです。ぜひ、このデータを活かして、タブレットのない学校の学習指導にも活かしていきたいと、今、考えているところです。","id":"exchange-151"},{"speaker":"石田（し）委員","kind":"意見","question":"どうしても、これは学校の工事も、ぜひそういったことも検討を今後進めていってほしいと求めました。時間があるので１点だけ、図書館経費ですが、品川区の図書館における、電子書籍の導入の取り組みについて、現状と今後のお考えをお知らせくださいとの意見を述べました。","respondent":"木村品川図書館長","answer":"現在、研究段階というようなところです。まだ具体的に、そういうところまではまだ至っておりませんが、引き続き研究してまいりたいと思ったところです。","id":"exchange-152"},{"speaker":"石田（し）委員","kind":"意見","question":"もう民間では全然、使われているわけでありますし、いわゆる人的な部分も非常に効率がよくなっていくのかと思います。電子書籍があればなくなっていくのかと思いますので、ぜひ研究から検討の段階に入ってほしいと求めましたので、引き続きとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-153"},{"speaker":"安藤委員","kind":"質問","question":"移転理由を変えるとは一体どういうことなのでしょうか。これでは住民をだましたのではないでしょうか、伺いたいと思います。","respondent":"木村品川図書館長","answer":"それから、品川産業支援交流施設（ＳＨＩＰ）の開設に伴いまして、大崎図書館自体の再活用を検討するというような段階におりました。ですので、理由に関しましては今までのご説明、ご答弁と変わるところはございません。","id":"exchange-154"},{"speaker":"安藤委員","kind":"質問","question":"区立図書館の広報紙にも、大崎図書館の紹介として、「２階にはビジネスコーナーが設けられており」とあります。それがあって、批判が強くなって、その都度、理由を後から考えているから、こうなるのではないのか尋ねました。","respondent":"木村品川図書館長","answer":"理由をその都度変えているというようなご認識ということではありますけれども、説明をそのような意味で、してきたつもりはございません。それで、実際にそこでＳＨＩＰとの連携みたいな部分も考え得るのではないかというところです。","id":"exchange-155"},{"speaker":"安藤委員","kind":"質問・要望","question":"本人、あるいは担任や学校への、そして学校ホームページなどの掲載はどうなっているのか、それぞれ伺いたいと思います。最後に、東京都の学力テストおよび全国学力テストとの違いはあるのか、ないのかも伺います。","respondent":"熊谷指導課長","answer":"これはコミュニティ・スクール実施校のみですけれども、９月７日に教育委員会に、そして９月２０日に学校ホームページに公表していきます。これまでも、区は４年生と７年生、そして都は５年生と８年生ということで実施してきたところです。","id":"exchange-156"},{"speaker":"安藤委員","kind":"質問","question":"おまえ、どうなのだということで競争が激化しないか、危惧するところです。区の考えを伺いますが、学力テストではかれる学力とは何なのか、子どもの何がはかれると考えているのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"そして、教員にとっても指導力の改善ということにつなげていけると考えております。そうした手だてを講じることができると思います。","id":"exchange-157"},{"speaker":"安藤委員","kind":"質問","question":"中学校も、品川区が１３.３％で全国は３２％と、非常に低くなっております。そうした心配について、区はどのように考えるか尋ねました。","respondent":"熊谷指導課長","answer":"そのため、これまでよりも増えるかといいますと、実は４・７年生に関しては減るです。だからこそ、これから、こうした子どもへのアンケート等も含めて、授業の改善について、また区としても学校と一緒に考えていきたいと考えております。","id":"exchange-158"},{"speaker":"安藤委員","kind":"質問・要望","question":"紹介しましたように、テストの点数を獲得するためにどうするかということが中心の学校になっていき、そして子どもたちが追い詰められる。学力テストの拡大は中止を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３６７ページの、いじめ防止対策費、３７５ページの文化財保護事業、３８７ページの就学援助費でお伺いします。ネットいじめが４件、持たせる理由はなぜなのかというところ、どのようにつかんでいるかを説明を求めました。","respondent":"村尾教育総合支援センター長、品川庶務課長、有馬学務課長","answer":"保護者への啓発も進めながら、持たせるのであれば必ず、きちっと子どもと話し合って家庭のルールを決める。このような取り組みは進めているところです。文化財の件ですが、これは広報のほうで、しながわ百景アプリ、ＡＲ技術を活用した記念撮影スポットというものをアプリでやっていく予定でおります。… ３点目の、新入学学用品費につきましては、当該学年に入らないと対象になっていないというのが現状です。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２０２０年までに２００カ所を目指して、ぜひ検討していただきたいと、これは要望にとどめておきます。そうした動きを見きわめて、積極的にそういった前倒しも行っていただきたいと要望させていただきたいのですが、ご見解をお願いいたします。","respondent":"濱田生活安全担当課長、有馬学務課長","answer":"区民の声で、平成２６年に回答しております。こういったことで対応しております。 前倒しの検討ですけれども、そのような国の動きということがあります。２３区でも実施あるいは検討を始めたという区もありますので、そういったことも含めながら、今後の検討課題とさせていただきたいと思ってあります。","id":"exchange-161"},{"speaker":"鈴木（真）委員","kind":"確認","question":"小学校・中学校・義務教育学校の建築年次を確認させていただいたところ、一番古いのが昭和３３年の鮫浜小学校ということで、改築の計画が出ています。全体がこの年代ではないということもお聞きしているのですけれど、これからの改築計画についてどのように考えていくのか、その点を説明を求めました。","respondent":"熊谷指導課長、篠田学校計画担当課長","answer":"学校支援ボランティア連絡用郵券が、そして学校支援地域本部通信費が、学校支援ボランティア保険料が。本部用の備品購入費として、３４校分、３４０万円を計上しています。現在、本日も幾つかお話が出てきましたけれど、就学人口の急増といったことが見込まれているところがあります。","id":"exchange-162"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"前に質問に入れさせてもらったことがあると思うのですが、すごくこれから責任感を持ってやっていこうということでお話を伺っています。それから、この１億３,４００万円というのは、自費なのか、国から出てくるのか、その辺を説明を求めました。","respondent":"熊谷指導課長、篠田学校計画担当課長","answer":"コーディネーターの人数ですけれども、学校配置が３７人、そして指導課で総括するコーディネーターが１人ですので、３８名です。実際に新しくなるコーディネーター等に対する支援ですけれども、研修… 城南小学校の改築に当たっての埋蔵文化財の対応ですけれども、こちらのほうで計上していたものです。埋蔵文化財等の対応につきましては、そういった調査に関しましては全部、一般財源でやるという形になっているものです。","id":"exchange-163"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どういうものが出てくるか、その辺はわからないのですけれど、工事が順調に進むようにお願いしたいと思います。この学習指導要領と教育ルネサンスをどのように結びつけて、区の教育を展開させていくのか、そこら辺の点についてお答えをお願いしたいと思います。","respondent":"中島教育長","answer":"まさにこれは、教育ルネサンスの中でコミュニティ・スクールを実施する私たちの構想と合致するところであります。さらに、これからも教育のあり方を検討していくことも踏まえて、より良い品川区のあしたの教育をつくってまいりたいと考えます。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/307926?Template=document&Id=1066#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":132166,"voices":367}},{"id":"h29-20170317-7","meetingId":"h29-cm03","date":"2017年3月17日","dateIso":"2017-03-17","committee":"厚生委員会","time":"午後 ２時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"第３６号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第３６号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"横山委員","kind":"確認","question":"１点だけ確認したいことがあるのでお願いします。品川区も既に取り組みされているかと思うのですけれども、その辺について確認をお願いします。","respondent":"高森国保医療年金課長","answer":"２年に１回更新なのですけれども、１０月の時期に同封して、ジェネリックの医薬品のＰＲをしております。平成２７年度に計画を策定させていただいて平成２８年度から進めているのですけれども、さまざまな形で機会を通じて推進を図っているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからこの資料なのですけれども、国保運営協議会に出された資料と随分違う資料になっているというのはなぜなのでしょうか。なぜ国保運営協議会に出された資料からかなりのページを減らした資料になったのかを説明を求めました。","respondent":"高森国保医療年金課長","answer":"今日お出しした厚生委員会資料よりもかなり大きいものですけれども、必要な部分を抽出いたしまして、今回委員会資料として提示しています。それ以上の意味はございません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"加入世帯がどれぐらいいて、それが経年的にどういうふうに変化しているのかとかという、そういう推移はどこかに書かれているでしょうか。４０歳から６４歳までの方は、その介護納付金の所得割のパーセンテージですとか、そういうものの記載がありますか尋ねました。","respondent":"高森国保医療年金課長","answer":"次回以降については、また戻させていただいて、よりわかりやすい資料を作成のうえ、提案していきたいと考えています。そしてこの賦課割合、所得割率については、各区独自という形になっていますので、ここでは１.３９という所得割率になっているところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"制度の仕組みがわかるような形で説明してほしいというのが毎回国保運営協議会で出されていると思うのですけれども、ぜひしてほしいと求めました。資料と説明のことについてお願いします。","respondent":"高森国保医療年金課長","answer":"国保運営協議会の資料も変更するような動きもありますので、もう一度検討して、なるべく同じ形のものを出すように進めていきたいと考えております。先ほど来、この部分が残りの５０のところで保険者支援制度または保険料の軽減部分ということで入ってまいりまして、全体として。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２.３％減少するということでは書かれているのですけれども、これは何人から何人減ったのかというところをちょっと教えていただきたいのが１点です。なぜ５,０００円、１万円という額が拡大がされたのかということと、増えるとしたら何人ぐらい増えるのかということについても説明を求めました。","respondent":"高森国保医療年金課長","answer":"被保険者数ですが、全体の話で、２３区の話でよろしいですか。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"９８件、８６件というのは、今まで対象でなかった方が新たに対象になる世帯数ということで考えてよろしいか尋ねました。","respondent":"高森国保医療年金課長","answer":"５,１０３件だったのですけれども、これが５,２０１件、２割軽減４,６５７件が４,７４３件となります。ただ、この数字はあくまでも推定ですので、その旨ご理解いただければと思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうした場合に、１３億５,０００万円が１人当たりにしたらどれぐらいの値上げになるのかということを伺ったときには。予定だと思うのですけれども、その３３％というと、１７％と１６％みたいな感じに二等分するとそうなるではないか尋ねました。","respondent":"高森国保医療年金課長","answer":"一度変更していますので、おそらくそこは入れるという考え方と、かなり厳しくなるという考え方も出てるのかなと思います。それはまた改めて新たに検討するです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"せめて協会けんぽ並みに国保の負担割合を持っていってほしいというようなことを出していますね。その辺のところはどう考えられているのか尋ねました。","respondent":"高森国保医療年金課長","answer":"やはり２３区においては、すぐに何かちょっと具合悪いなと思えばすぐお医者さんにかかれるような医療環境というのも充実しているというのも事実です。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地方３団体代表の全国知事会、去年の１１月に緊急要望を出していますけれども、もうほとんど皆さんの認識になっているわけではないですか。そのように誰もが認める構造的な問題の解決の一助になるわけですから、ぜひそうすべきなのになぜそうしないのか。","respondent":"高森国保医療年金課長","answer":"そして残りの４分の１が区の負担ということで、一般会計に入ってあります。それは使っているといえば使っていることになるのかなと、この前さまざま考えたのですけれども、そのように考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらに財源措置をしてほしいという要望を出して、本来であれば４,０００円の繰り下げができることになるのに、それも引き下げに使わない。７,７５１円というのは、制度も破綻というふうなことになっていくのではないかと思うのですけれども、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"さまざまな形の医療水準が上がってきておりますので、そういう状況の中で、現在１万円という状況になってあります。医療水準が上がったことによって、さらに医療費が高額になったという状況もありますので、その辺のところもご理解いただきたいと思います。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"逆に増やしていただきたいということで、要望をします。基本的なことなのですけれども、そこのところ確認をさせてください。","respondent":"高森国保医療年金課長","answer":"３月に最終的に補正を行っている状況でございまして、保険料の関係でいけば、入っていないと考えてもらったらよろしいかと思います。入っていたらまたおかしくなってしまいますので。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、今回これで条例で決められて、この保険料と決まりましたら、それはいつどのように反映されるということなのか尋ねました。","respondent":"高森国保医療年金課長","answer":"さまざまな形で支出として、国保の会計のご説明しますと、それと同時に９月から保険料を賦課しまして３月までの間に被保険者の方から保険料いただく。最終では１１月、１２月ぐらいに実績に基づいて年度末までの見込みを出しまして、それに基づいて歳出額を調整するのです。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問","question":"薬剤師もそうですけれども、その点についてお伺いします。もう１点が１２ページなのですけれども、１人当たりの医療費が上がった、これはおよそ大体どこまで上がるのかというのは計算されているのか尋ねました。","respondent":"高森国保医療年金課長","answer":"１,８７１億５,９４１万円ほどというふうに見込んでおり、平成２８年から平成２９年で３％程度増額するという見込みになっていますので、これは今。","id":"exchange-013"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"なぜ政令は、このような動きになっているのか、その理由についてお伺いしたいのが２点目です。４点目は、年齢構成は４２％が６０歳以上の前期高齢者だということで、勤労している方はどれぐらいかなどはわかるのか尋ねました。","respondent":"高森国保医療年金課長","answer":"均等割の率というのが微妙にずれてまいりまして過去において、平成２７年度は６０対４０とか、そのようにご理解いただければというふうに思います。","id":"exchange-014"},{"speaker":"安藤副委員長","kind":"質問","question":"そちらもお伺いします。あるべき保険料水準を議論すべき」と述べておりまして、なぜこれを、あわせてお伺いしたいと思います。","respondent":"高森国保医療年金課長","answer":"均等割が２割程度上がっていくのかなという状況でありますので、５８：４２というのを、今特別区のほうでは採用しています。保険者の財政支援ということで、それを踏まえて保険者の財政支援を行うのだということで、１,７００億円余が投入されたと聞いてあります。","id":"exchange-015"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"中心は、保険料を下げるために使わないとこの提言の趣旨には合わないのではないですかという意味でお伺いしたので、もう一度お伺いしたいと思います。そこら辺大事な点なので、実際にどのように個々のケースを把握しているのかというのをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"安藤副委員長","kind":"質問","question":"品川区で財政的に一般財源からの投入で具体的に危機だという状況があるのかどうか、そこら辺はどうなのでしょうか。私はしっかりと保険料を下げるためにこのお金は充てるべきだと思いますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"委員が自由に発言をし、質問もできるという場ですから、そういう形で抑えるというやり方はちょっと。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年の平成２８年の１２月２６日に、区長会で、国保について、先ほども課長からありました特別区の緊急要望が出されています。２０１８年度予算からとなって、そして品川区では、このペナルティというところはどういう状況になっているのかということも説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"渡部委員長","kind":"質問","question":"２点目に区の一般財源の投入の話ですけれども、それに対して答弁いただけないと判断して進めておりますので、ご了承ください。答弁お願いします。","respondent":"高森国保医療年金課長","answer":"そのうちの３つ目に「子育て世帯の経済的負担の軽減のため、出てあります。子育て支援の関係の課で、いわゆる国の方針とはずれているという形で、確かそういう話になっているかと思います。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、そこのところのペナルティで出されているのが、品川区ではどの程度なのかということについて、先ほどお聞きしましたのでご答弁お願いいたします。","respondent":"高森国保医療年金課長","answer":"申し訳ございません。私のほうでは、今その資料を持ちあわせてございません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ求めていただきたいのと、子育て世代にとっては、特に国保が大変だという。そういうふうな制度を検討すべきなのではないかなと思うのですけれども、そういう制度の検討というところでは出ていないのか、説明を求めました。","respondent":"高森国保医療年金課長","answer":"いわゆる大人も子どもも均等割については同額だという形になっていますから、そこが変わらなければなりません。２３区だけでそういう形のことを、さまざまな形での指導が入ると認識していますので、現状ではそれについてはできないです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはり、区民の実態というのを、一番つかんでいらっしゃるのは、地方自治体である品川区です。多子世帯の減免というのは、ぜひともそういう制度を要望として上げていただきたいなと思うのですが、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"先ほど、特別区長会で出ているということで、やはり子育て世代の負担軽減ということが、厚生労働省のほうに出ていますので、こういうことは必要に応じて、また進めていきたいと考えています。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"確認させていただきたいのが、滞納繰越分の収納率、滞納繰越分収納の伸び率です。この報奨金は１億を大きく超えるかなという思いがしているのですけれども、例えば平成２７年の収納率が８９.３６％でいいのか尋ねました。","respondent":"高森国保医療年金課長","answer":"そのとおりです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"多分平成２６年が８７.１９％で、平成２７年が８９.３６％ということで、その点を確認だけさせていだきたい。平成２６年が４０.３２％なので、１０.５８％ということでいいのか、そのことの確認だけさせてください。","respondent":"高森国保医療年金課長","answer":"そのとおりです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"滞納繰越分の伸び率で２,０００万円。１億６,５００万円が取組み別成績交付算定表からもとめられる交付額になるのではないかなと思うのですけれどもいかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"それと、差し押さえ割合に対する交付というのが３００万円ありますから、平成２８年度の交付見込み額につきまして１億６,８００万円です。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"わかりました。改めて１億６,８００万円ということで確認をさせていただいていいでしょうかということで、確認です、お願いします。","respondent":"高森国保医療年金課長","answer":"本会議の質問のときには確定通知が来ておりませんでしたので、お知らせすることはできなかったという状況です。現在は確定通知が来てあります。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"もう限界に来ているということが、３首長会の中でも確認されているにもかかわらず、さらに大幅な値上げになったということ。本当にこの苛酷な取り立てと、それから高い保険料の条例ですので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374035?Template=document&Id=3472#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26559,"voices":82}}]);
